INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_L05_basic#8','math',5,2,'u1','L05','g5_2_math_u1_L05_basic','lesson_basic','M5-2-u1-C4',2,'mc','auto','2500을 올림하여 백의 자리까지 나타내면 얼마인가요?',ARRAY['M5-2-u1-X07','M5-2-u1-X09','M5-2-u1-X12']::text[],true,'{"seq":8,"concept":"M5-2-u1-C4","difficulty":2,"kind":"mc","stem":"2500을 올림하여 백의 자리까지 나타내면 얼마인가요?","options":[{"t":"2500","correct":true},{"t":"2600","mis":"M5-2-u1-X07"},{"t":"3000","mis":"M5-2-u1-X09"},{"t":"25","mis":"M5-2-u1-X12"}],"explanation":["올림은 구하려는 자리 아래 수를 올려요.","그런데 백의 자리 아래가 00이라 올릴 것이 없어요.","그대로 2500이에요."],"variant_rule":{"alt":[{"stem":"7000을 올림하여 천의 자리까지 나타내면 얼마인가요?","options":[{"t":"7000","correct":true},{"t":"8000","mis":"M5-2-u1-X07"},{"t":"10000","mis":"M5-2-u1-X09"},{"t":"7","mis":"M5-2-u1-X12"}],"explanation":["올림은 구하려는 자리 아래 수를 올려요.","그런데 천의 자리 아래가 000이라 올릴 것이 없어요.","그대로 7000이에요."]},{"stem":"3600을 올림하여 백의 자리까지 나타내면 얼마인가요?","options":[{"t":"3600","correct":true},{"t":"3700","mis":"M5-2-u1-X07"},{"t":"4000","mis":"M5-2-u1-X09"},{"t":"36","mis":"M5-2-u1-X12"}],"explanation":["올림은 구하려는 자리 아래 수를 올려요.","그런데 백의 자리 아래가 00이라 올릴 것이 없어요.","그대로 3600이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_L05_basic#9','math',5,2,'u1','L05','g5_2_math_u1_L05_basic','lesson_basic','M5-2-u1-C4',2,'ox','auto','올림할 때 구하려는 자리 아래 수가 모두 0이면 올리지 않고 그대로 써요.',ARRAY['M5-2-u1-X07']::text[],true,'{"seq":9,"concept":"M5-2-u1-C4","difficulty":2,"kind":"ox","stem":"올림할 때 구하려는 자리 아래 수가 모두 0이면 올리지 않고 그대로 써요.","answer":"O","reason_options":[{"t":"아래 수가 모두 0이면 올릴 것이 없어 이미 모자라지 않아서","correct":true},{"t":"올림은 언제나 한 칸 올리는 방법이라서","mis":"M5-2-u1-X07"}],"mis":"M5-2-u1-X07","explanation":["올림은 모자라지 않게 하려고 아래 수를 올려요.","아래가 모두 0이면 이미 딱 맞아 모자라지 않아요.","예: 2500을 올림하여 백의 자리까지 → 2500이에요."],"variant_rule":{"alt":[{"stem":"6000을 올림하여 천의 자리까지 나타내면 7000이에요.","answer":"X","reason_options":[{"t":"천의 자리 아래가 000이라 올릴 것이 없어 6000 그대로라서","correct":true},{"t":"올림은 언제나 한 칸 올리는 방법이라서","mis":"M5-2-u1-X07"}],"explanation":["6000에서 천의 자리 아래는 000이에요.","올릴 것이 없으니 그대로예요.","6000 → 6000이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_L05_basic#10','math',5,2,'u1','L05','g5_2_math_u1_L05_basic','lesson_basic','M5-2-u1-C4',3,'mc','auto','올림하여 십의 자리까지 나타내면 230이 되는 자연수 중에서 가장 큰 수는 얼마인가요?',ARRAY['M5-2-u1-X15','M5-2-u1-X08']::text[],true,'{"seq":10,"concept":"M5-2-u1-C4","difficulty":3,"kind":"mc","stem":"올림하여 십의 자리까지 나타내면 230이 되는 자연수 중에서 가장 큰 수는 얼마인가요?","options":[{"t":"230","correct":true},{"t":"229","mis":"M5-2-u1-X15"},{"t":"234","mis":"M5-2-u1-X08"},{"t":"239","mis":"M5-2-u1-X15"}],"explanation":["221부터 229까지는 올림하면 230이 돼요.","230은 아래 수가 0이라 그대로 230이에요.","231부터는 240이 되니 가장 큰 수는 230이에요."],"variant_rule":{"alt":[{"stem":"올림하여 십의 자리까지 나타내면 230이 되는 자연수 중에서 가장 작은 수는 얼마인가요?","options":[{"t":"221","correct":true},{"t":"220","mis":"M5-2-u1-X07"},{"t":"225","mis":"M5-2-u1-X08"},{"t":"229","mis":"M5-2-u1-X17"}],"explanation":["220은 아래 수가 0이라 올림해도 220이에요.","221은 아래 수 1을 올려 230이 돼요.","그래서 가장 작은 수는 221이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_L05_challenge#1','math',5,2,'u1','L05','g5_2_math_u1_L05_challenge','lesson_challenge','M5-2-u1-C4',2,'mc','auto','4.521을 올림하여 소수 첫째 자리까지 나타내면 얼마인가요?',ARRAY['M5-2-u1-X08','M5-2-u1-X09']::text[],true,'{"seq":1,"concept":"M5-2-u1-C4","difficulty":2,"kind":"mc","stem":"4.521을 올림하여 소수 첫째 자리까지 나타내면 얼마인가요?","options":[{"t":"4.6","correct":true},{"t":"4.5","mis":"M5-2-u1-X08"},{"t":"4.53","mis":"M5-2-u1-X09"},{"t":"5","mis":"M5-2-u1-X09"}],"explanation":["올림은 소수 첫째 자리 아래 수(0.021)을 올려서 나타내요.","아래 숫자가 무엇이든 0이 아니면 한 칸 올리고, 아래는 0으로 채워요.","4.521 → 4.6이에요."],"variant_rule":{"alt":[{"stem":"7.805를 올림하여 소수 둘째 자리까지 나타내면 얼마인가요?","options":[{"t":"7.81","correct":true},{"t":"7.80","mis":"M5-2-u1-X08"},{"t":"7.85","mis":"M5-2-u1-X09"},{"t":"7.9","mis":"M5-2-u1-X09"}],"explanation":["올림은 소수 둘째 자리 아래 수(0.005)를 올려서 나타내요.","아래 숫자가 무엇이든 0이 아니면 한 칸 올리고, 아래는 0으로 채워요.","7.805 → 7.81이에요."]},{"stem":"12.3을 올림하여 일의 자리까지 나타내면 얼마인가요?","options":[{"t":"13","correct":true},{"t":"12","mis":"M5-2-u1-X08"},{"t":"20","mis":"M5-2-u1-X09"},{"t":"14","mis":"M5-2-u1-X16"}],"explanation":["올림은 일의 자리 아래 수(0.3)을 올려서 나타내요.","아래 숫자가 무엇이든 0이 아니면 한 칸 올리고, 아래는 0으로 채워요.","12.3 → 13이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_L05_challenge#2','math',5,2,'u1','L05','g5_2_math_u1_L05_challenge','lesson_challenge','M5-2-u1-C4',2,'sa','auto','학생 543명에게 친환경 가방을 1개씩 나누어 주려고 해요. 가방이 100개 묶음으로만 판다면 최소 몇 묶음을 사야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M5-2-u1-C4","difficulty":2,"kind":"sa","stem":"학생 543명에게 친환경 가방을 1개씩 나누어 주려고 해요. 가방이 100개 묶음으로만 판다면 최소 몇 묶음을 사야 하나요? 숫자로 쓰세요.","answer":["6","6묶음"],"explanation":["5묶음은 500개라 543명에게 모자라요.","모자라면 안 되니 543을 올림하여 백의 자리까지 → 600개예요.","600개는 100개 묶음 6묶음이에요."],"variant_rule":{"alt":[{"stem":"학생 278명에게 공책을 1권씩 주려고 해요. 공책이 10권 묶음으로만 판다면 최소 몇 묶음을 사야 하나요? 숫자로 쓰세요.","answer":["28","28묶음"],"explanation":["27묶음은 270권이라 모자라요.","278을 올림하여 십의 자리까지 → 280권이에요.","280권은 10권 묶음 28묶음이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_L05_challenge#3','math',5,2,'u1','L05','g5_2_math_u1_L05_challenge','lesson_challenge','M5-2-u1-C4',3,'mc','auto','올림하여 백의 자리까지 나타내면 3700이 되는 자연수의 범위로 알맞은 것은 어느 것인가요?',ARRAY['M5-2-u1-X07','M5-2-u1-X08','M5-2-u1-X15']::text[],true,'{"seq":3,"concept":"M5-2-u1-C4","difficulty":3,"kind":"mc","stem":"올림하여 백의 자리까지 나타내면 3700이 되는 자연수의 범위로 알맞은 것은 어느 것인가요?","options":[{"t":"3600 초과 3700 이하","correct":true},{"t":"3600 이상 3700 이하","mis":"M5-2-u1-X07"},{"t":"3650 이상 3750 미만","mis":"M5-2-u1-X08"},{"t":"3700 이상 3800 미만","mis":"M5-2-u1-X15"}],"explanation":["3600은 아래 수가 00이라 올림해도 3600 — 빠져요.","3601부터 3700까지는 올림하면 3700이에요.","그래서 3600 초과 3700 이하예요."],"variant_rule":{"alt":[{"stem":"올림하여 십의 자리까지 나타내면 80이 되는 자연수의 범위로 알맞은 것은 어느 것인가요?","options":[{"t":"70 초과 80 이하","correct":true},{"t":"70 이상 80 이하","mis":"M5-2-u1-X07"},{"t":"75 이상 85 미만","mis":"M5-2-u1-X08"},{"t":"80 이상 90 미만","mis":"M5-2-u1-X15"}],"explanation":["70은 올림해도 70 — 빠져요.","71부터 80까지가 80이 돼요.","그래서 70 초과 80 이하예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_L05_challenge#4','math',5,2,'u1','L05','g5_2_math_u1_L05_challenge','lesson_challenge','M5-2-u1-C4',3,'mc','auto','학생 136명이 45인승 버스를 타고 현장 체험 학습을 가요. 모두 타려면 버스는 최소 몇 대가 필요한가요?',ARRAY['M5-2-u1-X13','M5-2-u1-X16']::text[],true,'{"seq":4,"concept":"M5-2-u1-C4","difficulty":3,"kind":"mc","stem":"학생 136명이 45인승 버스를 타고 현장 체험 학습을 가요. 모두 타려면 버스는 최소 몇 대가 필요한가요?","options":[{"t":"4대","correct":true},{"t":"3대","mis":"M5-2-u1-X13"},{"t":"5대","mis":"M5-2-u1-X16"},{"t":"2대","mis":"M5-2-u1-X16"}],"explanation":["버스 3대에는 45 × 3 = 135명까지 탈 수 있어요.","136명은 1명이 남으니 한 대가 더 있어야 해요.","모자라면 안 되니 올림 — 4대예요."],"variant_rule":{"alt":[{"stem":"사과 250개를 한 상자에 40개씩 담아요. 사과를 모두 담으려면 상자는 최소 몇 개가 필요한가요?","options":[{"t":"7개","correct":true},{"t":"6개","mis":"M5-2-u1-X13"},{"t":"8개","mis":"M5-2-u1-X16"},{"t":"25개","mis":"M5-2-u1-X14"}],"explanation":["상자 6개에는 40 × 6 = 240개까지 담겨요.","10개가 남으니 상자가 하나 더 있어야 해요.","남김없이 담으려면 7개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_L05_challenge#5','math',5,2,'u1','L05','g5_2_math_u1_L05_challenge','lesson_challenge','M5-2-u1-C4',3,'error','auto','친구들이 올림을 했어요. 잘못한 친구는 누구인가요?',ARRAY['M5-2-u1-X08','M5-2-u1-X17']::text[],true,'{"seq":5,"concept":"M5-2-u1-C4","difficulty":3,"kind":"error","stem":"친구들이 올림을 했어요. 잘못한 친구는 누구인가요?","options":[{"t":"라희 — 「2.003을 올림하여 소수 첫째 자리까지 나타내면 2.0이야.」","correct":true,"mis_target":"M5-2-u1-X08"},{"t":"도윤 — 「2.003을 올림하여 일의 자리까지 나타내면 3이야.」","mis":"M5-2-u1-X17"},{"t":"세은 — 「2.003을 올림하여 소수 둘째 자리까지 나타내면 2.01이야.」","mis":"M5-2-u1-X17"}],"explanation":["올림은 아래 수가 아무리 작아도 0이 아니면 올려요.","2.003의 소수 첫째 자리 아래 0.003도 올려 2.1이에요.","라희는 작다고 버렸어요 — 반올림처럼 했어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 친구들이 올림을 했어요. 잘못한 친구는 누구인가요?","options":[{"t":"하준 — 「8001을 올림하여 천의 자리까지 나타내면 8000이야.」","correct":true,"mis_target":"M5-2-u1-X08"},{"t":"미루 — 「8001을 올림하여 십의 자리까지 나타내면 8010이야.」","mis":"M5-2-u1-X17"},{"t":"지안 — 「8001을 올림하여 백의 자리까지 나타내면 8100이야.」","mis":"M5-2-u1-X17"}],"explanation":["8001에서 천의 자리 아래 001은 0이 아니에요.","그래서 올려 9000이에요.","하준이는 작다고 버렸어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_L05_challenge#6','math',5,2,'u1','L05','g5_2_math_u1_L05_challenge','lesson_challenge','M5-2-u1-C4',3,'mc','auto','수 카드 4, 7, 2, 9를 한 번씩만 써서 가장 작은 네 자리 수를 만들었어요. 그 수를 올림하여 백의 자리까지 나타내면 얼마인가요?',ARRAY['M5-2-u1-X08','M5-2-u1-X09']::text[],true,'{"seq":6,"concept":"M5-2-u1-C4","difficulty":3,"kind":"mc","stem":"수 카드 4, 7, 2, 9를 한 번씩만 써서 가장 작은 네 자리 수를 만들었어요. 그 수를 올림하여 백의 자리까지 나타내면 얼마인가요?","options":[{"t":"2500","correct":true},{"t":"2400","mis":"M5-2-u1-X08"},{"t":"2480","mis":"M5-2-u1-X09"},{"t":"3000","mis":"M5-2-u1-X09"}],"explanation":["가장 작은 네 자리 수는 작은 숫자부터 — 2479예요.","백의 자리 아래 79를 올려요.","2479 → 2500이에요."],"variant_rule":{"alt":[{"stem":"수 카드 3, 6, 1, 8을 한 번씩만 써서 가장 큰 네 자리 수를 만들었어요. 그 수를 올림하여 십의 자리까지 나타내면 얼마인가요?","options":[{"t":"8640","correct":true},{"t":"8630","mis":"M5-2-u1-X08"},{"t":"8700","mis":"M5-2-u1-X09"},{"t":"9000","mis":"M5-2-u1-X09"}],"explanation":["가장 큰 네 자리 수는 큰 숫자부터 — 8631이에요.","십의 자리 아래 1을 올려요.","8631 → 8640이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_L05_challenge#7','math',5,2,'u1','L05','g5_2_math_u1_L05_challenge','lesson_challenge','M5-2-u1-C4',3,'mc','auto','4301, 4399, 4300, 4350을 각각 올림하여 백의 자리까지 나타냈어요. 결과가 다른 하나는 어느 것인가요?',ARRAY['M5-2-u1-X17']::text[],true,'{"seq":7,"concept":"M5-2-u1-C4","difficulty":3,"kind":"mc","stem":"4301, 4399, 4300, 4350을 각각 올림하여 백의 자리까지 나타냈어요. 결과가 다른 하나는 어느 것인가요?","options":[{"t":"4300","correct":true},{"t":"4301","mis":"M5-2-u1-X17"},{"t":"4399","mis":"M5-2-u1-X17"},{"t":"4350","mis":"M5-2-u1-X17"}],"explanation":["4301·4399·4350은 백의 자리 아래가 0이 아니라 올려 4400이에요.","4300은 아래가 00이라 그대로 4300이에요.","그래서 다른 하나는 4300이에요."],"variant_rule":{"alt":[{"stem":"5.10, 5.11, 5.19, 5.15를 각각 올림하여 소수 첫째 자리까지 나타냈어요. 결과가 다른 하나는 어느 것인가요?","options":[{"t":"5.10","correct":true},{"t":"5.11","mis":"M5-2-u1-X17"},{"t":"5.19","mis":"M5-2-u1-X17"},{"t":"5.15","mis":"M5-2-u1-X17"}],"explanation":["5.11·5.19·5.15는 소수 첫째 자리 아래가 0이 아니라 올려 5.2예요.","5.10은 아래가 0이라 그대로 5.1이에요.","그래서 다른 하나는 5.10이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_L05_challenge#8','math',5,2,'u1','L05','g5_2_math_u1_L05_challenge','lesson_challenge','M5-2-u1-C4',4,'essay','teacher','학생 543명에게 가방을 1개씩 주려고 10개 묶음으로 사요. 54묶음이 아니라 55묶음을 사야 하는 까닭을 쓰고, 이것이 543을 어떻게 어림한 것인지 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"M5-2-u1-C4","difficulty":4,"kind":"essay","stem":"학생 543명에게 가방을 1개씩 주려고 10개 묶음으로 사요. 54묶음이 아니라 55묶음을 사야 하는 까닭을 쓰고, 이것이 543을 어떻게 어림한 것인지 쓰세요.","answer_guide":{"answer":"예: 54묶음은 540개라 3명이 받지 못해 모자란다. 모자라면 안 되니 55묶음 550개를 사야 한다. 이것은 543을 올림하여 십의 자리까지 나타낸 것이다.","scoring_points":["54묶음이면 모자람을 썼는가","55묶음(550개)이 필요함을 썼는가","543을 올림하여 십의 자리까지 나타낸 것임을 썼는가"]},"explanation":["54묶음은 540개 — 3명이 못 받아요.","모자라면 안 되니 55묶음이에요.","543을 올림하여 십의 자리까지 → 550이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_L05_challenge#9','math',5,2,'u1','L05','g5_2_math_u1_L05_challenge','lesson_challenge','M5-2-u1-C4',4,'essay','teacher','2500을 올림하여 백의 자리까지 나타내면 2600이라고 답한 친구가 있어요. 친구의 답이 맞는지 판단하고, 올림의 뜻을 들어 까닭을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"M5-2-u1-C4","difficulty":4,"kind":"essay","stem":"2500을 올림하여 백의 자리까지 나타내면 2600이라고 답한 친구가 있어요. 친구의 답이 맞는지 판단하고, 올림의 뜻을 들어 까닭을 쓰세요.","answer_guide":{"answer":"예: 틀리다. 올림은 구하려는 자리 아래 수를 올리는 것인데 2500은 백의 자리 아래가 00이라 올릴 것이 없다. 이미 모자라지 않으므로 그대로 2500이다.","scoring_points":["틀렸다고 판단했는가","백의 자리 아래가 00이라 올릴 것이 없음을 썼는가","바른 답 2500을 썼는가"]},"explanation":["2500의 백의 자리 아래는 00이에요.","올릴 것이 없으니 그대로예요.","바른 답은 2500이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_L05_challenge#10','math',5,2,'u1','L05','g5_2_math_u1_L05_challenge','lesson_challenge','M5-2-u1-C4',4,'mc','auto','올림하여 십의 자리까지 나타내면 70이 되는 자연수는 모두 몇 개인가요?',ARRAY['M5-2-u1-X07','M5-2-u1-X15','M5-2-u1-X08']::text[],true,'{"seq":10,"concept":"M5-2-u1-C4","difficulty":4,"kind":"mc","stem":"올림하여 십의 자리까지 나타내면 70이 되는 자연수는 모두 몇 개인가요?","options":[{"t":"10개","correct":true},{"t":"9개","mis":"M5-2-u1-X07"},{"t":"11개","mis":"M5-2-u1-X15"},{"t":"5개","mis":"M5-2-u1-X08"}],"explanation":["61부터 69까지는 올림하면 70이 돼요 — 9개예요.","70은 아래 수가 0이라 그대로 70 — 들어가요.","60은 그대로 60이라 빠지니 61부터 70까지 10개예요."],"variant_rule":{"alt":[{"stem":"올림하여 백의 자리까지 나타내면 400이 되는 자연수는 모두 몇 개인가요?","options":[{"t":"100개","correct":true},{"t":"99개","mis":"M5-2-u1-X07"},{"t":"101개","mis":"M5-2-u1-X15"},{"t":"50개","mis":"M5-2-u1-X08"}],"explanation":["301부터 399까지는 올림하면 400이에요 — 99개예요.","400은 그대로 400이라 들어가요.","300은 빠지니 301부터 400까지 100개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_L06_basic#1','math',5,2,'u1','L06','g5_2_math_u1_L06_basic','lesson_basic','M5-2-u1-C5',1,'mc','auto','곤충으로 만든 과자 657개를 10개씩 포장해요. 포장할 수 있는 과자는 최대 몇 개인가요?',ARRAY['M5-2-u1-X13','M5-2-u1-X14','M5-2-u1-X09']::text[],true,'{"seq":1,"concept":"M5-2-u1-C5","difficulty":1,"kind":"mc","stem":"곤충으로 만든 과자 657개를 10개씩 포장해요. 포장할 수 있는 과자는 최대 몇 개인가요?","options":[{"t":"650개","correct":true},{"t":"660개","mis":"M5-2-u1-X13"},{"t":"65개","mis":"M5-2-u1-X14"},{"t":"600개","mis":"M5-2-u1-X09"}],"explanation":["10개씩 66묶음을 만들려면 660개가 있어야 해서 모자라요.","65묶음 — 650개까지 포장하고 남는 7개는 포장하지 못해요.","657을 버림하여 십의 자리까지 나타낸 650개예요."],"variant_rule":{"alt":[{"stem":"곤충으로 만든 과자 657개를 100개씩 포장해요. 포장할 수 있는 과자는 최대 몇 개인가요?","options":[{"t":"600개","correct":true},{"t":"700개","mis":"M5-2-u1-X13"},{"t":"6개","mis":"M5-2-u1-X14"},{"t":"657개","mis":"M5-2-u1-X17"}],"explanation":["100개씩 7묶음을 만들려면 700개가 있어야 해서 모자라요.","6묶음 — 600개까지 포장하고 남는 57개는 포장하지 못해요.","657을 버림하여 백의 자리까지 나타낸 600개예요."]},{"stem":"곤충으로 만든 과자 1284개를 10개씩 포장해요. 포장할 수 있는 과자는 최대 몇 개인가요?","options":[{"t":"1280개","correct":true},{"t":"1290개","mis":"M5-2-u1-X13"},{"t":"128개","mis":"M5-2-u1-X14"},{"t":"1200개","mis":"M5-2-u1-X09"}],"explanation":["10개씩 129묶음을 만들려면 1290개가 있어야 해서 모자라요.","128묶음 — 1280개까지 포장하고 남는 4개는 포장하지 못해요.","1284를 버림하여 십의 자리까지 나타낸 1280개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
