INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_L06_basic#5','math',5,2,'u1','L06','g5_2_math_u1_L06_basic','lesson_basic','M5-2-u1-C5',2,'sa','auto','과수원에서 딴 단감 4953개를 한 상자에 100개씩 포장해요. 포장한 상자는 최대 몇 상자인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M5-2-u1-C5","difficulty":2,"kind":"sa","stem":"과수원에서 딴 단감 4953개를 한 상자에 100개씩 포장해요. 포장한 상자는 최대 몇 상자인가요? 숫자로 쓰세요.","answer":["49","49상자"],"explanation":["100개가 다 차야 한 상자가 돼요.","4953을 버림하여 백의 자리까지 → 4900개예요.","4900개는 100개씩 49상자예요. 남는 53개는 상자를 채우지 못해요."],"variant_rule":{"alt":[{"stem":"과자 657개를 10개씩 포장해요. 포장한 봉지는 최대 몇 봉지인가요? 숫자로 쓰세요.","answer":["65","65봉지"],"explanation":["10개가 다 차야 한 봉지예요.","657을 버림하여 십의 자리까지 → 650개예요.","650개는 10개씩 65봉지예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_L06_basic#6','math',5,2,'u1','L06','g5_2_math_u1_L06_basic','lesson_basic','M5-2-u1-C5',2,'mc','auto','수 카드 3, 6, 1, 7을 한 번씩만 써서 가장 큰 네 자리 수를 만들었어요. 그 수를 버림하여 십의 자리까지 나타내면 얼마인가요?',ARRAY['M5-2-u1-X08','M5-2-u1-X09','M5-2-u1-X12']::text[],true,'{"seq":6,"concept":"M5-2-u1-C5","difficulty":2,"kind":"mc","stem":"수 카드 3, 6, 1, 7을 한 번씩만 써서 가장 큰 네 자리 수를 만들었어요. 그 수를 버림하여 십의 자리까지 나타내면 얼마인가요?","options":[{"t":"7630","correct":true},{"t":"7640","mis":"M5-2-u1-X08"},{"t":"7600","mis":"M5-2-u1-X09"},{"t":"763","mis":"M5-2-u1-X12"}],"explanation":["가장 큰 네 자리 수는 큰 숫자부터 — 7631이에요.","십의 자리 아래 1을 버려요.","7631 → 7630이에요."],"variant_rule":{"alt":[{"stem":"수 카드 5, 2, 8, 4를 한 번씩만 써서 가장 큰 네 자리 수를 만들었어요. 그 수를 버림하여 백의 자리까지 나타내면 얼마인가요?","options":[{"t":"8500","correct":true},{"t":"8600","mis":"M5-2-u1-X08"},{"t":"8540","mis":"M5-2-u1-X09"},{"t":"85","mis":"M5-2-u1-X12"}],"explanation":["가장 큰 네 자리 수는 8542예요.","백의 자리 아래 42를 버려요.","8542 → 8500이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_L06_basic#7','math',5,2,'u1','L06','g5_2_math_u1_L06_basic','lesson_basic','M5-2-u1-C5',2,'mc','auto','도서관에서 책을 10권 읽을 때마다 공책 한 권을 줘요. 책을 27권 읽었다면 공책을 몇 권 받나요?',ARRAY['M5-2-u1-X13','M5-2-u1-X16']::text[],true,'{"seq":7,"concept":"M5-2-u1-C5","difficulty":2,"kind":"mc","stem":"도서관에서 책을 10권 읽을 때마다 공책 한 권을 줘요. 책을 27권 읽었다면 공책을 몇 권 받나요?","options":[{"t":"2권","correct":true},{"t":"3권","mis":"M5-2-u1-X13"},{"t":"7권","mis":"M5-2-u1-X16"},{"t":"1권","mis":"M5-2-u1-X16"}],"explanation":["10권을 다 채워야 공책 한 권이에요.","27권은 10권 묶음이 2개 — 남는 7권은 공책이 되지 못해요.","27을 버림하여 십의 자리까지 → 20이라 2권이에요."],"variant_rule":{"alt":[{"stem":"도장을 10개 모을 때마다 연필 한 자루를 줘요. 도장을 46개 모았다면 연필을 몇 자루 받나요?","options":[{"t":"4자루","correct":true},{"t":"5자루","mis":"M5-2-u1-X13"},{"t":"6자루","mis":"M5-2-u1-X16"},{"t":"46자루","mis":"M5-2-u1-X14"}],"explanation":["10개를 다 채워야 연필 한 자루예요.","46개는 10개 묶음이 4개 — 남는 6개는 버려요.","46을 버림하여 십의 자리까지 → 40이라 4자루예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_L06_basic#8','math',5,2,'u1','L06','g5_2_math_u1_L06_basic','lesson_basic','M5-2-u1-C5',2,'ox','auto','버림은 구하려는 자리 아래 숫자가 9여도 버려요.',ARRAY['M5-2-u1-X08']::text[],true,'{"seq":8,"concept":"M5-2-u1-C5","difficulty":2,"kind":"ox","stem":"버림은 구하려는 자리 아래 숫자가 9여도 버려요.","answer":"O","reason_options":[{"t":"버림은 아래 수가 어떤 수인지에 관계없이 모두 버리는 방법이라서","correct":true},{"t":"아래 숫자가 5 이상이면 올려야 해서","mis":"M5-2-u1-X08"}],"mis":"M5-2-u1-X08","explanation":["버림은 아래 수를 보고 판단하지 않아요.","9든 1이든 모두 버려요.","예: 6.89를 버림하여 소수 첫째 자리까지 → 6.8이에요."],"variant_rule":{"alt":[{"stem":"버림하여 나타낸 수는 원래 수보다 커질 수 있어요.","answer":"X","reason_options":[{"t":"아래 수를 버리기만 하니 원래 수와 같거나 작아져서","correct":true},{"t":"버림도 아래 숫자가 크면 올려서","mis":"M5-2-u1-X08"}],"explanation":["버림은 아래 수를 덜어 내기만 해요.","그래서 원래 수보다 커지지 않아요.","아래가 모두 0일 때만 원래 수와 같아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_L06_basic#9','math',5,2,'u1','L06','g5_2_math_u1_L06_basic','lesson_basic','M5-2-u1-C5',2,'mc','auto','다음 중 버림으로 어림하기에 알맞은 상황은 어느 것인가요?',ARRAY['M5-2-u1-X13']::text[],false,'{"seq":9,"concept":"M5-2-u1-C5","difficulty":2,"kind":"mc","stem":"다음 중 버림으로 어림하기에 알맞은 상황은 어느 것인가요?","options":[{"t":"과자를 10개씩 포장할 때 포장할 수 있는 과자 수 구하기","correct":true},{"t":"학생 모두에게 가방을 주려고 10개 묶음으로 살 가방 수 구하기","mis":"M5-2-u1-X13"},{"t":"도시 인구를 실제와 가깝게 그래프로 나타내기","mis":"M5-2-u1-X13"},{"t":"11200원짜리 필통을 지폐로만 낼 돈 구하기","mis":"M5-2-u1-X13"}],"explanation":["버림은 남는 것을 쓸 수 없을 때 써요.","10개를 채우지 못한 과자는 포장할 수 없어 버려요.","가방 사기·필통값 내기는 올림, 인구 그래프는 반올림이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_L06_basic#10','math',5,2,'u1','L06','g5_2_math_u1_L06_basic','lesson_basic','M5-2-u1-C5',3,'mc','auto','버림하여 백의 자리까지 나타내면 3700이 되는 자연수의 범위로 알맞은 것은 어느 것인가요?',ARRAY['M5-2-u1-X08','M5-2-u1-X15']::text[],true,'{"seq":10,"concept":"M5-2-u1-C5","difficulty":3,"kind":"mc","stem":"버림하여 백의 자리까지 나타내면 3700이 되는 자연수의 범위로 알맞은 것은 어느 것인가요?","options":[{"t":"3700 이상 3800 미만","correct":true},{"t":"3600 초과 3700 이하","mis":"M5-2-u1-X08"},{"t":"3650 이상 3750 미만","mis":"M5-2-u1-X08"},{"t":"3700 초과 3800 이하","mis":"M5-2-u1-X15"}],"explanation":["3700은 버림해도 3700 — 들어가요.","3701부터 3799까지도 아래 수를 버려 3700이에요.","3800은 그대로 3800이라 빠지니 3700 이상 3800 미만이에요."],"variant_rule":{"alt":[{"stem":"버림하여 십의 자리까지 나타내면 80이 되는 자연수의 범위로 알맞은 것은 어느 것인가요?","options":[{"t":"80 이상 90 미만","correct":true},{"t":"70 초과 80 이하","mis":"M5-2-u1-X08"},{"t":"75 이상 85 미만","mis":"M5-2-u1-X08"},{"t":"80 초과 90 이하","mis":"M5-2-u1-X15"}],"explanation":["80은 버림해도 80 — 들어가요.","81부터 89까지도 80이 돼요.","90은 빠지니 80 이상 90 미만이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_L06_challenge#1','math',5,2,'u1','L06','g5_2_math_u1_L06_challenge','lesson_challenge','M5-2-u1-C5',2,'mc','auto','5.639를 버림하여 소수 둘째 자리까지 나타내면 얼마인가요?',ARRAY['M5-2-u1-X08','M5-2-u1-X09','M5-2-u1-X16']::text[],true,'{"seq":1,"concept":"M5-2-u1-C5","difficulty":2,"kind":"mc","stem":"5.639를 버림하여 소수 둘째 자리까지 나타내면 얼마인가요?","options":[{"t":"5.63","correct":true},{"t":"5.64","mis":"M5-2-u1-X08"},{"t":"5.6","mis":"M5-2-u1-X09"},{"t":"5.65","mis":"M5-2-u1-X16"}],"explanation":["버림은 소수 둘째 자리 아래 수(0.009)를 어떤 수든 버려요.","버린 자리는 0으로 채우거나(자연수) 지워요(소수).","5.639 → 5.63이에요."],"variant_rule":{"alt":[{"stem":"9.098을 버림하여 소수 첫째 자리까지 나타내면 얼마인가요?","options":[{"t":"9.0","correct":true},{"t":"9.1","mis":"M5-2-u1-X08"},{"t":"9.9","mis":"M5-2-u1-X09"},{"t":"9.09","mis":"M5-2-u1-X09"}],"explanation":["버림은 소수 첫째 자리 아래 수(0.098)을 어떤 수든 버려요.","버린 자리는 0으로 채우거나(자연수) 지워요(소수).","9.098 → 9.0이에요."]},{"stem":"0.774를 버림하여 소수 둘째 자리까지 나타내면 얼마인가요?","options":[{"t":"0.77","correct":true},{"t":"0.78","mis":"M5-2-u1-X08"},{"t":"0.7","mis":"M5-2-u1-X09"},{"t":"0.79","mis":"M5-2-u1-X16"}],"explanation":["버림은 소수 둘째 자리 아래 수(0.004)를 어떤 수든 버려요.","버린 자리는 0으로 채우거나(자연수) 지워요(소수).","0.774 → 0.77이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_L06_challenge#2','math',5,2,'u1','L06','g5_2_math_u1_L06_challenge','lesson_challenge','M5-2-u1-C5',2,'mc','auto','저금통에 모은 동전이 모두 58600원이에요. 1000원짜리 지폐로 바꾸면 최대 얼마까지 바꿀 수 있나요?',ARRAY['M5-2-u1-X13','M5-2-u1-X09','M5-2-u1-X17']::text[],true,'{"seq":2,"concept":"M5-2-u1-C5","difficulty":2,"kind":"mc","stem":"저금통에 모은 동전이 모두 58600원이에요. 1000원짜리 지폐로 바꾸면 최대 얼마까지 바꿀 수 있나요?","options":[{"t":"58000원","correct":true},{"t":"59000원","mis":"M5-2-u1-X13"},{"t":"50000원","mis":"M5-2-u1-X09"},{"t":"58600원","mis":"M5-2-u1-X17"}],"explanation":["1000원이 다 차야 지폐 한 장이에요.","남는 600원은 지폐가 되지 못해요.","58600을 버림하여 천의 자리까지 → 58000원이에요."],"variant_rule":{"alt":[{"stem":"저금통에 모은 동전이 모두 37450원이에요. 10000원짜리 지폐로만 바꾸면 최대 얼마까지 바꿀 수 있나요?","options":[{"t":"30000원","correct":true},{"t":"40000원","mis":"M5-2-u1-X13"},{"t":"37000원","mis":"M5-2-u1-X09"},{"t":"37450원","mis":"M5-2-u1-X17"}],"explanation":["10000원이 다 차야 지폐 한 장이에요.","남는 7450원은 바꾸지 못해요.","37450을 버림하여 만의 자리까지 → 30000원이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_L06_challenge#3','math',5,2,'u1','L06','g5_2_math_u1_L06_challenge','lesson_challenge','M5-2-u1-C5',3,'mc','auto','6.79, 6.70, 6.71, 6.8을 각각 버림하여 소수 첫째 자리까지 나타냈어요. 결과가 다른 하나는 어느 것인가요?',ARRAY['M5-2-u1-X17']::text[],true,'{"seq":3,"concept":"M5-2-u1-C5","difficulty":3,"kind":"mc","stem":"6.79, 6.70, 6.71, 6.8을 각각 버림하여 소수 첫째 자리까지 나타냈어요. 결과가 다른 하나는 어느 것인가요?","options":[{"t":"6.8","correct":true},{"t":"6.79","mis":"M5-2-u1-X17"},{"t":"6.70","mis":"M5-2-u1-X17"},{"t":"6.71","mis":"M5-2-u1-X17"}],"explanation":["6.79·6.70·6.71은 소수 첫째 자리 아래를 버려 모두 6.7이에요.","6.8은 버릴 것이 없어 그대로 6.8이에요.","그래서 다른 하나는 6.8이에요."],"variant_rule":{"alt":[{"stem":"2390, 2309, 2400, 2399를 각각 버림하여 백의 자리까지 나타냈어요. 결과가 다른 하나는 어느 것인가요?","options":[{"t":"2400","correct":true},{"t":"2390","mis":"M5-2-u1-X17"},{"t":"2309","mis":"M5-2-u1-X17"},{"t":"2399","mis":"M5-2-u1-X17"}],"explanation":["2390·2309·2399는 백의 자리 아래를 버려 모두 2300이에요.","2400은 그대로 2400이에요.","그래서 다른 하나는 2400이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_L06_challenge#4','math',5,2,'u1','L06','g5_2_math_u1_L06_challenge','lesson_challenge','M5-2-u1-C5',3,'sa','auto','꽃 한 송이를 만드는 데 리본 100 cm가 들어요. 리본 357 cm로 꽃을 최대 몇 송이 만들 수 있나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M5-2-u1-C5","difficulty":3,"kind":"sa","stem":"꽃 한 송이를 만드는 데 리본 100 cm가 들어요. 리본 357 cm로 꽃을 최대 몇 송이 만들 수 있나요? 숫자로 쓰세요.","answer":["3","3송이"],"explanation":["100 cm가 다 있어야 꽃 한 송이예요.","357을 버림하여 백의 자리까지 → 300 cm예요.","300 cm로 3송이 — 남는 57 cm로는 한 송이를 못 만들어요."],"variant_rule":{"alt":[{"stem":"주스 한 병을 채우는 데 1000 mL가 들어요. 주스 8750 mL로 병을 최대 몇 병 채울 수 있나요? 숫자로 쓰세요.","answer":["8","8병"],"explanation":["1000 mL가 다 있어야 한 병이에요.","8750을 버림하여 천의 자리까지 → 8000 mL예요.","8병을 채우고 750 mL가 남아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_L06_challenge#5','math',5,2,'u1','L06','g5_2_math_u1_L06_challenge','lesson_challenge','M5-2-u1-C5',3,'error','auto','친구들이 4.835를 버림했어요. 잘못한 친구는 누구인가요?',ARRAY['M5-2-u1-X08','M5-2-u1-X17']::text[],true,'{"seq":5,"concept":"M5-2-u1-C5","difficulty":3,"kind":"error","stem":"친구들이 4.835를 버림했어요. 잘못한 친구는 누구인가요?","options":[{"t":"은재 — 「소수 첫째 자리까지 나타내면 4.9야.」","correct":true,"mis_target":"M5-2-u1-X08"},{"t":"주하 — 「소수 둘째 자리까지 나타내면 4.83이야.」","mis":"M5-2-u1-X17"},{"t":"이안 — 「일의 자리까지 나타내면 4야.」","mis":"M5-2-u1-X17"}],"explanation":["버림은 아래 수를 모두 버려요.","4.835에서 소수 첫째 자리 아래 0.035를 버리면 4.8이에요.","은재는 아래 숫자 3을 보지도 않고 올렸어요."],"variant_rule":{"alt":[{"stem":"친구들이 7296을 버림했어요. 잘못한 친구는 누구인가요?","options":[{"t":"서준 — 「백의 자리까지 나타내면 7300이야.」","correct":true,"mis_target":"M5-2-u1-X08"},{"t":"다윤 — 「십의 자리까지 나타내면 7290이야.」","mis":"M5-2-u1-X17"},{"t":"로아 — 「천의 자리까지 나타내면 7000이야.」","mis":"M5-2-u1-X17"}],"explanation":["버림은 아래 수를 모두 버려요.","7296에서 백의 자리 아래 96을 버리면 7200이에요.","서준이는 아래 숫자가 커서 올렸어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_L06_challenge#6','math',5,2,'u1','L06','g5_2_math_u1_L06_challenge','lesson_challenge','M5-2-u1-C5',3,'mc','auto','339, 340, 345, 349, 350 중에서 버림하여 십의 자리까지 나타내면 340이 되는 수를 모두 고른 것은 어느 것인가요?',ARRAY['M5-2-u1-X08','M5-2-u1-X15']::text[],true,'{"seq":6,"concept":"M5-2-u1-C5","difficulty":3,"kind":"mc","stem":"339, 340, 345, 349, 350 중에서 버림하여 십의 자리까지 나타내면 340이 되는 수를 모두 고른 것은 어느 것인가요?","options":[{"t":"340, 345, 349","correct":true},{"t":"345, 349, 350","mis":"M5-2-u1-X08"},{"t":"339, 340, 345","mis":"M5-2-u1-X08"},{"t":"345, 349","mis":"M5-2-u1-X15"}],"explanation":["버림하여 340이 되려면 340 이상 350 미만이에요.","340은 그대로 340, 345·349는 아래 수를 버려 340이에요.","339는 330, 350은 350이라 빠져요."],"variant_rule":{"alt":[{"stem":"2.4, 2.45, 2.5, 2.49, 2.39 중에서 버림하여 소수 첫째 자리까지 나타내면 2.4가 되는 수를 모두 고른 것은 어느 것인가요?","options":[{"t":"2.4, 2.45, 2.49","correct":true},{"t":"2.45, 2.49, 2.5","mis":"M5-2-u1-X08"},{"t":"2.39, 2.4, 2.45","mis":"M5-2-u1-X08"},{"t":"2.45, 2.49","mis":"M5-2-u1-X15"}],"explanation":["버림하여 2.4가 되려면 2.4 이상 2.5 미만이에요.","2.4는 그대로, 2.45·2.49는 아래를 버려 2.4예요.","2.39는 2.3, 2.5는 2.5라 빠져요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_L06_challenge#7','math',5,2,'u1','L06','g5_2_math_u1_L06_challenge','lesson_challenge','M5-2-u1-C5',3,'sa','auto','버림하여 십의 자리까지 나타내면 60이 되는 자연수는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M5-2-u1-C5","difficulty":3,"kind":"sa","stem":"버림하여 십의 자리까지 나타내면 60이 되는 자연수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["10","10개"],"explanation":["60은 버림해도 60 — 들어가요.","61부터 69까지도 60이 돼요.","60부터 69까지 10개예요."],"variant_rule":{"alt":[{"stem":"버림하여 십의 자리까지 나타내면 90이 되는 두 자리 수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["10","10개"],"explanation":["90은 그대로 90이에요.","91부터 99까지도 90이 돼요.","90부터 99까지 10개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_L06_challenge#8','math',5,2,'u1','L06','g5_2_math_u1_L06_challenge','lesson_challenge','M5-2-u1-C5',4,'essay','teacher','곤충 과자 657개를 10개씩 포장해요. 포장할 수 있는 과자 수를 구하고, 이 상황에서 버림으로 어림하는 까닭을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"M5-2-u1-C5","difficulty":4,"kind":"essay","stem":"곤충 과자 657개를 10개씩 포장해요. 포장할 수 있는 과자 수를 구하고, 이 상황에서 버림으로 어림하는 까닭을 쓰세요.","answer_guide":{"answer":"예: 650개. 10개씩 65묶음을 만들고 남는 7개는 10개를 채우지 못해 포장할 수 없으므로 아래 수를 버린다. 657을 버림하여 십의 자리까지 나타낸 것이다.","scoring_points":["650개를 구했는가","남는 7개는 포장할 수 없음을 썼는가","버림하여 십의 자리까지 나타낸 것임을 썼는가"]},"explanation":["10개씩 65묶음 — 650개예요.","남는 7개는 묶음을 채우지 못해요.","그래서 버림이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_L06_challenge#9','math',5,2,'u1','L06','g5_2_math_u1_L06_challenge','lesson_challenge','M5-2-u1-C5',4,'essay','teacher','가방을 사는 이야기(543명)에서는 올림을, 과자를 포장하는 이야기(657개)에서는 버림을 썼어요. 두 이야기에서 어림 방법이 갈린 까닭을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"M5-2-u1-C5","difficulty":4,"kind":"essay","stem":"가방을 사는 이야기(543명)에서는 올림을, 과자를 포장하는 이야기(657개)에서는 버림을 썼어요. 두 이야기에서 어림 방법이 갈린 까닭을 쓰세요.","answer_guide":{"answer":"예: 가방은 모자라면 받지 못하는 학생이 생기니 필요한 수보다 크게 어림하는 올림을 쓴다. 과자는 10개를 채우지 못하면 포장할 수 없으니 남는 것을 버리는 버림을 쓴다. 무엇을 하려는지에 따라 방법이 갈린다.","scoring_points":["가방은 모자라면 안 되어 올림임을 썼는가","과자는 남는 것을 포장할 수 없어 버림임을 썼는가","상황(하려는 일)이 방법을 정한다고 썼는가"]},"explanation":["가방 — 모자라면 안 돼 올림이에요.","과자 — 남는 것은 못 담아 버림이에요.","무엇을 하려는지가 방법을 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_L06_challenge#10','math',5,2,'u1','L06','g5_2_math_u1_L06_challenge','lesson_challenge','M5-2-u1-C5',4,'mc','auto','어떤 자연수를 버림하여 백의 자리까지 나타내면 4500이고, 올림하여 백의 자리까지 나타내면 4600이에요. 어떤 자연수가 될 수 있는 수는 모두 몇 개인가요?',ARRAY['M5-2-u1-X07','M5-2-u1-X15','M5-2-u1-X06']::text[],true,'{"seq":10,"concept":"M5-2-u1-C5","difficulty":4,"kind":"mc","stem":"어떤 자연수를 버림하여 백의 자리까지 나타내면 4500이고, 올림하여 백의 자리까지 나타내면 4600이에요. 어떤 자연수가 될 수 있는 수는 모두 몇 개인가요?","options":[{"t":"99개","correct":true},{"t":"100개","mis":"M5-2-u1-X07"},{"t":"101개","mis":"M5-2-u1-X15"},{"t":"98개","mis":"M5-2-u1-X06"}],"explanation":["버림하여 4500이 되는 수는 4500부터 4599까지예요.","그중 4500은 올림해도 4500이라 빠져요.","4501부터 4599까지 99개예요."],"variant_rule":{"alt":[{"stem":"어떤 자연수를 버림하여 십의 자리까지 나타내면 70이고, 올림하여 십의 자리까지 나타내면 80이에요. 어떤 자연수가 될 수 있는 수는 모두 몇 개인가요?","options":[{"t":"9개","correct":true},{"t":"10개","mis":"M5-2-u1-X07"},{"t":"11개","mis":"M5-2-u1-X15"},{"t":"8개","mis":"M5-2-u1-X06"}],"explanation":["버림하여 70이 되는 수는 70부터 79까지예요.","70은 올림해도 70이라 빠져요.","71부터 79까지 9개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_L07_basic#1','math',5,2,'u1','L07','g5_2_math_u1_L07_basic','lesson_basic','M5-2-u1-C6',1,'mc','auto','도서관에서 1학기 동안 빌려준 책이 5813권이에요. 5813은 5800과 5900 중에서 어느 수에 더 가까운가요?',ARRAY['M5-2-u1-X08','M5-2-u1-X16','M5-2-u1-X09']::text[],true,'{"seq":1,"concept":"M5-2-u1-C6","difficulty":1,"kind":"mc","stem":"도서관에서 1학기 동안 빌려준 책이 5813권이에요. 5813은 5800과 5900 중에서 어느 수에 더 가까운가요?","options":[{"t":"5800","correct":true},{"t":"5900","mis":"M5-2-u1-X08"},{"t":"두 수에 똑같이 가깝다","mis":"M5-2-u1-X16"},{"t":"6000","mis":"M5-2-u1-X09"}],"explanation":["5800과 5900의 한가운데는 5850이에요.","5813은 5850보다 왼쪽(작은 쪽)에 있어요.","그래서 5800에 더 가까워요 — 약 5800권이에요."],"variant_rule":{"alt":[{"stem":"어제 박물관에 온 관람객이 4752명이에요. 4752는 4700과 4800 중에서 어느 수에 더 가까운가요?","options":[{"t":"4800","correct":true},{"t":"4700","mis":"M5-2-u1-X08"},{"t":"두 수에 똑같이 가깝다","mis":"M5-2-u1-X16"},{"t":"5000","mis":"M5-2-u1-X09"}],"explanation":["4700과 4800의 한가운데는 4750이에요.","4752는 4750보다 오른쪽에 있어요.","그래서 4800에 더 가까워요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_L07_basic#2','math',5,2,'u1','L07','g5_2_math_u1_L07_basic','lesson_basic','M5-2-u1-C6',1,'mc','auto','5813을 반올림하여 백의 자리까지 나타내면 얼마인가요?',ARRAY['M5-2-u1-X08','M5-2-u1-X09']::text[],true,'{"seq":2,"concept":"M5-2-u1-C6","difficulty":1,"kind":"mc","stem":"5813을 반올림하여 백의 자리까지 나타내면 얼마인가요?","options":[{"t":"5800","correct":true},{"t":"5900","mis":"M5-2-u1-X08"},{"t":"5810","mis":"M5-2-u1-X09"},{"t":"6000","mis":"M5-2-u1-X09"}],"explanation":["반올림은 구하려는 자리 바로 아래 한 자리만 봐요.","백의 자리 바로 아래 숫자가 1이라 버려요.","5813 → 5800이에요."],"variant_rule":{"alt":[{"stem":"4752를 반올림하여 백의 자리까지 나타내면 얼마인가요?","options":[{"t":"4800","correct":true},{"t":"4700","mis":"M5-2-u1-X08"},{"t":"4750","mis":"M5-2-u1-X09"},{"t":"5000","mis":"M5-2-u1-X09"}],"explanation":["반올림은 구하려는 자리 바로 아래 한 자리만 봐요.","백의 자리 바로 아래 숫자가 5라 올려요.","4752 → 4800이에요."]},{"stem":"8542를 반올림하여 천의 자리까지 나타내면 얼마인가요?","options":[{"t":"9000","correct":true},{"t":"8000","mis":"M5-2-u1-X08"},{"t":"8500","mis":"M5-2-u1-X09"},{"t":"8540","mis":"M5-2-u1-X09"}],"explanation":["반올림은 구하려는 자리 바로 아래 한 자리만 봐요.","천의 자리 바로 아래 숫자가 5라 올려요.","8542 → 9000이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_L07_basic#3','math',5,2,'u1','L07','g5_2_math_u1_L07_basic','lesson_basic','M5-2-u1-C6',1,'mc','auto','3.406을 반올림하여 소수 둘째 자리까지 나타내면 얼마인가요?',ARRAY['M5-2-u1-X08','M5-2-u1-X09','M5-2-u1-X16']::text[],true,'{"seq":3,"concept":"M5-2-u1-C6","difficulty":1,"kind":"mc","stem":"3.406을 반올림하여 소수 둘째 자리까지 나타내면 얼마인가요?","options":[{"t":"3.41","correct":true},{"t":"3.40","mis":"M5-2-u1-X08"},{"t":"3.46","mis":"M5-2-u1-X09"},{"t":"3.42","mis":"M5-2-u1-X16"}],"explanation":["반올림은 구하려는 자리 바로 아래 한 자리만 봐요.","소수 둘째 자리 바로 아래 숫자가 0이라 버려요.","3.406 → 3.41이에요."],"variant_rule":{"alt":[{"stem":"1.573을 반올림하여 소수 첫째 자리까지 나타내면 얼마인가요?","options":[{"t":"1.6","correct":true},{"t":"1.5","mis":"M5-2-u1-X08"},{"t":"1.57","mis":"M5-2-u1-X09"},{"t":"2","mis":"M5-2-u1-X09"}],"explanation":["반올림은 구하려는 자리 바로 아래 한 자리만 봐요.","소수 첫째 자리 바로 아래 숫자가 0이라 버려요.","1.573 → 1.6이에요."]},{"stem":"0.758을 반올림하여 소수 첫째 자리까지 나타내면 얼마인가요?","options":[{"t":"0.8","correct":true},{"t":"0.7","mis":"M5-2-u1-X08"},{"t":"0.76","mis":"M5-2-u1-X09"},{"t":"1","mis":"M5-2-u1-X09"}],"explanation":["반올림은 구하려는 자리 바로 아래 한 자리만 봐요.","소수 첫째 자리 바로 아래 숫자가 0이라 버려요.","0.758 → 0.8이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_L07_basic#4','math',5,2,'u1','L07','g5_2_math_u1_L07_basic','lesson_basic','M5-2-u1-C6',1,'mc','auto','4752를 반올림하여 천의 자리까지 나타내면 얼마인가요?',ARRAY['M5-2-u1-X08','M5-2-u1-X09']::text[],true,'{"seq":4,"concept":"M5-2-u1-C6","difficulty":1,"kind":"mc","stem":"4752를 반올림하여 천의 자리까지 나타내면 얼마인가요?","options":[{"t":"5000","correct":true},{"t":"4000","mis":"M5-2-u1-X08"},{"t":"4800","mis":"M5-2-u1-X09"},{"t":"4750","mis":"M5-2-u1-X09"}],"explanation":["반올림은 구하려는 자리 바로 아래 한 자리만 봐요.","천의 자리 바로 아래 숫자가 7이라 올려요.","4752 → 5000이에요."],"variant_rule":{"alt":[{"stem":"5813을 반올림하여 천의 자리까지 나타내면 얼마인가요?","options":[{"t":"6000","correct":true},{"t":"5000","mis":"M5-2-u1-X08"},{"t":"5800","mis":"M5-2-u1-X09"},{"t":"5810","mis":"M5-2-u1-X09"}],"explanation":["반올림은 구하려는 자리 바로 아래 한 자리만 봐요.","천의 자리 바로 아래 숫자가 8이라 올려요.","5813 → 6000이에요."]},{"stem":"2481을 반올림하여 십의 자리까지 나타내면 얼마인가요?","options":[{"t":"2480","correct":true},{"t":"2490","mis":"M5-2-u1-X08"},{"t":"2500","mis":"M5-2-u1-X09"},{"t":"248","mis":"M5-2-u1-X12"}],"explanation":["반올림은 구하려는 자리 바로 아래 한 자리만 봐요.","십의 자리 바로 아래 숫자가 1이라 버려요.","2481 → 2480이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_L07_basic#5','math',5,2,'u1','L07','g5_2_math_u1_L07_basic','lesson_basic','M5-2-u1-C6',2,'sa','auto','우리 학년 학생은 47명이에요. 반올림하여 십의 자리까지 나타내면 약 몇 명인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M5-2-u1-C6","difficulty":2,"kind":"sa","stem":"우리 학년 학생은 47명이에요. 반올림하여 십의 자리까지 나타내면 약 몇 명인가요? 숫자로 쓰세요.","answer":["50","50명"],"explanation":["반올림은 십의 자리 바로 아래 — 일의 자리 숫자를 봐요.","일의 자리 숫자 7은 5~9라 올려요.","47 → 50, 약 50명이에요."],"variant_rule":{"alt":[{"stem":"학교 텃밭에서 딴 오이가 84개예요. 반올림하여 십의 자리까지 나타내면 약 몇 개인가요? 숫자로 쓰세요.","answer":["80","80개"],"explanation":["일의 자리 숫자를 봐요.","4는 0~4라 버려요.","84 → 80, 약 80개예요."]},{"stem":"줄넘기를 65번 넘었어요. 반올림하여 십의 자리까지 나타내면 약 몇 번인가요? 숫자로 쓰세요.","answer":["70","70번"],"explanation":["일의 자리 숫자를 봐요.","5는 5~9라 올려요.","65 → 70, 약 70번이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_L07_basic#6','math',5,2,'u1','L07','g5_2_math_u1_L07_basic','lesson_basic','M5-2-u1-C6',2,'mc','auto','2449를 반올림하여 백의 자리까지 나타내면 얼마인가요?',ARRAY['M5-2-u1-X10','M5-2-u1-X09']::text[],true,'{"seq":6,"concept":"M5-2-u1-C6","difficulty":2,"kind":"mc","stem":"2449를 반올림하여 백의 자리까지 나타내면 얼마인가요?","options":[{"t":"2400","correct":true},{"t":"2500","mis":"M5-2-u1-X10"},{"t":"2450","mis":"M5-2-u1-X09"},{"t":"2000","mis":"M5-2-u1-X09"}],"explanation":["반올림은 구하려는 자리 바로 아래 한 자리만 봐요.","백의 자리 바로 아래 숫자가 4라 버려요.","2449 → 2400이에요."],"variant_rule":{"alt":[{"stem":"1649를 반올림하여 백의 자리까지 나타내면 얼마인가요?","options":[{"t":"1600","correct":true},{"t":"1700","mis":"M5-2-u1-X10"},{"t":"1650","mis":"M5-2-u1-X09"},{"t":"2000","mis":"M5-2-u1-X09"}],"explanation":["반올림은 구하려는 자리 바로 아래 한 자리만 봐요.","백의 자리 바로 아래 숫자가 4라 버려요.","1649 → 1600이에요."]},{"stem":"3.449를 반올림하여 소수 첫째 자리까지 나타내면 얼마인가요?","options":[{"t":"3.4","correct":true},{"t":"3.5","mis":"M5-2-u1-X10"},{"t":"3.45","mis":"M5-2-u1-X09"},{"t":"3","mis":"M5-2-u1-X09"}],"explanation":["반올림은 구하려는 자리 바로 아래 한 자리만 봐요.","소수 첫째 자리 바로 아래 숫자가 0이라 버려요.","3.449 → 3.4예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_L07_basic#7','math',5,2,'u1','L07','g5_2_math_u1_L07_basic','lesson_basic','M5-2-u1-C6',2,'mc','auto','반올림하여 십의 자리까지 나타낸 수가 1270이에요. 126□의 □에 들어갈 수 있는 수를 모두 고른 것은 어느 것인가요?',ARRAY['M5-2-u1-X08','M5-2-u1-X11','M5-2-u1-X16']::text[],true,'{"seq":7,"concept":"M5-2-u1-C6","difficulty":2,"kind":"mc","stem":"반올림하여 십의 자리까지 나타낸 수가 1270이에요. 126□의 □에 들어갈 수 있는 수를 모두 고른 것은 어느 것인가요?","options":[{"t":"5, 6, 7, 8, 9","correct":true},{"t":"0, 1, 2, 3, 4","mis":"M5-2-u1-X08"},{"t":"6, 7, 8, 9","mis":"M5-2-u1-X11"},{"t":"0, 5","mis":"M5-2-u1-X16"}],"explanation":["126□를 십의 자리까지 반올림하면 일의 자리 □를 봐요.","1270이 되려면 올려야 하니 □는 5~9예요.","0~4면 버려서 1260이 돼요."],"variant_rule":{"alt":[{"stem":"반올림하여 백의 자리까지 나타낸 수가 3500이에요. 35□2의 □에 들어갈 수 있는 수를 모두 고른 것은 어느 것인가요?","options":[{"t":"0, 1, 2, 3, 4","correct":true},{"t":"5, 6, 7, 8, 9","mis":"M5-2-u1-X08"},{"t":"0, 1, 2, 3","mis":"M5-2-u1-X16"},{"t":"1, 2, 3, 4, 5","mis":"M5-2-u1-X11"}],"explanation":["백의 자리까지 반올림하면 십의 자리 □를 봐요.","3500이 되려면 버려야 하니 □는 0~4예요.","5~9면 올라가 3600이 돼요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_L07_basic#8','math',5,2,'u1','L07','g5_2_math_u1_L07_basic','lesson_basic','M5-2-u1-C6',2,'sa','auto','반올림하여 십의 자리까지 나타낸 수가 1270이에요. 126□의 □에 들어갈 수 있는 수 중에서 가장 작은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M5-2-u1-C6","difficulty":2,"kind":"sa","stem":"반올림하여 십의 자리까지 나타낸 수가 1270이에요. 126□의 □에 들어갈 수 있는 수 중에서 가장 작은 수는 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["1270이 되려면 일의 자리 □를 올려야 해요.","올리는 숫자는 5, 6, 7, 8, 9예요.","그중 가장 작은 수는 5 — 1265예요."],"variant_rule":{"alt":[{"stem":"반올림하여 백의 자리까지 나타낸 수가 3500이에요. 35□2의 □에 들어갈 수 있는 수 중에서 가장 큰 수는 얼마인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["3500이 되려면 십의 자리 □를 버려야 해요.","버리는 숫자는 0~4예요.","그중 가장 큰 수는 4 — 3542예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_L07_basic#9','math',5,2,'u1','L07','g5_2_math_u1_L07_basic','lesson_basic','M5-2-u1-C6',2,'ox','auto','반올림할 때 바로 아래 자리 숫자가 5이면 버려요.',ARRAY['M5-2-u1-X11']::text[],true,'{"seq":9,"concept":"M5-2-u1-C6","difficulty":2,"kind":"ox","stem":"반올림할 때 바로 아래 자리 숫자가 5이면 버려요.","answer":"X","reason_options":[{"t":"반올림은 바로 아래 숫자가 0~4면 버리고 5~9면 올리는 방법이라서","correct":true},{"t":"5는 0과 9의 한가운데라 버려서","mis":"M5-2-u1-X11"}],"mis":"M5-2-u1-X11","explanation":["0부터 9까지 열 개의 숫자를 다섯 개씩 나눠요.","0~4는 버리고 5~9는 올려요.","그래서 5는 올려요 — 예: 4752를 백의 자리까지 → 4800."],"variant_rule":{"alt":[{"stem":"반올림할 때는 구하려는 자리 바로 아래 한 자리의 숫자만 봐요.","answer":"O","reason_options":[{"t":"바로 아래 한 자리로 버릴지 올릴지 정해서","correct":true},{"t":"맨 끝 자리부터 차례로 반올림해 올라가야 해서","mis":"M5-2-u1-X10"}],"explanation":["반올림은 바로 아래 한 자리만 봐요.","2449를 백의 자리까지 → 십의 자리 숫자 4만 보고 버려요.","그래서 2400이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
