INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_L07_challenge#1','math',5,2,'u1','L07','g5_2_math_u1_L07_challenge','lesson_challenge','M5-2-u1-C6',2,'mc','auto','3259219를 반올림하여 만의 자리까지 나타내면 얼마인가요?',ARRAY['M5-2-u1-X08','M5-2-u1-X09']::text[],true,'{"seq":1,"concept":"M5-2-u1-C6","difficulty":2,"kind":"mc","stem":"3259219를 반올림하여 만의 자리까지 나타내면 얼마인가요?","options":[{"t":"3260000","correct":true},{"t":"3250000","mis":"M5-2-u1-X08"},{"t":"3259000","mis":"M5-2-u1-X09"},{"t":"3259200","mis":"M5-2-u1-X09"}],"explanation":["반올림은 구하려는 자리 바로 아래 한 자리만 봐요.","만의 자리 바로 아래 숫자가 9라 올려요.","3259219 → 3260000이에요."],"variant_rule":{"alt":[{"stem":"2276.209를 반올림하여 일의 자리까지 나타내면 얼마인가요?","options":[{"t":"2276","correct":true},{"t":"2277","mis":"M5-2-u1-X08"},{"t":"2276.2","mis":"M5-2-u1-X09"},{"t":"2280","mis":"M5-2-u1-X09"}],"explanation":["반올림은 구하려는 자리 바로 아래 한 자리만 봐요.","일의 자리 바로 아래 숫자가 0이라 버려요.","2276.209 → 2276이에요."]},{"stem":"485.647을 반올림하여 일의 자리까지 나타내면 얼마인가요?","options":[{"t":"486","correct":true},{"t":"485","mis":"M5-2-u1-X08"},{"t":"485.6","mis":"M5-2-u1-X09"},{"t":"490","mis":"M5-2-u1-X09"}],"explanation":["반올림은 구하려는 자리 바로 아래 한 자리만 봐요.","일의 자리 바로 아래 숫자가 0이라 버려요.","485.647 → 486이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_L07_challenge#2','math',5,2,'u1','L07','g5_2_math_u1_L07_challenge','lesson_challenge','M5-2-u1-C6',2,'mc','auto','반올림을 바르게 설명한 것은 어느 것인가요?',ARRAY['M5-2-u1-X08','M5-2-u1-X11','M5-2-u1-X10']::text[],false,'{"seq":2,"concept":"M5-2-u1-C6","difficulty":2,"kind":"mc","stem":"반올림을 바르게 설명한 것은 어느 것인가요?","options":[{"t":"구하려는 자리 바로 아래 한 자리의 숫자가 0~4면 버리고 5~9면 올리는 방법","correct":true},{"t":"구하려는 자리 아래 수를 모두 올리는 방법","mis":"M5-2-u1-X08"},{"t":"바로 아래 숫자가 0~5면 버리고 6~9면 올리는 방법","mis":"M5-2-u1-X11"},{"t":"맨 끝 자리부터 차례로 반올림해 올라가는 방법","mis":"M5-2-u1-X10"}],"explanation":["반올림은 바로 아래 한 자리만 봐요.","0~4는 버리고 5~9는 올려요.","그래서 원래 수에 가장 가깝게 어림돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_L07_challenge#3','math',5,2,'u1','L07','g5_2_math_u1_L07_challenge','lesson_challenge','M5-2-u1-C6',3,'mc','auto','반올림하여 백의 자리까지 나타내면 3700이 되는 수의 범위로 알맞은 것은 어느 것인가요?',ARRAY['M5-2-u1-X11','M5-2-u1-X08']::text[],true,'{"seq":3,"concept":"M5-2-u1-C6","difficulty":3,"kind":"mc","stem":"반올림하여 백의 자리까지 나타내면 3700이 되는 수의 범위로 알맞은 것은 어느 것인가요?","options":[{"t":"3650 이상 3750 미만","correct":true},{"t":"3650 초과 3750 이하","mis":"M5-2-u1-X11"},{"t":"3600 초과 3700 이하","mis":"M5-2-u1-X08"},{"t":"3700 이상 3800 미만","mis":"M5-2-u1-X08"}],"explanation":["3650은 십의 자리 숫자 5를 올려 3700 — 들어가요.","3749까지는 3700, 3750은 올려 3800이 돼요.","그래서 3650 이상 3750 미만이에요."],"variant_rule":{"alt":[{"stem":"반올림하여 십의 자리까지 나타내면 80이 되는 수의 범위로 알맞은 것은 어느 것인가요?","options":[{"t":"75 이상 85 미만","correct":true},{"t":"75 초과 85 이하","mis":"M5-2-u1-X11"},{"t":"70 초과 80 이하","mis":"M5-2-u1-X08"},{"t":"80 이상 90 미만","mis":"M5-2-u1-X08"}],"explanation":["75는 5를 올려 80 — 들어가요.","84까지는 80, 85는 올려 90이에요.","그래서 75 이상 85 미만이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_L07_challenge#4','math',5,2,'u1','L07','g5_2_math_u1_L07_challenge','lesson_challenge','M5-2-u1-C6',3,'error','auto','친구들이 2449를 반올림하여 백의 자리까지 나타냈어요. 잘못한 친구는 누구인가요?',ARRAY['M5-2-u1-X10','M5-2-u1-X17']::text[],true,'{"seq":4,"concept":"M5-2-u1-C6","difficulty":3,"kind":"error","stem":"친구들이 2449를 반올림하여 백의 자리까지 나타냈어요. 잘못한 친구는 누구인가요?","options":[{"t":"주원 — 「49를 먼저 반올림하면 50이 되니 2450, 그걸 또 반올림해서 2500이야.」","correct":true,"mis_target":"M5-2-u1-X10"},{"t":"하랑 — 「십의 자리 숫자 4만 보고 버려서 2400이야.」","mis":"M5-2-u1-X17"},{"t":"채린 — 「2449는 2400과 2500 중 2400에 더 가까워.」","mis":"M5-2-u1-X17"}],"explanation":["반올림은 바로 아래 한 자리 — 십의 자리 숫자 4만 봐요.","4는 버리니 2400이 맞아요.","주원이는 맨 끝부터 차례로 올려서 틀렸어요."],"variant_rule":{"alt":[{"stem":"친구들이 3.449를 반올림하여 소수 첫째 자리까지 나타냈어요. 잘못한 친구는 누구인가요?","options":[{"t":"민서 — 「끝의 9부터 올리면 3.45, 그걸 또 올리면 3.5야.」","correct":true,"mis_target":"M5-2-u1-X10"},{"t":"겸이 — 「소수 둘째 자리 숫자 4만 보고 버려서 3.4야.」","mis":"M5-2-u1-X17"},{"t":"아린 — 「3.449는 3.4와 3.5 중 3.4에 더 가까워.」","mis":"M5-2-u1-X17"}],"explanation":["소수 첫째 자리 바로 아래 — 소수 둘째 자리 숫자 4만 봐요.","4는 버리니 3.4가 맞아요.","민서는 맨 끝부터 차례로 올려서 틀렸어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_L07_challenge#5','math',5,2,'u1','L07','g5_2_math_u1_L07_challenge','lesson_challenge','M5-2-u1-C6',3,'mc','auto','5.602, 5.58, 5.061, 5.63, 5.51 중에서 반올림하여 소수 첫째 자리까지 나타내면 5.6이 되는 수를 모두 고른 것은 어느 것인가요?',ARRAY['M5-2-u1-X08','M5-2-u1-X11','M5-2-u1-X15']::text[],true,'{"seq":5,"concept":"M5-2-u1-C6","difficulty":3,"kind":"mc","stem":"5.602, 5.58, 5.061, 5.63, 5.51 중에서 반올림하여 소수 첫째 자리까지 나타내면 5.6이 되는 수를 모두 고른 것은 어느 것인가요?","options":[{"t":"5.602, 5.58, 5.63","correct":true},{"t":"5.602, 5.63","mis":"M5-2-u1-X08"},{"t":"5.58, 5.51","mis":"M5-2-u1-X11"},{"t":"5.602, 5.58, 5.63, 5.51","mis":"M5-2-u1-X15"}],"explanation":["소수 둘째 자리 숫자를 봐요 — 5.602(0 버림), 5.58(8 올림), 5.63(3 버림)은 5.6이에요.","5.061은 5.1, 5.51은 5.5예요.","그래서 5.602, 5.58, 5.63이에요."],"variant_rule":{"alt":[{"stem":"2.35, 2.449, 2.44, 2.351, 2.25 중에서 반올림하여 소수 첫째 자리까지 나타내면 2.4가 되는 수를 모두 고른 것은 어느 것인가요?","options":[{"t":"2.35, 2.449, 2.44, 2.351","correct":true},{"t":"2.449, 2.44","mis":"M5-2-u1-X11"},{"t":"2.35, 2.351","mis":"M5-2-u1-X08"},{"t":"2.35, 2.449, 2.44, 2.351, 2.25","mis":"M5-2-u1-X15"}],"explanation":["소수 둘째 자리 숫자를 봐요 — 2.35·2.351(5 올림), 2.449·2.44(4 버림)는 2.4예요.","2.25는 2.3이에요.","그래서 2.35, 2.449, 2.44, 2.351이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_L07_challenge#6','math',5,2,'u1','L07','g5_2_math_u1_L07_challenge','lesson_challenge','M5-2-u1-C6',3,'sa','auto','반올림하여 십의 자리까지 나타내면 40이 되는 자연수는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M5-2-u1-C6","difficulty":3,"kind":"sa","stem":"반올림하여 십의 자리까지 나타내면 40이 되는 자연수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["10","10개"],"explanation":["35부터 39까지는 올려서 40이 돼요.","40부터 44까지는 버려서 40이에요.","35부터 44까지 10개예요."],"variant_rule":{"alt":[{"stem":"반올림하여 십의 자리까지 나타내면 40이 되는 자연수 중에서 홀수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["5","5개"],"explanation":["40이 되는 자연수는 35부터 44까지예요.","그중 홀수는 35, 37, 39, 41, 43이에요.","모두 5개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_L07_challenge#7','math',5,2,'u1','L07','g5_2_math_u1_L07_challenge','lesson_challenge','M5-2-u1-C6',3,'mc','auto','5267을 백의 자리까지 올림, 버림, 반올림으로 각각 나타냈어요. 반올림한 결과와 같은 결과가 나오는 방법은 어느 것인가요?',ARRAY['M5-2-u1-X08','M5-2-u1-X16']::text[],true,'{"seq":7,"concept":"M5-2-u1-C6","difficulty":3,"kind":"mc","stem":"5267을 백의 자리까지 올림, 버림, 반올림으로 각각 나타냈어요. 반올림한 결과와 같은 결과가 나오는 방법은 어느 것인가요?","options":[{"t":"올림","correct":true},{"t":"버림","mis":"M5-2-u1-X08"},{"t":"셋 다 같다","mis":"M5-2-u1-X08"},{"t":"셋 다 다르다","mis":"M5-2-u1-X16"}],"explanation":["올림 5300 · 버림 5200이에요.","반올림은 십의 자리 숫자 6을 올려 5300이에요.","그래서 반올림과 같은 것은 올림이에요."],"variant_rule":{"alt":[{"stem":"5217을 백의 자리까지 올림, 버림, 반올림으로 각각 나타냈어요. 반올림한 결과와 같은 결과가 나오는 방법은 어느 것인가요?","options":[{"t":"버림","correct":true},{"t":"올림","mis":"M5-2-u1-X08"},{"t":"셋 다 같다","mis":"M5-2-u1-X08"},{"t":"셋 다 다르다","mis":"M5-2-u1-X16"}],"explanation":["올림 5300 · 버림 5200이에요.","반올림은 십의 자리 숫자 1을 버려 5200이에요.","그래서 반올림과 같은 것은 버림이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_L07_challenge#8','math',5,2,'u1','L07','g5_2_math_u1_L07_challenge','lesson_challenge','M5-2-u1-C6',4,'essay','teacher','2449를 반올림하여 백의 자리까지 나타내면 2400인지 2500인지 판단하고, 바로 아래 한 자리만 보는 까닭을 수직선(2400과 2500 사이 한가운데 2450)으로 설명하세요.','{}'::text[],false,'{"seq":8,"concept":"M5-2-u1-C6","difficulty":4,"kind":"essay","stem":"2449를 반올림하여 백의 자리까지 나타내면 2400인지 2500인지 판단하고, 바로 아래 한 자리만 보는 까닭을 수직선(2400과 2500 사이 한가운데 2450)으로 설명하세요.","answer_guide":{"answer":"예: 2400이다. 2449는 2400과 2500의 한가운데인 2450보다 작아 2400에 더 가깝다. 십의 자리 숫자 4만 보아도 이것을 알 수 있으므로 바로 아래 한 자리만 본다. 끝의 9부터 올리면 2450이 되어 실제보다 커지므로 틀린다.","scoring_points":["2400으로 판단했는가","2449가 한가운데 2450보다 작아 2400에 가깝다고 썼는가","맨 끝부터 차례로 올리면 안 되는 까닭을 썼는가"]},"explanation":["2449는 2450보다 작아요.","그래서 2400에 더 가까워요.","바로 아래 숫자 4만 보면 버린다는 것을 알 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_L07_challenge#9','math',5,2,'u1','L07','g5_2_math_u1_L07_challenge','lesson_challenge','M5-2-u1-C6',4,'essay','teacher','도서관에서 빌려준 책 5813권을 「약 5800권」이라고 한 친구와 「약 6000권」이라고 한 친구가 있어요. 두 친구의 말이 모두 맞을 수 있는지 판단하고 까닭을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"M5-2-u1-C6","difficulty":4,"kind":"essay","stem":"도서관에서 빌려준 책 5813권을 「약 5800권」이라고 한 친구와 「약 6000권」이라고 한 친구가 있어요. 두 친구의 말이 모두 맞을 수 있는지 판단하고 까닭을 쓰세요.","answer_guide":{"answer":"예: 모두 맞을 수 있다. 5813을 반올림하여 백의 자리까지 나타내면 5800이고, 천의 자리까지 나타내면 6000이다. 어느 자리까지 어림했는지가 다를 뿐 둘 다 바르게 반올림했다.","scoring_points":["모두 맞을 수 있다고 판단했는가","백의 자리까지 5800임을 썼는가","천의 자리까지 6000임을 쓰고 자리가 다르다고 설명했는가"]},"explanation":["백의 자리까지 — 5800이에요.","천의 자리까지 — 6000이에요.","어림한 자리가 달라 둘 다 맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_L07_challenge#10','math',5,2,'u1','L07','g5_2_math_u1_L07_challenge','lesson_challenge','M5-2-u1-C6',4,'mc','auto','네 자리 수 3□84를 반올림하여 천의 자리까지 나타내면 4000이에요. □에 들어갈 수 있는 숫자는 모두 몇 개인가요?',ARRAY['M5-2-u1-X11','M5-2-u1-X16','M5-2-u1-X15']::text[],true,'{"seq":10,"concept":"M5-2-u1-C6","difficulty":4,"kind":"mc","stem":"네 자리 수 3□84를 반올림하여 천의 자리까지 나타내면 4000이에요. □에 들어갈 수 있는 숫자는 모두 몇 개인가요?","options":[{"t":"5개","correct":true},{"t":"4개","mis":"M5-2-u1-X11"},{"t":"6개","mis":"M5-2-u1-X16"},{"t":"10개","mis":"M5-2-u1-X15"}],"explanation":["천의 자리까지 반올림하면 백의 자리 □를 봐요.","4000이 되려면 올려야 하니 □는 5, 6, 7, 8, 9예요.","모두 5개예요."],"variant_rule":{"alt":[{"stem":"네 자리 수 6□72를 반올림하여 백의 자리까지 나타내면 6800이에요. □에 들어갈 수 있는 숫자는 모두 몇 개인가요?","options":[{"t":"1개","correct":true},{"t":"2개","mis":"M5-2-u1-X10"},{"t":"0개","mis":"M5-2-u1-X16"},{"t":"5개","mis":"M5-2-u1-X15"}],"explanation":["6800이 되려면 6750 이상 6850 미만이어야 해요.","6□72 중 6772만 이 범위에 들어가요 — 6872는 6900이에요.","□ = 7 하나뿐이라 1개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_L08_basic#1','math',5,2,'u1','L08','g5_2_math_u1_L08_basic','lesson_basic','M5-2-u1-C7',1,'mc','auto','재생 천으로 만든 필통이 11200원이에요. 지폐로만 낸다면 낼 돈을 정할 때 알맞은 어림 방법은 어느 것인가요?',ARRAY['M5-2-u1-X13']::text[],true,'{"seq":1,"concept":"M5-2-u1-C7","difficulty":1,"kind":"mc","stem":"재생 천으로 만든 필통이 11200원이에요. 지폐로만 낸다면 낼 돈을 정할 때 알맞은 어림 방법은 어느 것인가요?","options":[{"t":"올림","correct":true},{"t":"버림","mis":"M5-2-u1-X13"},{"t":"반올림","mis":"M5-2-u1-X13"},{"t":"아무 방법이나 좋다","mis":"M5-2-u1-X13"}],"explanation":["지폐로만 내면 11200원보다 적게 내서는 안 돼요.","모자라면 살 수 없어요.","모자라지 않게 크게 어림하는 올림이 알맞아요."],"variant_rule":{"alt":[{"stem":"저금통의 동전이 모두 58600원이에요. 지폐로 바꿀 수 있는 돈을 정할 때 알맞은 어림 방법은 어느 것인가요?","options":[{"t":"버림","correct":true},{"t":"올림","mis":"M5-2-u1-X13"},{"t":"반올림","mis":"M5-2-u1-X13"},{"t":"아무 방법이나 좋다","mis":"M5-2-u1-X13"}],"explanation":["지폐 한 장이 되지 못하는 동전은 바꿀 수 없어요.","남는 동전은 지폐가 되지 못해요.","남는 것을 버리는 버림이 알맞아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_L08_basic#2','math',5,2,'u1','L08','g5_2_math_u1_L08_basic','lesson_basic','M5-2-u1-C7',1,'mc','auto','필통 11200원을 10000원짜리 지폐로만 낸다면 최소 얼마를 내야 하나요?',ARRAY['M5-2-u1-X13','M5-2-u1-X09','M5-2-u1-X08']::text[],true,'{"seq":2,"concept":"M5-2-u1-C7","difficulty":1,"kind":"mc","stem":"필통 11200원을 10000원짜리 지폐로만 낸다면 최소 얼마를 내야 하나요?","options":[{"t":"20000원","correct":true},{"t":"10000원","mis":"M5-2-u1-X13"},{"t":"12000원","mis":"M5-2-u1-X09"},{"t":"11000원","mis":"M5-2-u1-X08"}],"explanation":["10000원짜리 1장은 10000원이라 모자라요.","모자라지 않게 11200을 올림하여 만의 자리까지 나타내요.","11200 → 20000원, 2장을 내요."],"variant_rule":{"alt":[{"stem":"필통 11200원을 1000원짜리 지폐로만 낸다면 최소 얼마를 내야 하나요?","options":[{"t":"12000원","correct":true},{"t":"11000원","mis":"M5-2-u1-X13"},{"t":"20000원","mis":"M5-2-u1-X09"},{"t":"11200원","mis":"M5-2-u1-X17"}],"explanation":["1000원짜리 11장은 11000원이라 모자라요.","11200을 올림하여 천의 자리까지 나타내요.","11200 → 12000원, 12장을 내요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_L08_basic#3','math',5,2,'u1','L08','g5_2_math_u1_L08_basic','lesson_basic','M5-2-u1-C7',1,'mc','auto','동전 58600원을 10000원짜리 지폐로만 바꾼다면 최대 얼마까지 바꿀 수 있나요?',ARRAY['M5-2-u1-X13','M5-2-u1-X09','M5-2-u1-X08']::text[],true,'{"seq":3,"concept":"M5-2-u1-C7","difficulty":1,"kind":"mc","stem":"동전 58600원을 10000원짜리 지폐로만 바꾼다면 최대 얼마까지 바꿀 수 있나요?","options":[{"t":"50000원","correct":true},{"t":"60000원","mis":"M5-2-u1-X13"},{"t":"58000원","mis":"M5-2-u1-X09"},{"t":"59000원","mis":"M5-2-u1-X08"}],"explanation":["10000원이 다 차야 지폐 한 장이에요.","58600을 버림하여 만의 자리까지 나타내요.","58600 → 50000원, 5장이에요."],"variant_rule":{"alt":[{"stem":"동전 58600원을 1000원짜리 지폐로 바꾼다면 최대 얼마까지 바꿀 수 있나요?","options":[{"t":"58000원","correct":true},{"t":"59000원","mis":"M5-2-u1-X13"},{"t":"50000원","mis":"M5-2-u1-X09"},{"t":"58600원","mis":"M5-2-u1-X17"}],"explanation":["1000원이 다 차야 한 장이에요.","58600을 버림하여 천의 자리까지 나타내요.","58600 → 58000원, 58장이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_L08_basic#4','math',5,2,'u1','L08','g5_2_math_u1_L08_basic','lesson_basic','M5-2-u1-C7',1,'mc','auto','도시별 인구를 그래프로 나타내려고 실제와 가깝게 반올림해요. 부산광역시 인구 3259219명을 반올림하여 만의 자리까지 나타내면 몇 명인가요?',ARRAY['M5-2-u1-X08','M5-2-u1-X09']::text[],true,'{"seq":4,"concept":"M5-2-u1-C7","difficulty":1,"kind":"mc","stem":"도시별 인구를 그래프로 나타내려고 실제와 가깝게 반올림해요. 부산광역시 인구 3259219명을 반올림하여 만의 자리까지 나타내면 몇 명인가요?","options":[{"t":"3260000명","correct":true},{"t":"3250000명","mis":"M5-2-u1-X08"},{"t":"3259000명","mis":"M5-2-u1-X09"},{"t":"3259200명","mis":"M5-2-u1-X09"}],"explanation":["반올림은 구하려는 자리 바로 아래 한 자리만 봐요.","만의 자리 바로 아래 숫자가 9라 올려요.","3259219 → 3260000이에요."],"variant_rule":{"alt":[{"stem":"도시별 인구를 그래프로 나타내려고 실제와 가깝게 반올림해요. 가 도시의 인구 2374960명을 반올림하여 만의 자리까지 나타내면 몇 명인가요?","options":[{"t":"2370000명","correct":true},{"t":"2380000명","mis":"M5-2-u1-X10"},{"t":"2375000명","mis":"M5-2-u1-X09"},{"t":"2400000명","mis":"M5-2-u1-X09"}],"explanation":["반올림은 구하려는 자리 바로 아래 한 자리만 봐요.","만의 자리 바로 아래 숫자가 4라 버려요.","2374960 → 2370000이에요."]},{"stem":"도시별 인구를 그래프로 나타내려고 실제와 가깝게 반올림해요. 나 도시의 인구 1419237명을 반올림하여 만의 자리까지 나타내면 몇 명인가요?","options":[{"t":"1420000명","correct":true},{"t":"1410000명","mis":"M5-2-u1-X08"},{"t":"1419000명","mis":"M5-2-u1-X09"},{"t":"1419200명","mis":"M5-2-u1-X09"}],"explanation":["반올림은 구하려는 자리 바로 아래 한 자리만 봐요.","만의 자리 바로 아래 숫자가 9라 올려요.","1419237 → 1420000이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_L08_basic#5','math',5,2,'u1','L08','g5_2_math_u1_L08_basic','lesson_basic','M5-2-u1-C7',2,'mc','auto','포도 한 송이의 무게는 0.758 kg이에요. 반올림하여 소수 첫째 자리까지 나타내면 몇 kg인가요?',ARRAY['M5-2-u1-X08','M5-2-u1-X09']::text[],true,'{"seq":5,"concept":"M5-2-u1-C7","difficulty":2,"kind":"mc","stem":"포도 한 송이의 무게는 0.758 kg이에요. 반올림하여 소수 첫째 자리까지 나타내면 몇 kg인가요?","options":[{"t":"0.8 kg","correct":true},{"t":"0.7 kg","mis":"M5-2-u1-X08"},{"t":"0.76 kg","mis":"M5-2-u1-X09"},{"t":"1 kg","mis":"M5-2-u1-X09"}],"explanation":["반올림은 구하려는 자리 바로 아래 한 자리만 봐요.","소수 첫째 자리 바로 아래 숫자가 0이라 버려요.","0.758 → 0.8이에요."],"variant_rule":{"alt":[{"stem":"연필의 길이는 14.36 cm예요. 반올림하여 소수 첫째 자리까지 나타내면 몇 cm인가요?","options":[{"t":"14.4 kg","correct":true},{"t":"14.3 kg","mis":"M5-2-u1-X08"},{"t":"14 kg","mis":"M5-2-u1-X09"},{"t":"14.5 kg","mis":"M5-2-u1-X16"}],"explanation":["반올림은 구하려는 자리 바로 아래 한 자리만 봐요.","소수 첫째 자리 바로 아래 숫자가 0이라 버려요.","14.36 → 14.4예요."]},{"stem":"수박의 무게는 6.451 kg이에요. 반올림하여 소수 첫째 자리까지 나타내면 몇 kg인가요?","options":[{"t":"6.5 kg","correct":true},{"t":"6.4 kg","mis":"M5-2-u1-X08"},{"t":"6.45 kg","mis":"M5-2-u1-X09"},{"t":"6 kg","mis":"M5-2-u1-X09"}],"explanation":["반올림은 구하려는 자리 바로 아래 한 자리만 봐요.","소수 첫째 자리 바로 아래 숫자가 0이라 버려요.","6.451 → 6.5예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_L08_basic#6','math',5,2,'u1','L08','g5_2_math_u1_L08_basic','lesson_basic','M5-2-u1-C7',2,'mc','auto','국립 공원의 넓이를 어림했어요 — 2276.209 → 2276 · 228.919 → 229 · 485.647 → 486. 어떤 방법으로 어림했나요?',ARRAY['M5-2-u1-X08']::text[],true,'{"seq":6,"concept":"M5-2-u1-C7","difficulty":2,"kind":"mc","stem":"국립 공원의 넓이를 어림했어요 — 2276.209 → 2276 · 228.919 → 229 · 485.647 → 486. 어떤 방법으로 어림했나요?","options":[{"t":"반올림","correct":true},{"t":"올림","mis":"M5-2-u1-X08"},{"t":"버림","mis":"M5-2-u1-X08"},{"t":"셋 다 아니다","mis":"M5-2-u1-X08"}],"explanation":["2276.209는 일의 자리 아래를 버렸고, 228.919와 485.647은 올렸어요.","올림이라면 2277, 버림이라면 228·485가 되었어요.","소수 첫째 자리 숫자(2 버림, 9·6 올림)로 정했으니 반올림이에요."],"variant_rule":{"alt":[{"stem":"호수의 둘레를 어림했어요 — 13.42 → 14 · 8.91 → 9 · 25.05 → 26. 어떤 방법으로 어림했나요?","options":[{"t":"올림","correct":true},{"t":"반올림","mis":"M5-2-u1-X08"},{"t":"버림","mis":"M5-2-u1-X08"},{"t":"셋 다 아니다","mis":"M5-2-u1-X08"}],"explanation":["13.42와 25.05도 일의 자리 아래를 올렸어요.","반올림이라면 13·25, 버림이라면 13·8·25예요.","아래 수를 모두 올렸으니 올림이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_L08_basic#7','math',5,2,'u1','L08','g5_2_math_u1_L08_basic','lesson_basic','M5-2-u1-C7',2,'sa','auto','음료수를 32명에게 한 개씩 나누어 줘요. 음료수를 10개씩 묶음으로만 판다면 최소 몇 개를 사야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M5-2-u1-C7","difficulty":2,"kind":"sa","stem":"음료수를 32명에게 한 개씩 나누어 줘요. 음료수를 10개씩 묶음으로만 판다면 최소 몇 개를 사야 하나요? 숫자로 쓰세요.","answer":["40","40개"],"explanation":["3묶음 30개로는 2명이 받지 못해요.","모자라면 안 되니 32를 올림하여 십의 자리까지 나타내요.","32 → 40개, 4묶음이에요."],"variant_rule":{"alt":[{"stem":"엘리베이터에 한 번에 10명까지 탈 수 있어요. 53명이 모두 올라가려면 최소 몇 번 운행해야 하나요? 숫자로 쓰세요.","answer":["6","6번"],"explanation":["5번 운행하면 50명뿐이라 3명이 남아요.","모두 태워야 하니 53을 올림하여 십의 자리까지 → 60명이에요.","60명은 10명씩 6번이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_L08_basic#8','math',5,2,'u1','L08','g5_2_math_u1_L08_basic','lesson_basic','M5-2-u1-C7',2,'ox','auto','같은 돈이라도 상황에 따라 올림을 쓰기도 하고 버림을 쓰기도 해요.',ARRAY['M5-2-u1-X13']::text[],true,'{"seq":8,"concept":"M5-2-u1-C7","difficulty":2,"kind":"ox","stem":"같은 돈이라도 상황에 따라 올림을 쓰기도 하고 버림을 쓰기도 해요.","answer":"O","reason_options":[{"t":"수가 아니라 하려는 일(내기·바꾸기)이 어림 방법을 정해서","correct":true},{"t":"돈은 언제나 반올림해서","mis":"M5-2-u1-X13"}],"mis":"M5-2-u1-X13","explanation":["필통값을 낼 때는 모자라면 안 되니 올림이에요.","동전을 지폐로 바꿀 때는 남는 동전을 못 쓰니 버림이에요.","같은 돈이라도 상황이 방법을 정해요."],"variant_rule":{"alt":[{"stem":"어림 방법은 수가 크면 올림, 작으면 버림으로 정해요.","answer":"X","reason_options":[{"t":"수의 크기가 아니라 상황(모자라면 안 되는지, 남는 것을 쓸 수 있는지)이 정해서","correct":true},{"t":"큰 수는 언제나 올려야 해서","mis":"M5-2-u1-X13"}],"explanation":["어림 방법은 수의 크기로 정하지 않아요.","모자라면 안 되면 올림, 남는 것을 못 쓰면 버림이에요.","실제와 가깝게 하려면 반올림이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_L08_basic#9','math',5,2,'u1','L08','g5_2_math_u1_L08_basic','lesson_basic','M5-2-u1-C7',2,'match','auto','상황에 알맞은 어림 방법을 이으세요.','{}'::text[],true,'{"seq":9,"concept":"M5-2-u1-C7","difficulty":2,"kind":"match","stem":"상황에 알맞은 어림 방법을 이으세요.","pairs":[{"l":"학생을 모두 태울 버스 수 구하기","r":"올림"},{"l":"상자에 담아 팔 수 있는 사과 수 구하기","r":"버림"},{"l":"그래프에 실제와 가까운 인구 나타내기","r":"반올림"}],"mis":"M5-2-u1-X13","explanation":["모두 태워야 하면 모자라면 안 돼 올림이에요.","상자를 채우지 못한 사과는 못 팔아 버림이에요.","실제와 차이를 작게 하려면 반올림이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 상황에 알맞은 어림 방법을 이으세요.","pairs":[{"l":"키를 실제와 가깝게 기록하기","r":"반올림"},{"l":"물건값을 지폐로만 내기","r":"올림"},{"l":"동전을 지폐로 바꾸기","r":"버림"}],"explanation":["실제와 가깝게 — 반올림이에요.","물건값은 모자라면 안 돼 올림이에요.","남는 동전은 바꿀 수 없어 버림이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_L08_basic#10','math',5,2,'u1','L08','g5_2_math_u1_L08_basic','lesson_basic','M5-2-u1-C7',3,'mc','auto','세 친구가 말했어요. 어림한 방법이 다른 친구는 누구인가요? 지민 — 「젤리 423개를 10개씩 담아 420개까지 팔 수 있어요.」 유나 — 「1000원짜리 48장을 10000원짜리로 40000원까지 바꿀 수 있어요.」 시은 — 「엘리베이터에 10명까지 타서 53명이 이동하려면 6번 운행해야 해요.」',ARRAY['M5-2-u1-X13']::text[],true,'{"seq":10,"concept":"M5-2-u1-C7","difficulty":3,"kind":"mc","stem":"세 친구가 말했어요. 어림한 방법이 다른 친구는 누구인가요? 지민 — 「젤리 423개를 10개씩 담아 420개까지 팔 수 있어요.」 유나 — 「1000원짜리 48장을 10000원짜리로 40000원까지 바꿀 수 있어요.」 시은 — 「엘리베이터에 10명까지 타서 53명이 이동하려면 6번 운행해야 해요.」","options":[{"t":"시은","correct":true},{"t":"지민","mis":"M5-2-u1-X13"},{"t":"유나","mis":"M5-2-u1-X13"},{"t":"모두 같다","mis":"M5-2-u1-X13"}],"explanation":["지민 — 담지 못한 3개를 버렸으니 버림이에요.","유나 — 바꾸지 못한 8000원을 버렸으니 버림이에요.","시은 — 남은 3명도 태워야 해 올림이에요. 다른 친구는 시은이에요."],"variant_rule":{"alt":[{"stem":"세 친구가 말했어요. 어림한 방법이 다른 친구는 누구인가요? 도하 — 「학생 128명에게 줄 공책을 10권 묶음으로 130권 사요.」 리아 — 「손님 45명이 앉도록 4인용 식탁을 12개 놓아요.」 준 — 「귤 87개를 10개씩 봉지에 담아 8봉지를 팔아요.」","options":[{"t":"준","correct":true},{"t":"도하","mis":"M5-2-u1-X13"},{"t":"리아","mis":"M5-2-u1-X13"},{"t":"모두 같다","mis":"M5-2-u1-X13"}],"explanation":["도하 — 모자라면 안 돼 올림이에요.","리아 — 남은 1명도 앉아야 해 올림이에요(4 × 11 = 44).","준 — 못 채운 7개를 버렸으니 버림이에요. 다른 친구는 준이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_L08_challenge#1','math',5,2,'u1','L08','g5_2_math_u1_L08_challenge','lesson_challenge','M5-2-u1-C7',2,'mc','auto','오늘 극장에 온 관람객은 5217명이에요. 올림하여 백의 자리까지 나타내면 몇 명인가요?',ARRAY['M5-2-u1-X08','M5-2-u1-X09']::text[],true,'{"seq":1,"concept":"M5-2-u1-C7","difficulty":2,"kind":"mc","stem":"오늘 극장에 온 관람객은 5217명이에요. 올림하여 백의 자리까지 나타내면 몇 명인가요?","options":[{"t":"5300명","correct":true},{"t":"5200명","mis":"M5-2-u1-X08"},{"t":"5220명","mis":"M5-2-u1-X09"},{"t":"6000명","mis":"M5-2-u1-X09"}],"explanation":["올림은 백의 자리 아래 수(17)을 올려서 나타내요.","아래 숫자가 무엇이든 0이 아니면 한 칸 올리고, 아래는 0으로 채워요.","5217 → 5300이에요."],"variant_rule":{"alt":[{"stem":"오늘 극장에 온 관람객은 5217명이에요. 버림하여 백의 자리까지 나타내면 몇 명인가요?","options":[{"t":"5300명","correct":true},{"t":"5200명","mis":"M5-2-u1-X08"},{"t":"5220명","mis":"M5-2-u1-X09"},{"t":"6000명","mis":"M5-2-u1-X09"}],"explanation":["올림은 백의 자리 아래 수(17)을 올려서 나타내요.","아래 숫자가 무엇이든 0이 아니면 한 칸 올리고, 아래는 0으로 채워요.","5217 → 5300이에요."]},{"stem":"어제 수족관에 온 관람객은 3486명이에요. 올림하여 백의 자리까지 나타내면 몇 명인가요?","options":[{"t":"3500명","correct":true},{"t":"3400명","mis":"M5-2-u1-X08"},{"t":"3490명","mis":"M5-2-u1-X09"},{"t":"4000명","mis":"M5-2-u1-X09"}],"explanation":["올림은 백의 자리 아래 수(86)을 올려서 나타내요.","아래 숫자가 무엇이든 0이 아니면 한 칸 올리고, 아래는 0으로 채워요.","3486 → 3500이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_L08_challenge#2','math',5,2,'u1','L08','g5_2_math_u1_L08_challenge','lesson_challenge','M5-2-u1-C7',2,'mc','auto','다음 수를 백의 자리까지 버림한 수와 반올림한 수가 서로 다른 것은 어느 것인가요?',ARRAY['M5-2-u1-X08']::text[],true,'{"seq":2,"concept":"M5-2-u1-C7","difficulty":2,"kind":"mc","stem":"다음 수를 백의 자리까지 버림한 수와 반올림한 수가 서로 다른 것은 어느 것인가요?","options":[{"t":"5267","correct":true},{"t":"5217","mis":"M5-2-u1-X08"},{"t":"5240","mis":"M5-2-u1-X08"},{"t":"5209","mis":"M5-2-u1-X08"}],"explanation":["십의 자리 숫자가 0~4면 반올림도 버리니 버림과 같아요.","5217·5240·5209는 모두 5200으로 같아요.","5267은 버림 5200, 반올림 5300으로 달라요."],"variant_rule":{"alt":[{"stem":"다음 수를 십의 자리까지 올림한 수와 반올림한 수가 서로 다른 것은 어느 것인가요?","options":[{"t":"832","correct":true},{"t":"836","mis":"M5-2-u1-X08"},{"t":"839","mis":"M5-2-u1-X08"},{"t":"835","mis":"M5-2-u1-X08"}],"explanation":["일의 자리 숫자가 5~9면 반올림도 올리니 올림과 같아요.","836·839·835는 모두 840이에요.","832는 올림 840, 반올림 830으로 달라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_L08_challenge#3','math',5,2,'u1','L08','g5_2_math_u1_L08_challenge','lesson_challenge','M5-2-u1-C7',3,'mc','auto','밭에서 딴 가지 73 kg을 한 상자에 10 kg씩 담아 팔아요. 한 상자에 20000원씩 받고 담은 상자를 모두 판다면 얼마를 받나요?',ARRAY['M5-2-u1-X13','M5-2-u1-X17','M5-2-u1-X14']::text[],true,'{"seq":3,"concept":"M5-2-u1-C7","difficulty":3,"kind":"mc","stem":"밭에서 딴 가지 73 kg을 한 상자에 10 kg씩 담아 팔아요. 한 상자에 20000원씩 받고 담은 상자를 모두 판다면 얼마를 받나요?","options":[{"t":"140000원","correct":true},{"t":"160000원","mis":"M5-2-u1-X13"},{"t":"146000원","mis":"M5-2-u1-X17"},{"t":"14000원","mis":"M5-2-u1-X14"}],"explanation":["10 kg이 다 차야 한 상자예요 — 73을 버림하여 십의 자리까지 → 70 kg, 7상자예요.","남는 3 kg은 상자를 채우지 못해요.","7상자 × 20000원 = 140000원이에요."],"variant_rule":{"alt":[{"stem":"밭에서 딴 감자 128 kg을 한 상자에 20 kg씩 담아 팔아요. 한 상자에 15000원씩 받고 담은 상자를 모두 판다면 얼마를 받나요?","options":[{"t":"90000원","correct":true},{"t":"105000원","mis":"M5-2-u1-X13"},{"t":"96000원","mis":"M5-2-u1-X17"},{"t":"6000원","mis":"M5-2-u1-X14"}],"explanation":["20 kg이 다 차야 한 상자예요 — 20 × 6 = 120 kg, 6상자예요.","남는 8 kg은 상자를 채우지 못해요.","6상자 × 15000원 = 90000원이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_L08_challenge#4','math',5,2,'u1','L08','g5_2_math_u1_L08_challenge','lesson_challenge','M5-2-u1-C7',3,'mc','auto','케이블카에 한 번에 8명까지 탈 수 있어요. 학생 61명이 모두 타려면 케이블카는 최소 몇 번 운행해야 하나요?',ARRAY['M5-2-u1-X13','M5-2-u1-X16','M5-2-u1-X14']::text[],true,'{"seq":4,"concept":"M5-2-u1-C7","difficulty":3,"kind":"mc","stem":"케이블카에 한 번에 8명까지 탈 수 있어요. 학생 61명이 모두 타려면 케이블카는 최소 몇 번 운행해야 하나요?","options":[{"t":"8번","correct":true},{"t":"7번","mis":"M5-2-u1-X13"},{"t":"9번","mis":"M5-2-u1-X16"},{"t":"61번","mis":"M5-2-u1-X14"}],"explanation":["7번 운행하면 8 × 7 = 56명이라 5명이 남아요.","남은 5명도 타야 하니 한 번 더 — 올림이에요.","8번 운행해야 해요."],"variant_rule":{"alt":[{"stem":"보트에 한 번에 6명까지 탈 수 있어요. 39명이 모두 타려면 보트는 최소 몇 번 운행해야 하나요?","options":[{"t":"7번","correct":true},{"t":"6번","mis":"M5-2-u1-X13"},{"t":"8번","mis":"M5-2-u1-X16"},{"t":"39번","mis":"M5-2-u1-X14"}],"explanation":["6번 운행하면 6 × 6 = 36명이라 3명이 남아요.","남은 3명도 타야 하니 한 번 더예요.","7번 운행해야 해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_L08_challenge#5','math',5,2,'u1','L08','g5_2_math_u1_L08_challenge','lesson_challenge','M5-2-u1-C7',3,'mc','auto','빵을 만드는 데 밀가루 3.2 kg이 필요해요. 밀가루를 1 kg짜리 봉지로만 판다면 최소 몇 봉지를 사야 하나요?',ARRAY['M5-2-u1-X13','M5-2-u1-X16','M5-2-u1-X14']::text[],true,'{"seq":5,"concept":"M5-2-u1-C7","difficulty":3,"kind":"mc","stem":"빵을 만드는 데 밀가루 3.2 kg이 필요해요. 밀가루를 1 kg짜리 봉지로만 판다면 최소 몇 봉지를 사야 하나요?","options":[{"t":"4봉지","correct":true},{"t":"3봉지","mis":"M5-2-u1-X13"},{"t":"5봉지","mis":"M5-2-u1-X16"},{"t":"32봉지","mis":"M5-2-u1-X14"}],"explanation":["3봉지는 3 kg이라 0.2 kg이 모자라요.","모자라면 빵을 못 만드니 3.2를 올림하여 일의 자리까지 나타내요.","3.2 → 4, 4봉지예요."],"variant_rule":{"alt":[{"stem":"화분을 채우는 데 흙 5.1 L가 필요해요. 흙을 1 L짜리 봉지로만 판다면 최소 몇 봉지를 사야 하나요?","options":[{"t":"6봉지","correct":true},{"t":"5봉지","mis":"M5-2-u1-X13"},{"t":"7봉지","mis":"M5-2-u1-X16"},{"t":"51봉지","mis":"M5-2-u1-X14"}],"explanation":["5봉지는 5 L라 0.1 L가 모자라요.","5.1을 올림하여 일의 자리까지 나타내요.","5.1 → 6, 6봉지예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_L08_challenge#6','math',5,2,'u1','L08','g5_2_math_u1_L08_challenge','lesson_challenge','M5-2-u1-C7',3,'mc','auto','우리 반 33명에게 사탕을 2개씩 나누어 주려고 해요. 사탕을 10개 묶음으로만 판다면 최소 몇 묶음을 사야 하나요?',ARRAY['M5-2-u1-X13','M5-2-u1-X16','M5-2-u1-X14']::text[],true,'{"seq":6,"concept":"M5-2-u1-C7","difficulty":3,"kind":"mc","stem":"우리 반 33명에게 사탕을 2개씩 나누어 주려고 해요. 사탕을 10개 묶음으로만 판다면 최소 몇 묶음을 사야 하나요?","options":[{"t":"7묶음","correct":true},{"t":"6묶음","mis":"M5-2-u1-X13"},{"t":"4묶음","mis":"M5-2-u1-X16"},{"t":"66묶음","mis":"M5-2-u1-X14"}],"explanation":["필요한 사탕은 33 × 2 = 66개예요.","6묶음 60개로는 모자라 66을 올림하여 십의 자리까지 → 70개예요.","70개는 7묶음이에요."],"variant_rule":{"alt":[{"stem":"우리 학년 47명에게 색종이를 3장씩 나누어 주려고 해요. 색종이를 100장 묶음으로만 판다면 최소 몇 묶음을 사야 하나요?","options":[{"t":"2묶음","correct":true},{"t":"1묶음","mis":"M5-2-u1-X13"},{"t":"3묶음","mis":"M5-2-u1-X16"},{"t":"141묶음","mis":"M5-2-u1-X14"}],"explanation":["필요한 색종이는 47 × 3 = 141장이에요.","1묶음 100장으로는 모자라 141을 올림하여 백의 자리까지 → 200장이에요.","200장은 2묶음이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_L08_challenge#7','math',5,2,'u1','L08','g5_2_math_u1_L08_challenge','lesson_challenge','M5-2-u1-C7',3,'error','auto','친구들이 어림 방법을 골랐어요. 잘못 고른 친구는 누구인가요?',ARRAY['M5-2-u1-X13','M5-2-u1-X17']::text[],true,'{"seq":7,"concept":"M5-2-u1-C7","difficulty":3,"kind":"error","stem":"친구들이 어림 방법을 골랐어요. 잘못 고른 친구는 누구인가요?","options":[{"t":"서윤 — 「인구를 그래프에 실제와 가깝게 나타내려고 3259219명을 버림해서 3250000명으로 했어.」","correct":true,"mis_target":"M5-2-u1-X13"},{"t":"하민 — 「11200원짜리 필통을 10000원짜리로 내려고 올림해서 20000원을 냈어.」","mis":"M5-2-u1-X17"},{"t":"지율 — 「단감 4953개를 100개씩 포장하려고 버림해서 4900개를 포장했어.」","mis":"M5-2-u1-X17"}],"explanation":["실제와 가깝게 나타내려면 반올림이 알맞아요.","3259219를 반올림하여 만의 자리까지 → 3260000명이에요.","서윤이는 버림을 골라 실제와 차이가 커졌어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 친구들이 어림 방법을 골랐어요. 잘못 고른 친구는 누구인가요?","options":[{"t":"채아 — 「학생 136명을 45인승 버스에 태우려고 버림해서 3대를 불렀어.」","correct":true,"mis_target":"M5-2-u1-X13"},{"t":"로운 — 「동전 37450원을 10000원짜리로 바꾸려고 버림해서 30000원을 바꿨어.」","mis":"M5-2-u1-X17"},{"t":"은솔 — 「키 142.6 cm를 실제와 가깝게 반올림해서 143 cm로 적었어.」","mis":"M5-2-u1-X17"}],"explanation":["사람을 모두 태워야 하면 모자라면 안 돼요.","3대에는 135명만 타니 1명이 남아요 — 올림해서 4대예요.","채아는 버림을 골라 1명이 못 탔어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_L08_challenge#8','math',5,2,'u1','L08','g5_2_math_u1_L08_challenge','lesson_challenge','M5-2-u1-C7',4,'essay','teacher','필통값 11200원을 지폐로 낼 때는 올림을, 동전 58600원을 지폐로 바꿀 때는 버림을 썼어요. 둘 다 돈인데 어림 방법이 갈린 까닭을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"M5-2-u1-C7","difficulty":4,"kind":"essay","stem":"필통값 11200원을 지폐로 낼 때는 올림을, 동전 58600원을 지폐로 바꿀 때는 버림을 썼어요. 둘 다 돈인데 어림 방법이 갈린 까닭을 쓰세요.","answer_guide":{"answer":"예: 필통값은 모자라게 내면 필통을 살 수 없으니 모자라지 않도록 크게 어림하는 올림을 쓴다. 동전은 지폐 한 장을 채우지 못한 나머지는 바꿀 수 없으니 남는 것을 버리는 버림을 쓴다. 수가 아니라 상황이 방법을 정한다.","scoring_points":["필통은 모자라면 안 돼 올림이라고 썼는가","동전은 남는 것을 바꿀 수 없어 버림이라고 썼는가","상황이 방법을 정한다고 정리했는가"]},"explanation":["필통값 — 모자라면 안 돼 올림이에요.","동전 — 남는 것을 못 바꿔 버림이에요.","수가 아니라 상황이 방법을 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_L08_challenge#9','math',5,2,'u1','L08','g5_2_math_u1_L08_challenge','lesson_challenge','M5-2-u1-C7',4,'essay','teacher','관람객 5217명을 백의 자리까지 버림해도 반올림해도 5200이에요. 두 방법의 결과가 같아진 까닭을 쓰고, 두 결과가 달라지는 수를 하나 들어 설명하세요.','{}'::text[],false,'{"seq":9,"concept":"M5-2-u1-C7","difficulty":4,"kind":"essay","stem":"관람객 5217명을 백의 자리까지 버림해도 반올림해도 5200이에요. 두 방법의 결과가 같아진 까닭을 쓰고, 두 결과가 달라지는 수를 하나 들어 설명하세요.","answer_guide":{"answer":"예: 십의 자리 숫자가 1이라 반올림에서도 버려지기 때문이다. 5267처럼 십의 자리 숫자가 5~9이면 버림은 5200, 반올림은 5300으로 달라진다.","scoring_points":["십의 자리 숫자가 0~4라 반올림도 버린다는 까닭을 썼는가","결과가 달라지는 수의 예를 들었는가","그 수의 버림·반올림 결과를 바르게 썼는가"]},"explanation":["5217의 십의 자리 숫자는 1이라 반올림도 버려요.","그래서 버림과 같아요.","5267이면 버림 5200, 반올림 5300으로 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_L08_challenge#10','math',5,2,'u1','L08','g5_2_math_u1_L08_challenge','lesson_challenge','M5-2-u1-C7',4,'mc','auto','어떤 수를 백의 자리까지 올림한 수와 버림한 수가 같았어요. 어떤 수가 될 수 있는 것은 어느 것인가요?',ARRAY['M5-2-u1-X07','M5-2-u1-X08']::text[],true,'{"seq":10,"concept":"M5-2-u1-C7","difficulty":4,"kind":"mc","stem":"어떤 수를 백의 자리까지 올림한 수와 버림한 수가 같았어요. 어떤 수가 될 수 있는 것은 어느 것인가요?","options":[{"t":"4500","correct":true},{"t":"4501","mis":"M5-2-u1-X07"},{"t":"4550","mis":"M5-2-u1-X08"},{"t":"4499","mis":"M5-2-u1-X07"}],"explanation":["올림한 수와 버림한 수가 같으려면 올릴 것도 버릴 것도 없어야 해요.","백의 자리 아래가 00인 수만 그래요.","4500은 올림·버림 모두 4500이에요."],"variant_rule":{"alt":[{"stem":"어떤 수를 십의 자리까지 올림한 수와 버림한 수가 같았어요. 어떤 수가 될 수 있는 것은 어느 것인가요?","options":[{"t":"380","correct":true},{"t":"381","mis":"M5-2-u1-X07"},{"t":"385","mis":"M5-2-u1-X08"},{"t":"379","mis":"M5-2-u1-X07"}],"explanation":["올림한 수와 버림한 수가 같으려면 일의 자리가 0이어야 해요.","381·385·379는 올림과 버림이 10만큼 달라요.","380은 모두 380이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_L09_basic#1','math',5,2,'u1','L09','g5_2_math_u1_L09_basic','lesson_basic','M5-2-u1-C8',1,'sa','auto','카레 가루 480 g이 필요한데 100 g씩 한 봉지로 팔아요. 몇 봉지를 사야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M5-2-u1-C8","difficulty":1,"kind":"sa","stem":"카레 가루 480 g이 필요한데 100 g씩 한 봉지로 팔아요. 몇 봉지를 사야 하나요? 숫자로 쓰세요.","answer":["5","5봉지"],"explanation":["4봉지는 400 g이라 80 g이 모자라요.","모자라면 요리를 못 하니 올림이에요.","480 g → 500 g, 5봉지예요."],"variant_rule":{"alt":[{"stem":"고수 740 g이 필요한데 100 g씩 한 봉지로 팔아요. 몇 봉지를 사야 하나요? 숫자로 쓰세요.","answer":["8","8봉지"],"explanation":["7봉지는 700 g이라 40 g이 모자라요.","모자라면 요리를 못 하니 올림이에요.","740 g → 800 g, 8봉지예요."]},{"stem":"양파 가루 360 g이 필요한데 100 g씩 한 봉지로 팔아요. 몇 봉지를 사야 하나요? 숫자로 쓰세요.","answer":["4","4봉지"],"explanation":["3봉지는 300 g이라 60 g이 모자라요.","모자라면 요리를 못 하니 올림이에요.","360 g → 400 g, 4봉지예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_L09_basic#2','math',5,2,'u1','L09','g5_2_math_u1_L09_basic','lesson_basic','M5-2-u1-C8',1,'mc','auto','탄두리치킨 재료 — 닭고기 20마리(1마리 8800원, 1마리씩 판매) · 카레 가루 480 g(100 g 한 봉지 1900원) · 고춧가루 220 g(100 g 한 봉지 2150원). 고춧가루 220 g을 사려면 몇 봉지를 사야 하나요?',ARRAY['M5-2-u1-X13','M5-2-u1-X14','M5-2-u1-X16']::text[],true,'{"seq":2,"concept":"M5-2-u1-C8","difficulty":1,"kind":"mc","stem":"탄두리치킨 재료 — 닭고기 20마리(1마리 8800원, 1마리씩 판매) · 카레 가루 480 g(100 g 한 봉지 1900원) · 고춧가루 220 g(100 g 한 봉지 2150원). 고춧가루 220 g을 사려면 몇 봉지를 사야 하나요?","options":[{"t":"3봉지","correct":true},{"t":"2봉지","mis":"M5-2-u1-X13"},{"t":"22봉지","mis":"M5-2-u1-X14"},{"t":"4봉지","mis":"M5-2-u1-X16"}],"explanation":["2봉지는 200 g이라 20 g이 모자라요.","모자라면 안 되니 220을 올림하여 백의 자리까지 → 300 g이에요.","300 g은 3봉지예요."],"variant_rule":{"alt":[{"stem":"탄두리치킨 재료 — 닭고기 20마리(1마리 8800원, 1마리씩 판매) · 카레 가루 480 g(100 g 한 봉지 1900원) · 고춧가루 220 g(100 g 한 봉지 2150원). 카레 가루 480 g을 사려면 몇 봉지를 사야 하나요?","options":[{"t":"5봉지","correct":true},{"t":"4봉지","mis":"M5-2-u1-X13"},{"t":"48봉지","mis":"M5-2-u1-X14"},{"t":"6봉지","mis":"M5-2-u1-X16"}],"explanation":["4봉지는 400 g이라 80 g이 모자라요.","480을 올림하여 백의 자리까지 → 500 g이에요.","500 g은 5봉지예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_L09_basic#3','math',5,2,'u1','L09','g5_2_math_u1_L09_basic','lesson_basic','M5-2-u1-C8',1,'mc','auto','탄두리치킨 재료를 판매 단위에 맞게 「구입해야 하는 양」을 정할 때 쓴 어림 방법은 어느 것인가요?',ARRAY['M5-2-u1-X13','M5-2-u1-X17']::text[],false,'{"seq":3,"concept":"M5-2-u1-C8","difficulty":1,"kind":"mc","stem":"탄두리치킨 재료를 판매 단위에 맞게 「구입해야 하는 양」을 정할 때 쓴 어림 방법은 어느 것인가요?","options":[{"t":"올림","correct":true},{"t":"버림","mis":"M5-2-u1-X13"},{"t":"반올림","mis":"M5-2-u1-X13"},{"t":"어림하지 않았다","mis":"M5-2-u1-X17"}],"explanation":["480 g이 필요한데 400 g만 사면 요리를 못 해요.","모자라면 안 되니 필요한 양보다 크게 어림해요.","그래서 올림이에요 — 480 g → 500 g."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_L09_basic#4','math',5,2,'u1','L09','g5_2_math_u1_L09_basic','lesson_basic','M5-2-u1-C8',1,'mc','auto','탄두리치킨 재료 — 닭고기 20마리(1마리 8800원, 1마리씩 판매) · 카레 가루 480 g(100 g 한 봉지 1900원) · 고춧가루 220 g(100 g 한 봉지 2150원). 어림셈을 하려고 닭고기 한 마리 값 8800원을 반올림하여 천의 자리까지 나타내면 얼마인가요?',ARRAY['M5-2-u1-X08','M5-2-u1-X09','M5-2-u1-X16']::text[],true,'{"seq":4,"concept":"M5-2-u1-C8","difficulty":1,"kind":"mc","stem":"탄두리치킨 재료 — 닭고기 20마리(1마리 8800원, 1마리씩 판매) · 카레 가루 480 g(100 g 한 봉지 1900원) · 고춧가루 220 g(100 g 한 봉지 2150원). 어림셈을 하려고 닭고기 한 마리 값 8800원을 반올림하여 천의 자리까지 나타내면 얼마인가요?","options":[{"t":"9000원","correct":true},{"t":"8000원","mis":"M5-2-u1-X08"},{"t":"10000원","mis":"M5-2-u1-X09"},{"t":"11000원","mis":"M5-2-u1-X16"}],"explanation":["반올림은 구하려는 자리 바로 아래 한 자리만 봐요.","천의 자리 바로 아래 숫자가 8이라 올려요.","8800 → 9000이에요."],"variant_rule":{"alt":[{"stem":"탄두리치킨 재료 — 닭고기 20마리(1마리 8800원, 1마리씩 판매) · 카레 가루 480 g(100 g 한 봉지 1900원) · 고춧가루 220 g(100 g 한 봉지 2150원). 어림셈을 하려고 카레 가루 한 봉지 값 1900원을 반올림하여 천의 자리까지 나타내면 얼마인가요?","options":[{"t":"2000원","correct":true},{"t":"1000원","mis":"M5-2-u1-X08"},{"t":"3000원","mis":"M5-2-u1-X16"},{"t":"4000원","mis":"M5-2-u1-X16"}],"explanation":["반올림은 구하려는 자리 바로 아래 한 자리만 봐요.","천의 자리 바로 아래 숫자가 9라 올려요.","1900 → 2000이에요."]},{"stem":"탄두리치킨 재료 — 닭고기 20마리(1마리 8800원, 1마리씩 판매) · 카레 가루 480 g(100 g 한 봉지 1900원) · 고춧가루 220 g(100 g 한 봉지 2150원). 어림셈을 하려고 고춧가루 한 봉지 값 2150원을 반올림하여 천의 자리까지 나타내면 얼마인가요?","options":[{"t":"2000원","correct":true},{"t":"3000원","mis":"M5-2-u1-X08"},{"t":"2200원","mis":"M5-2-u1-X09"},{"t":"4000원","mis":"M5-2-u1-X16"}],"explanation":["반올림은 구하려는 자리 바로 아래 한 자리만 봐요.","천의 자리 바로 아래 숫자가 1이라 버려요.","2150 → 2000이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_L09_basic#5','math',5,2,'u1','L09','g5_2_math_u1_L09_basic','lesson_basic','M5-2-u1-C8',2,'mc','auto','탄두리치킨 재료 — 닭고기 20마리(1마리 8800원, 1마리씩 판매) · 카레 가루 480 g(100 g 한 봉지 1900원) · 고춧가루 220 g(100 g 한 봉지 2150원). 가격을 반올림하여 천의 자리까지 나타낸 값(9000원·2000원·2000원)으로 어림셈하면 탄두리치킨 재료의 구입 비용은 약 얼마인가요?',ARRAY['M5-2-u1-X08','M5-2-u1-X17','M5-2-u1-X16']::text[],false,'{"seq":5,"concept":"M5-2-u1-C8","difficulty":2,"kind":"mc","stem":"탄두리치킨 재료 — 닭고기 20마리(1마리 8800원, 1마리씩 판매) · 카레 가루 480 g(100 g 한 봉지 1900원) · 고춧가루 220 g(100 g 한 봉지 2150원). 가격을 반올림하여 천의 자리까지 나타낸 값(9000원·2000원·2000원)으로 어림셈하면 탄두리치킨 재료의 구입 비용은 약 얼마인가요?","options":[{"t":"196000원","correct":true},{"t":"199000원","mis":"M5-2-u1-X08"},{"t":"191950원","mis":"M5-2-u1-X17"},{"t":"186000원","mis":"M5-2-u1-X16"}],"explanation":["닭고기 9000 × 20 = 180000원이에요.","카레 가루 5봉지 2000 × 5 = 10000원, 고춧가루 3봉지 2000 × 3 = 6000원이에요.","모두 더하면 약 196000원이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_L09_basic#6','math',5,2,'u1','L09','g5_2_math_u1_L09_basic','lesson_basic','M5-2-u1-C8',2,'mc','auto','탄두리치킨 재료 — 닭고기 20마리(1마리 8800원, 1마리씩 판매) · 카레 가루 480 g(100 g 한 봉지 1900원) · 고춧가루 220 g(100 g 한 봉지 2150원). 계산기로 확인하면 탄두리치킨 재료의 실제 구입 비용은 모두 얼마인가요?',ARRAY['M5-2-u1-X17','M5-2-u1-X16']::text[],false,'{"seq":6,"concept":"M5-2-u1-C8","difficulty":2,"kind":"mc","stem":"탄두리치킨 재료 — 닭고기 20마리(1마리 8800원, 1마리씩 판매) · 카레 가루 480 g(100 g 한 봉지 1900원) · 고춧가루 220 g(100 g 한 봉지 2150원). 계산기로 확인하면 탄두리치킨 재료의 실제 구입 비용은 모두 얼마인가요?","options":[{"t":"191950원","correct":true},{"t":"196000원","mis":"M5-2-u1-X17"},{"t":"190950원","mis":"M5-2-u1-X16"},{"t":"176000원","mis":"M5-2-u1-X16"}],"explanation":["닭고기 8800 × 20 = 176000원이에요.","카레 가루 1900 × 5 = 9500원, 고춧가루 2150 × 3 = 6450원이에요.","176000 + 9500 + 6450 = 191950원이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_L09_basic#7','math',5,2,'u1','L09','g5_2_math_u1_L09_basic','lesson_basic','M5-2-u1-C8',2,'sa','auto','고수 740 g이 필요한데 100 g씩 한 봉지로 팔아요. 몇 봉지를 사야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M5-2-u1-C8","difficulty":2,"kind":"sa","stem":"고수 740 g이 필요한데 100 g씩 한 봉지로 팔아요. 몇 봉지를 사야 하나요? 숫자로 쓰세요.","answer":["8","8봉지"],"explanation":["7봉지는 700 g이라 40 g이 모자라요.","모자라면 요리를 못 하니 올림이에요.","740 g → 800 g, 8봉지예요."],"variant_rule":{"alt":[{"stem":"치즈 1350 g이 필요한데 500 g씩 한 봉지로 팔아요. 몇 봉지를 사야 하나요? 숫자로 쓰세요.","answer":["3","3봉지"],"explanation":["2봉지는 1000 g이라 350 g이 모자라요.","모자라면 요리를 못 하니 올림이에요.","1350 g → 1500 g, 3봉지예요."]},{"stem":"우유 2300 mL가 필요한데 1000 mL씩 한 봉지로 팔아요. 몇 봉지를 사야 하나요? 숫자로 쓰세요.","answer":["3","3봉지"],"explanation":["2봉지는 2000 mL라 300 mL가 모자라요.","모자라면 요리를 못 하니 올림이에요.","2300 mL → 3000 mL, 3봉지예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_L09_basic#8','math',5,2,'u1','L09','g5_2_math_u1_L09_basic','lesson_basic','M5-2-u1-C8',2,'mc','auto','피자를 만드는 데 토마토소스가 2 L 필요하고 1 L씩 팔아요. 2봉지만 사면 되는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['M5-2-u1-X13','M5-2-u1-X08']::text[],false,'{"seq":8,"concept":"M5-2-u1-C8","difficulty":2,"kind":"mc","stem":"피자를 만드는 데 토마토소스가 2 L 필요하고 1 L씩 팔아요. 2봉지만 사면 되는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"필요한 양이 판매 단위로 딱 나누어져 올릴 것이 없어서","correct":true},{"t":"토마토소스는 어림하지 않아도 되는 재료라서","mis":"M5-2-u1-X13"},{"t":"반올림하면 2가 되어서","mis":"M5-2-u1-X08"},{"t":"버림하면 2가 되어서","mis":"M5-2-u1-X08"}],"explanation":["2 L는 1 L씩 2봉지로 딱 맞아요.","올림할 때 아래 수가 모두 0이면 올리지 않아요.","그래서 2봉지면 모자라지도 남지도 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_L09_basic#9','math',5,2,'u1','L09','g5_2_math_u1_L09_basic','lesson_basic','M5-2-u1-C8',2,'ox','auto','구입해야 하는 재료의 양은 반올림으로 정해도 괜찮아요.',ARRAY['M5-2-u1-X13']::text[],true,'{"seq":9,"concept":"M5-2-u1-C8","difficulty":2,"kind":"ox","stem":"구입해야 하는 재료의 양은 반올림으로 정해도 괜찮아요.","answer":"X","reason_options":[{"t":"반올림하면 필요한 양보다 적게 사서 모자랄 수 있어서(220 g → 200 g)","correct":true},{"t":"대략 얼마인지만 알면 되어서","mis":"M5-2-u1-X13"}],"mis":"M5-2-u1-X13","explanation":["고춧가루 220 g을 반올림하면 200 g이에요.","200 g으로는 20 g이 모자라요.","양은 모자라면 안 되니 올림으로 정해요."],"variant_rule":{"alt":[{"stem":"재료의 구입 비용을 미리 대략 알아볼 때는 가격을 반올림해 어림셈해도 돼요.","answer":"O","reason_options":[{"t":"비용은 대략 얼마인지만 알면 되어 실제와 가까운 반올림이 알맞아서","correct":true},{"t":"비용은 언제나 올림해야 해서","mis":"M5-2-u1-X13"}],"explanation":["비용 예상은 정확한 값이 아니어도 돼요.","계산하기 쉬운 수로 바꾸되 실제와 가깝게 해요.","그래서 반올림으로 어림셈해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_L09_basic#10','math',5,2,'u1','L09','g5_2_math_u1_L09_basic','lesson_basic','M5-2-u1-C8',3,'mc','auto','탄두리치킨 재료 — 닭고기 20마리(1마리 8800원, 1마리씩 판매) · 카레 가루 480 g(100 g 한 봉지 1900원) · 고춧가루 220 g(100 g 한 봉지 2150원). 어림셈한 비용 196000원과 실제 비용 191950원은 얼마나 차이가 나나요?',ARRAY['M5-2-u1-X16','M5-2-u1-X17']::text[],false,'{"seq":10,"concept":"M5-2-u1-C8","difficulty":3,"kind":"mc","stem":"탄두리치킨 재료 — 닭고기 20마리(1마리 8800원, 1마리씩 판매) · 카레 가루 480 g(100 g 한 봉지 1900원) · 고춧가루 220 g(100 g 한 봉지 2150원). 어림셈한 비용 196000원과 실제 비용 191950원은 얼마나 차이가 나나요?","options":[{"t":"4050원","correct":true},{"t":"5050원","mis":"M5-2-u1-X16"},{"t":"3950원","mis":"M5-2-u1-X16"},{"t":"191950원","mis":"M5-2-u1-X17"}],"explanation":["어림셈 196000원, 실제 191950원이에요.","196000 − 191950 = 4050원이에요.","어림셈이 실제와 꽤 가까워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_L09_challenge#1','math',5,2,'u1','L09','g5_2_math_u1_L09_challenge','lesson_challenge','M5-2-u1-C8',2,'mc','auto','피자를 만드는 데 치즈 1350 g이 필요해요. 치즈를 500 g씩 한 봉지로 판다면 몇 봉지를 사야 하나요?',ARRAY['M5-2-u1-X13','M5-2-u1-X16','M5-2-u1-X14']::text[],true,'{"seq":1,"concept":"M5-2-u1-C8","difficulty":2,"kind":"mc","stem":"피자를 만드는 데 치즈 1350 g이 필요해요. 치즈를 500 g씩 한 봉지로 판다면 몇 봉지를 사야 하나요?","options":[{"t":"3봉지","correct":true},{"t":"2봉지","mis":"M5-2-u1-X13"},{"t":"4봉지","mis":"M5-2-u1-X16"},{"t":"27봉지","mis":"M5-2-u1-X14"}],"explanation":["2봉지는 1000 g이라 350 g이 모자라요.","모자라면 안 되니 한 봉지 더 — 올림이에요.","3봉지 1500 g을 사야 해요."],"variant_rule":{"alt":[{"stem":"피자를 만드는 데 밀가루 2300 g이 필요해요. 밀가루를 1000 g씩 한 봉지로 판다면 몇 봉지를 사야 하나요?","options":[{"t":"3봉지","correct":true},{"t":"2봉지","mis":"M5-2-u1-X13"},{"t":"4봉지","mis":"M5-2-u1-X16"},{"t":"23봉지","mis":"M5-2-u1-X14"}],"explanation":["2봉지는 2000 g이라 300 g이 모자라요.","2300을 올림하여 천의 자리까지 → 3000 g이에요.","3봉지를 사야 해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_L09_challenge#2','math',5,2,'u1','L09','g5_2_math_u1_L09_challenge','lesson_challenge','M5-2-u1-C8',2,'mc','auto','반미 재료 — 바게트 15개(1개 2380원, 1개씩 판매) · 고수 740 g(100 g 한 봉지 1450원) · 당근 1.2 kg(1 kg 한 봉지 3600원). 어림셈을 하려고 바게트 한 개 값 2380원을 반올림하여 천의 자리까지 나타내면 얼마인가요?',ARRAY['M5-2-u1-X08','M5-2-u1-X09','M5-2-u1-X16']::text[],true,'{"seq":2,"concept":"M5-2-u1-C8","difficulty":2,"kind":"mc","stem":"반미 재료 — 바게트 15개(1개 2380원, 1개씩 판매) · 고수 740 g(100 g 한 봉지 1450원) · 당근 1.2 kg(1 kg 한 봉지 3600원). 어림셈을 하려고 바게트 한 개 값 2380원을 반올림하여 천의 자리까지 나타내면 얼마인가요?","options":[{"t":"2000원","correct":true},{"t":"3000원","mis":"M5-2-u1-X08"},{"t":"2400원","mis":"M5-2-u1-X09"},{"t":"4000원","mis":"M5-2-u1-X16"}],"explanation":["반올림은 구하려는 자리 바로 아래 한 자리만 봐요.","천의 자리 바로 아래 숫자가 3이라 버려요.","2380 → 2000이에요."],"variant_rule":{"alt":[{"stem":"반미 재료 — 바게트 15개(1개 2380원, 1개씩 판매) · 고수 740 g(100 g 한 봉지 1450원) · 당근 1.2 kg(1 kg 한 봉지 3600원). 어림셈을 하려고 고수 한 봉지 값 1450원을 반올림하여 천의 자리까지 나타내면 얼마인가요?","options":[{"t":"1000원","correct":true},{"t":"2000원","mis":"M5-2-u1-X10"},{"t":"1500원","mis":"M5-2-u1-X09"},{"t":"3000원","mis":"M5-2-u1-X16"}],"explanation":["반올림은 구하려는 자리 바로 아래 한 자리만 봐요.","천의 자리 바로 아래 숫자가 4라 버려요.","1450 → 1000이에요."]},{"stem":"반미 재료 — 바게트 15개(1개 2380원, 1개씩 판매) · 고수 740 g(100 g 한 봉지 1450원) · 당근 1.2 kg(1 kg 한 봉지 3600원). 어림셈을 하려고 당근 한 봉지 값 3600원을 반올림하여 천의 자리까지 나타내면 얼마인가요?","options":[{"t":"4000원","correct":true},{"t":"3000원","mis":"M5-2-u1-X08"},{"t":"5000원","mis":"M5-2-u1-X16"},{"t":"6000원","mis":"M5-2-u1-X16"}],"explanation":["반올림은 구하려는 자리 바로 아래 한 자리만 봐요.","천의 자리 바로 아래 숫자가 6이라 올려요.","3600 → 4000이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_L09_challenge#3','math',5,2,'u1','L09','g5_2_math_u1_L09_challenge','lesson_challenge','M5-2-u1-C8',3,'mc','auto','반미 재료 — 바게트 15개(1개 2380원, 1개씩 판매) · 고수 740 g(100 g 한 봉지 1450원) · 당근 1.2 kg(1 kg 한 봉지 3600원). 구입할 양은 올림으로 정하고, 가격은 반올림하여 천의 자리까지 나타내 어림셈하면 반미 재료의 구입 비용은 약 얼마인가요?',ARRAY['M5-2-u1-X08','M5-2-u1-X17','M5-2-u1-X13']::text[],false,'{"seq":3,"concept":"M5-2-u1-C8","difficulty":3,"kind":"mc","stem":"반미 재료 — 바게트 15개(1개 2380원, 1개씩 판매) · 고수 740 g(100 g 한 봉지 1450원) · 당근 1.2 kg(1 kg 한 봉지 3600원). 구입할 양은 올림으로 정하고, 가격은 반올림하여 천의 자리까지 나타내 어림셈하면 반미 재료의 구입 비용은 약 얼마인가요?","options":[{"t":"46000원","correct":true},{"t":"54000원","mis":"M5-2-u1-X08"},{"t":"54500원","mis":"M5-2-u1-X17"},{"t":"42000원","mis":"M5-2-u1-X13"}],"explanation":["고수 740 g → 8봉지, 당근 1.2 kg → 2봉지예요.","어림 가격 — 바게트 2000원, 고수 1000원, 당근 4000원이에요.","2000 × 15 + 1000 × 8 + 4000 × 2 = 30000 + 8000 + 8000 = 46000원이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_L09_challenge#4','math',5,2,'u1','L09','g5_2_math_u1_L09_challenge','lesson_challenge','M5-2-u1-C8',3,'sa','auto','반미 재료 — 바게트 15개(1개 2380원, 1개씩 판매) · 고수 740 g(100 g 한 봉지 1450원) · 당근 1.2 kg(1 kg 한 봉지 3600원). 당근 1.2 kg을 사려면 몇 봉지를 사야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M5-2-u1-C8","difficulty":3,"kind":"sa","stem":"반미 재료 — 바게트 15개(1개 2380원, 1개씩 판매) · 고수 740 g(100 g 한 봉지 1450원) · 당근 1.2 kg(1 kg 한 봉지 3600원). 당근 1.2 kg을 사려면 몇 봉지를 사야 하나요? 숫자로 쓰세요.","answer":["2","2봉지"],"explanation":["1봉지는 1 kg이라 0.2 kg이 모자라요.","모자라면 안 되니 1.2를 올림하여 일의 자리까지 → 2예요.","2봉지를 사야 해요."],"variant_rule":{"alt":[{"stem":"반미 재료 — 바게트 15개(1개 2380원, 1개씩 판매) · 고수 740 g(100 g 한 봉지 1450원) · 당근 1.2 kg(1 kg 한 봉지 3600원). 고수 740 g을 사려면 몇 봉지를 사야 하나요? 숫자로 쓰세요.","answer":["8","8봉지"],"explanation":["7봉지는 700 g이라 40 g이 모자라요.","740을 올림하여 백의 자리까지 → 800 g이에요.","8봉지를 사야 해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_L09_challenge#5','math',5,2,'u1','L09','g5_2_math_u1_L09_challenge','lesson_challenge','M5-2-u1-C8',3,'error','auto','탄두리치킨 재료를 사러 간 친구들이 말했어요. 잘못한 친구는 누구인가요?',ARRAY['M5-2-u1-X13','M5-2-u1-X17']::text[],true,'{"seq":5,"concept":"M5-2-u1-C8","difficulty":3,"kind":"error","stem":"탄두리치킨 재료를 사러 간 친구들이 말했어요. 잘못한 친구는 누구인가요?","options":[{"t":"태린 — 「고춧가루 220 g은 반올림해서 2봉지 200 g만 샀어.」","correct":true,"mis_target":"M5-2-u1-X13"},{"t":"윤서 — 「카레 가루 480 g은 올림해서 5봉지 500 g을 샀어.」","mis":"M5-2-u1-X17"},{"t":"강민 — 「닭고기는 1마리씩 팔아서 20마리 그대로 샀어.」","mis":"M5-2-u1-X17"}],"explanation":["구입할 양은 모자라면 안 되니 올림해요.","220 g을 반올림하면 200 g이라 20 g이 모자라요.","태린이는 3봉지를 사야 했어요."],"variant_rule":{"alt":[{"stem":"반미 재료를 사러 간 친구들이 말했어요. 잘못한 친구는 누구인가요?","options":[{"t":"세진 — 「당근 1.2 kg은 버림해서 1봉지만 샀어.」","correct":true,"mis_target":"M5-2-u1-X13"},{"t":"도아 — 「고수 740 g은 올림해서 8봉지를 샀어.」","mis":"M5-2-u1-X17"},{"t":"유찬 — 「바게트는 1개씩 팔아서 15개 그대로 샀어.」","mis":"M5-2-u1-X17"}],"explanation":["구입할 양은 모자라면 안 되니 올림해요.","1.2 kg을 버림하면 1 kg이라 0.2 kg이 모자라요.","세진이는 2봉지를 사야 했어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_L09_challenge#6','math',5,2,'u1','L09','g5_2_math_u1_L09_challenge','lesson_challenge','M5-2-u1-C8',3,'mc','auto','탄두리치킨 재료 — 닭고기 20마리(1마리 8800원, 1마리씩 판매) · 카레 가루 480 g(100 g 한 봉지 1900원) · 고춧가루 220 g(100 g 한 봉지 2150원). 200000원을 내고 탄두리치킨 재료를 모두 샀다면 거스름돈은 얼마인가요?',ARRAY['M5-2-u1-X17','M5-2-u1-X16']::text[],false,'{"seq":6,"concept":"M5-2-u1-C8","difficulty":3,"kind":"mc","stem":"탄두리치킨 재료 — 닭고기 20마리(1마리 8800원, 1마리씩 판매) · 카레 가루 480 g(100 g 한 봉지 1900원) · 고춧가루 220 g(100 g 한 봉지 2150원). 200000원을 내고 탄두리치킨 재료를 모두 샀다면 거스름돈은 얼마인가요?","options":[{"t":"8050원","correct":true},{"t":"4000원","mis":"M5-2-u1-X17"},{"t":"18050원","mis":"M5-2-u1-X16"},{"t":"8950원","mis":"M5-2-u1-X16"}],"explanation":["실제 비용은 191950원이에요.","200000 − 191950 = 8050원이에요.","어림셈 값 196000원으로 빼면 4000원이 되어 실제와 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_L09_challenge#7','math',5,2,'u1','L09','g5_2_math_u1_L09_challenge','lesson_challenge','M5-2-u1-C8',3,'mc','auto','재료 비용을 어림셈할 때 가격을 반올림하지 않고 모두 올림하여 천의 자리까지 나타낸다면, 어림셈한 비용은 실제 비용과 견주어 어떻게 될까요?',ARRAY['M5-2-u1-X08','M5-2-u1-X17']::text[],false,'{"seq":7,"concept":"M5-2-u1-C8","difficulty":3,"kind":"mc","stem":"재료 비용을 어림셈할 때 가격을 반올림하지 않고 모두 올림하여 천의 자리까지 나타낸다면, 어림셈한 비용은 실제 비용과 견주어 어떻게 될까요?","options":[{"t":"실제 비용과 같거나 크다","correct":true},{"t":"실제 비용보다 작다","mis":"M5-2-u1-X08"},{"t":"언제나 실제 비용과 같다","mis":"M5-2-u1-X08"},{"t":"알 수 없다","mis":"M5-2-u1-X17"}],"explanation":["올림은 가격을 같거나 크게 바꿔요.","모든 가격이 같거나 커지니 합도 같거나 커져요.","그래서 실제 비용과 같거나 커요 — 예산을 넉넉히 잡을 때 쓸 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_L09_challenge#8','math',5,2,'u1','L09','g5_2_math_u1_L09_challenge','lesson_challenge','M5-2-u1-C8',4,'essay','teacher','탄두리치킨 재료를 살 때 「구입해야 하는 양」은 올림으로, 「구입 비용」은 반올림으로 어림했어요. 한 문제 안에서 어림 방법이 갈린 까닭을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"M5-2-u1-C8","difficulty":4,"kind":"essay","stem":"탄두리치킨 재료를 살 때 「구입해야 하는 양」은 올림으로, 「구입 비용」은 반올림으로 어림했어요. 한 문제 안에서 어림 방법이 갈린 까닭을 쓰세요.","answer_guide":{"answer":"예: 구입해야 하는 양은 모자라면 요리를 할 수 없으니 필요한 양보다 크게 어림하는 올림을 쓴다. 구입 비용은 대략 얼마인지만 알면 되니 실제와 가까운 반올림으로 어림셈한다. 무엇을 구하는지에 따라 방법이 갈린다.","scoring_points":["양은 모자라면 안 돼 올림이라고 썼는가","비용은 대략 알면 되어 반올림이라고 썼는가","구하는 것에 따라 방법이 갈린다고 정리했는가"]},"explanation":["양 — 모자라면 안 돼 올림이에요.","비용 — 대략이면 되니 반올림이에요.","구하는 것이 방법을 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_L09_challenge#9','math',5,2,'u1','L09','g5_2_math_u1_L09_challenge','lesson_challenge','M5-2-u1-C8',4,'essay','teacher','탄두리치킨 재료 — 닭고기 20마리(1마리 8800원, 1마리씩 판매) · 카레 가루 480 g(100 g 한 봉지 1900원) · 고춧가루 220 g(100 g 한 봉지 2150원). 어림셈한 비용(약 196000원)과 실제 비용(191950원)을 견주고, 재료를 사러 가기 전에 어림셈을 해 보면 좋은 점을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"M5-2-u1-C8","difficulty":4,"kind":"essay","stem":"탄두리치킨 재료 — 닭고기 20마리(1마리 8800원, 1마리씩 판매) · 카레 가루 480 g(100 g 한 봉지 1900원) · 고춧가루 220 g(100 g 한 봉지 2150원). 어림셈한 비용(약 196000원)과 실제 비용(191950원)을 견주고, 재료를 사러 가기 전에 어림셈을 해 보면 좋은 점을 쓰세요.","answer_guide":{"answer":"예: 어림셈 196000원은 실제 191950원보다 4050원 많아 꽤 가깝다. 사러 가기 전에 어림셈을 하면 계산이 쉬워 돈을 얼마쯤 준비해야 할지 빨리 알 수 있다.","scoring_points":["두 값의 차(4050원)나 크기를 견주었는가","어림셈이 실제와 가깝다고 썼는가","준비할 돈을 미리 쉽게 알 수 있다는 좋은 점을 썼는가"]},"explanation":["196000 − 191950 = 4050원 차이예요.","어림셈이 실제와 꽤 가까워요.","미리 쉽게 준비할 돈을 가늠할 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_L09_challenge#10','math',5,2,'u1','L09','g5_2_math_u1_L09_challenge','lesson_challenge','M5-2-u1-C8',4,'mc','auto','반미 재료 — 바게트 15개(1개 2380원, 1개씩 판매) · 고수 740 g(100 g 한 봉지 1450원) · 당근 1.2 kg(1 kg 한 봉지 3600원). 반미 재료를 반올림으로 어림셈한 값은 46000원이에요. 이 값만 믿고 50000원만 준비해 간다면 어떻게 될까요?',ARRAY['M5-2-u1-X17','M5-2-u1-X16']::text[],false,'{"seq":10,"concept":"M5-2-u1-C8","difficulty":4,"kind":"mc","stem":"반미 재료 — 바게트 15개(1개 2380원, 1개씩 판매) · 고수 740 g(100 g 한 봉지 1450원) · 당근 1.2 kg(1 kg 한 봉지 3600원). 반미 재료를 반올림으로 어림셈한 값은 46000원이에요. 이 값만 믿고 50000원만 준비해 간다면 어떻게 될까요?","options":[{"t":"실제 비용이 54500원이라 4500원이 모자란다","correct":true},{"t":"4000원이 남는다","mis":"M5-2-u1-X17"},{"t":"딱 맞는다","mis":"M5-2-u1-X16"},{"t":"500원이 모자란다","mis":"M5-2-u1-X16"}],"explanation":["실제 비용은 2380 × 15 + 1450 × 8 + 3600 × 2 = 35700 + 11600 + 7200 = 54500원이에요.","50000원으로는 54500 − 50000 = 4500원이 모자라요.","반올림으로 많이 내려간 가격(2380원 → 2000원)이 있으면 어림셈이 실제보다 작을 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_review_a#1','math',5,2,'u1','','g5_2_math_u1_review_a','unit_review','M5-2-u1-C1',1,'sa','auto','45, 35, 30, 25, 50 중에서 35 이상인 수는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"M5-2-u1-C1","difficulty":1,"kind":"sa","stem":"45, 35, 30, 25, 50 중에서 35 이상인 수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["3","3개"],"explanation":["35 이상인 수의 뜻에 맞는지 하나씩 확인해요.","들어가는 수는 45, 35, 50이에요.","모두 3개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_review_a#2','math',5,2,'u1','','g5_2_math_u1_review_a','unit_review','M5-2-u1-C1',2,'mc','auto','「키 140 cm (  ) 어린이는 이 놀이 기구를 탈 수 있어요.」 키가 딱 140 cm인 어린이도 탈 수 있다면 (  )에 알맞은 말은 어느 것인가요?',ARRAY['M5-2-u1-X02','M5-2-u1-X03']::text[],false,'{"seq":2,"concept":"M5-2-u1-C1","difficulty":2,"kind":"mc","stem":"「키 140 cm (  ) 어린이는 이 놀이 기구를 탈 수 있어요.」 키가 딱 140 cm인 어린이도 탈 수 있다면 (  )에 알맞은 말은 어느 것인가요?","options":[{"t":"이상","correct":true},{"t":"초과","mis":"M5-2-u1-X02"},{"t":"이하","mis":"M5-2-u1-X03"},{"t":"미만","mis":"M5-2-u1-X03"}],"explanation":["키가 큰 쪽이 타니 「이상」이나 「초과」예요.","딱 140 cm도 들어가야 해요.","경곗값을 넣는 말은 「이상」이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_review_a#3','math',5,2,'u1','','g5_2_math_u1_review_a','unit_review','M5-2-u1-C2',1,'mc','auto','가방 10.5 kg, 13 kg, 10 kg, 12 kg 중에서 10 kg 초과가 아닌 것은 어느 것인가요?',ARRAY['M5-2-u1-X17']::text[],false,'{"seq":3,"concept":"M5-2-u1-C2","difficulty":1,"kind":"mc","stem":"가방 10.5 kg, 13 kg, 10 kg, 12 kg 중에서 10 kg 초과가 아닌 것은 어느 것인가요?","options":[{"t":"10 kg","correct":true},{"t":"10.5 kg","mis":"M5-2-u1-X17"},{"t":"13 kg","mis":"M5-2-u1-X17"},{"t":"12 kg","mis":"M5-2-u1-X17"}],"explanation":["10 kg 초과는 경곗값을 포함하지 않아요.","10 kg만 범위에서 벗어나요.","그래서 아닌 것은 10 kg이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_review_a#4','math',5,2,'u1','','g5_2_math_u1_review_a','unit_review','M5-2-u1-C2',2,'ox','auto','25 미만인 수에는 25가 들어가요.',ARRAY['M5-2-u1-X02']::text[],false,'{"seq":4,"concept":"M5-2-u1-C2","difficulty":2,"kind":"ox","stem":"25 미만인 수에는 25가 들어가요.","answer":"X","reason_options":[{"t":"미만은 그 수보다 작은 수라 25가 빠져서","correct":true},{"t":"미만은 「같거나 작다」는 뜻이라서","mis":"M5-2-u1-X02"}],"mis":"M5-2-u1-X02","explanation":["25 미만은 25보다 작은 수예요.","경곗값 25는 들어가지 않아요.","수직선에도 25에 빈 ○으로 그려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_review_a#5','math',5,2,'u1','','g5_2_math_u1_review_a','unit_review','M5-2-u1-C2',1,'mc','auto','수직선에 34에 ○이 그려져 있고 거기서 오른쪽으로 선이 그어져 있어요. 수직선이 나타내는 수의 범위는 어느 것인가요?',ARRAY['M5-2-u1-X04','M5-2-u1-X03']::text[],false,'{"seq":5,"concept":"M5-2-u1-C2","difficulty":1,"kind":"mc","stem":"수직선에 34에 ○이 그려져 있고 거기서 오른쪽으로 선이 그어져 있어요. 수직선이 나타내는 수의 범위는 어느 것인가요?","options":[{"t":"34 초과인 수","correct":true},{"t":"34 이상인 수","mis":"M5-2-u1-X04"},{"t":"34 미만인 수","mis":"M5-2-u1-X03"},{"t":"34 이하인 수","mis":"M5-2-u1-X03"}],"explanation":["●은 그 수를 포함하고 ○은 포함하지 않아요.","34는 ○이라 포함하지 않아요.","그래서 34 초과인 수예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_review_a#6','math',5,2,'u1','','g5_2_math_u1_review_a','unit_review','M5-2-u1-C3',1,'mc','auto','수직선에 52에는 ●, 58에는 ●이 그려져 있고 두 점 사이가 선으로 이어져 있어요. 수직선이 나타내는 수의 범위는 어느 것인가요?',ARRAY['M5-2-u1-X04']::text[],false,'{"seq":6,"concept":"M5-2-u1-C3","difficulty":1,"kind":"mc","stem":"수직선에 52에는 ●, 58에는 ●이 그려져 있고 두 점 사이가 선으로 이어져 있어요. 수직선이 나타내는 수의 범위는 어느 것인가요?","options":[{"t":"52 이상 58 이하인 수","correct":true},{"t":"52 초과 58 이하인 수","mis":"M5-2-u1-X04"},{"t":"52 이상 58 미만인 수","mis":"M5-2-u1-X04"},{"t":"52 초과 58 미만인 수","mis":"M5-2-u1-X04"}],"explanation":["●은 그 수를 포함하고 ○은 포함하지 않아요.","52는 ●이라 포함해요 · 58은 ●이라 포함해요.","그래서 52 이상 58 이하인 수예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_review_a#7','math',5,2,'u1','','g5_2_math_u1_review_a','unit_review','M5-2-u1-C3',2,'sa','auto','24, 14.6, 24.5, 17, 12, 20.7, 22, 10.1 중에서 12 초과 24 미만인 수는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":7,"concept":"M5-2-u1-C3","difficulty":2,"kind":"sa","stem":"24, 14.6, 24.5, 17, 12, 20.7, 22, 10.1 중에서 12 초과 24 미만인 수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["4","4개"],"explanation":["12 초과 24 미만인 수의 뜻에 맞는지 하나씩 확인해요.","들어가는 수는 14.6, 17, 20.7, 22예요.","모두 4개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_review_a#8','math',5,2,'u1','','g5_2_math_u1_review_a','unit_review','M5-2-u1-C3',3,'mc','auto','우체국 소포 요금표 — 5 kg 이하 4000원 · 5 kg 초과 10 kg 이하 5000원 · 10 kg 초과 20 kg 이하 7000원 · 20 kg 초과 25 kg 이하 9000원. 무게가 10 kg인 소포의 요금은 얼마인가요?',ARRAY['M5-2-u1-X01','M5-2-u1-X16']::text[],false,'{"seq":8,"concept":"M5-2-u1-C3","difficulty":3,"kind":"mc","stem":"우체국 소포 요금표 — 5 kg 이하 4000원 · 5 kg 초과 10 kg 이하 5000원 · 10 kg 초과 20 kg 이하 7000원 · 20 kg 초과 25 kg 이하 9000원. 무게가 10 kg인 소포의 요금은 얼마인가요?","options":[{"t":"5000원","correct":true},{"t":"7000원","mis":"M5-2-u1-X01"},{"t":"4000원","mis":"M5-2-u1-X16"},{"t":"9000원","mis":"M5-2-u1-X16"}],"explanation":["10 kg은 「5 kg 초과 10 kg 이하」에 들어가요.","「10 kg 초과」에는 10 kg이 빠져요.","그래서 5000원이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_review_a#9','math',5,2,'u1','','g5_2_math_u1_review_a','unit_review','M5-2-u1-C4',1,'mc','auto','543을 올림하여 십의 자리까지 나타내면 얼마인가요?',ARRAY['M5-2-u1-X08','M5-2-u1-X09','M5-2-u1-X12']::text[],false,'{"seq":9,"concept":"M5-2-u1-C4","difficulty":1,"kind":"mc","stem":"543을 올림하여 십의 자리까지 나타내면 얼마인가요?","options":[{"t":"550","correct":true},{"t":"540","mis":"M5-2-u1-X08"},{"t":"600","mis":"M5-2-u1-X09"},{"t":"55","mis":"M5-2-u1-X12"}],"explanation":["올림은 십의 자리 아래 수(3)을 올려서 나타내요.","아래 숫자가 무엇이든 0이 아니면 한 칸 올리고, 아래는 0으로 채워요.","543 → 550이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_review_a#10','math',5,2,'u1','','g5_2_math_u1_review_a','unit_review','M5-2-u1-C4',2,'mc','auto','3.457을 올림하여 소수 첫째 자리까지 나타내면 얼마인가요?',ARRAY['M5-2-u1-X08','M5-2-u1-X09']::text[],false,'{"seq":10,"concept":"M5-2-u1-C4","difficulty":2,"kind":"mc","stem":"3.457을 올림하여 소수 첫째 자리까지 나타내면 얼마인가요?","options":[{"t":"3.5","correct":true},{"t":"3.4","mis":"M5-2-u1-X08"},{"t":"3.46","mis":"M5-2-u1-X09"},{"t":"4","mis":"M5-2-u1-X09"}],"explanation":["올림은 소수 첫째 자리 아래 수(0.057)을 올려서 나타내요.","아래 숫자가 무엇이든 0이 아니면 한 칸 올리고, 아래는 0으로 채워요.","3.457 → 3.5예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_review_a#11','math',5,2,'u1','','g5_2_math_u1_review_a','unit_review','M5-2-u1-C5',1,'mc','auto','657을 버림하여 십의 자리까지 나타내면 얼마인가요?',ARRAY['M5-2-u1-X08','M5-2-u1-X09','M5-2-u1-X12']::text[],false,'{"seq":11,"concept":"M5-2-u1-C5","difficulty":1,"kind":"mc","stem":"657을 버림하여 십의 자리까지 나타내면 얼마인가요?","options":[{"t":"650","correct":true},{"t":"660","mis":"M5-2-u1-X08"},{"t":"600","mis":"M5-2-u1-X09"},{"t":"65","mis":"M5-2-u1-X12"}],"explanation":["버림은 십의 자리 아래 수(7)을 어떤 수든 버려요.","버린 자리는 0으로 채우거나(자연수) 지워요(소수).","657 → 650이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_review_a#12','math',5,2,'u1','','g5_2_math_u1_review_a','unit_review','M5-2-u1-C5',2,'sa','auto','과수원에서 딴 단감 4953개를 한 상자에 100개씩 포장해요. 포장한 상자는 최대 몇 상자인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":12,"concept":"M5-2-u1-C5","difficulty":2,"kind":"sa","stem":"과수원에서 딴 단감 4953개를 한 상자에 100개씩 포장해요. 포장한 상자는 최대 몇 상자인가요? 숫자로 쓰세요.","answer":["49","49상자"],"explanation":["묶음이 다 차야 하나로 셀 수 있어요.","4953을 버림하여 백의 자리까지 → 4900개예요.","4900개는 49상자예요. 남는 것은 버려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_review_a#13','math',5,2,'u1','','g5_2_math_u1_review_a','unit_review','M5-2-u1-C6',1,'mc','auto','5813을 반올림하여 백의 자리까지 나타내면 얼마인가요?',ARRAY['M5-2-u1-X08','M5-2-u1-X09']::text[],false,'{"seq":13,"concept":"M5-2-u1-C6","difficulty":1,"kind":"mc","stem":"5813을 반올림하여 백의 자리까지 나타내면 얼마인가요?","options":[{"t":"5800","correct":true},{"t":"5900","mis":"M5-2-u1-X08"},{"t":"5810","mis":"M5-2-u1-X09"},{"t":"6000","mis":"M5-2-u1-X09"}],"explanation":["반올림은 구하려는 자리 바로 아래 한 자리만 봐요.","백의 자리 바로 아래 숫자가 1이라 버려요.","5813 → 5800이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_review_a#14','math',5,2,'u1','','g5_2_math_u1_review_a','unit_review','M5-2-u1-C6',2,'mc','auto','3.406을 반올림하여 소수 둘째 자리까지 나타내면 얼마인가요?',ARRAY['M5-2-u1-X08','M5-2-u1-X09','M5-2-u1-X16']::text[],false,'{"seq":14,"concept":"M5-2-u1-C6","difficulty":2,"kind":"mc","stem":"3.406을 반올림하여 소수 둘째 자리까지 나타내면 얼마인가요?","options":[{"t":"3.41","correct":true},{"t":"3.40","mis":"M5-2-u1-X08"},{"t":"3.46","mis":"M5-2-u1-X09"},{"t":"3.42","mis":"M5-2-u1-X16"}],"explanation":["반올림은 구하려는 자리 바로 아래 한 자리만 봐요.","소수 둘째 자리 바로 아래 숫자가 0이라 버려요.","3.406 → 3.41이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_review_a#15','math',5,2,'u1','','g5_2_math_u1_review_a','unit_review','M5-2-u1-C6',3,'mc','auto','반올림하여 십의 자리까지 나타낸 수가 1270이에요. 126□의 □에 들어갈 수 있는 수를 모두 고른 것은 어느 것인가요?',ARRAY['M5-2-u1-X08','M5-2-u1-X11','M5-2-u1-X16']::text[],false,'{"seq":15,"concept":"M5-2-u1-C6","difficulty":3,"kind":"mc","stem":"반올림하여 십의 자리까지 나타낸 수가 1270이에요. 126□의 □에 들어갈 수 있는 수를 모두 고른 것은 어느 것인가요?","options":[{"t":"5, 6, 7, 8, 9","correct":true},{"t":"0, 1, 2, 3, 4","mis":"M5-2-u1-X08"},{"t":"6, 7, 8, 9","mis":"M5-2-u1-X11"},{"t":"0, 5","mis":"M5-2-u1-X16"}],"explanation":["일의 자리 □를 봐요.","1270이 되려면 올려야 하니 □는 5~9예요.","0~4면 1260이 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_review_a#16','math',5,2,'u1','','g5_2_math_u1_review_a','unit_review','M5-2-u1-C4',3,'mc','auto','올림하여 백의 자리까지 나타내면 3700이 되는 자연수의 범위로 알맞은 것은 어느 것인가요?',ARRAY['M5-2-u1-X07','M5-2-u1-X08','M5-2-u1-X15']::text[],false,'{"seq":16,"concept":"M5-2-u1-C4","difficulty":3,"kind":"mc","stem":"올림하여 백의 자리까지 나타내면 3700이 되는 자연수의 범위로 알맞은 것은 어느 것인가요?","options":[{"t":"3600 초과 3700 이하","correct":true},{"t":"3600 이상 3700 이하","mis":"M5-2-u1-X07"},{"t":"3650 이상 3750 미만","mis":"M5-2-u1-X08"},{"t":"3700 이상 3800 미만","mis":"M5-2-u1-X15"}],"explanation":["3600은 올림해도 3600 — 빠져요.","3601부터 3700까지가 3700이 돼요.","그래서 3600 초과 3700 이하예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_review_a#17','math',5,2,'u1','','g5_2_math_u1_review_a','unit_review','M5-2-u1-C7',1,'mc','auto','학생 모두에게 공책을 나누어 주려고 10권 묶음으로 살 공책 수를 정할 때 알맞은 어림 방법은 어느 것인가요?',ARRAY['M5-2-u1-X13']::text[],false,'{"seq":17,"concept":"M5-2-u1-C7","difficulty":1,"kind":"mc","stem":"학생 모두에게 공책을 나누어 주려고 10권 묶음으로 살 공책 수를 정할 때 알맞은 어림 방법은 어느 것인가요?","options":[{"t":"올림","correct":true},{"t":"버림","mis":"M5-2-u1-X13"},{"t":"반올림","mis":"M5-2-u1-X13"},{"t":"아무 방법이나 좋다","mis":"M5-2-u1-X13"}],"explanation":["모자라면 받지 못하는 학생이 생겨요.","모자라지 않게 크게 어림해요.","그래서 올림이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_review_a#18','math',5,2,'u1','','g5_2_math_u1_review_a','unit_review','M5-2-u1-C7',2,'mc','auto','필통 11200원을 10000원짜리 지폐로만 낸다면 최소 얼마를 내야 하나요?',ARRAY['M5-2-u1-X13','M5-2-u1-X09','M5-2-u1-X08']::text[],false,'{"seq":18,"concept":"M5-2-u1-C7","difficulty":2,"kind":"mc","stem":"필통 11200원을 10000원짜리 지폐로만 낸다면 최소 얼마를 내야 하나요?","options":[{"t":"20000원","correct":true},{"t":"10000원","mis":"M5-2-u1-X13"},{"t":"12000원","mis":"M5-2-u1-X09"},{"t":"11000원","mis":"M5-2-u1-X08"}],"explanation":["10000원 1장으로는 모자라요.","11200을 올림하여 만의 자리까지 나타내요.","20000원이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_review_a#19','math',5,2,'u1','','g5_2_math_u1_review_a','unit_review','M5-2-u1-C7',3,'mc','auto','어림한 방법이 다른 친구는 누구인가요? 지민 — 「젤리 423개를 10개씩 담아 420개까지 팔 수 있어요.」 유나 — 「1000원짜리 48장을 10000원짜리로 40000원까지 바꿀 수 있어요.」 시은 — 「엘리베이터에 10명까지 타서 53명이 이동하려면 6번 운행해야 해요.」',ARRAY['M5-2-u1-X13']::text[],false,'{"seq":19,"concept":"M5-2-u1-C7","difficulty":3,"kind":"mc","stem":"어림한 방법이 다른 친구는 누구인가요? 지민 — 「젤리 423개를 10개씩 담아 420개까지 팔 수 있어요.」 유나 — 「1000원짜리 48장을 10000원짜리로 40000원까지 바꿀 수 있어요.」 시은 — 「엘리베이터에 10명까지 타서 53명이 이동하려면 6번 운행해야 해요.」","options":[{"t":"시은","correct":true},{"t":"지민","mis":"M5-2-u1-X13"},{"t":"유나","mis":"M5-2-u1-X13"},{"t":"모두 같다","mis":"M5-2-u1-X13"}],"explanation":["지민·유나는 남는 것을 버렸어요 — 버림이에요.","시은은 남은 3명도 태워야 해 올림이에요.","그래서 다른 친구는 시은이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_review_a#20','math',5,2,'u1','','g5_2_math_u1_review_a','unit_review','M5-2-u1-C8',2,'sa','auto','카레 가루 480 g이 필요한데 100 g씩 한 봉지로 팔아요. 몇 봉지를 사야 하나요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":20,"concept":"M5-2-u1-C8","difficulty":2,"kind":"sa","stem":"카레 가루 480 g이 필요한데 100 g씩 한 봉지로 팔아요. 몇 봉지를 사야 하나요? 숫자로 쓰세요.","answer":["5","5봉지"],"explanation":["4봉지는 400 g이라 80 g이 모자라요.","모자라면 요리를 못 하니 올림이에요.","480 g → 500 g, 5봉지예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_review_a#21','math',5,2,'u1','','g5_2_math_u1_review_a','unit_review','M5-2-u1-C8',3,'mc','auto','탄두리치킨 재료 — 닭고기 20마리(1마리 8800원, 1마리씩 판매) · 카레 가루 480 g(100 g 한 봉지 1900원) · 고춧가루 220 g(100 g 한 봉지 2150원). 가격을 반올림하여 천의 자리까지 나타내 어림셈하면 구입 비용은 약 얼마인가요?',ARRAY['M5-2-u1-X08','M5-2-u1-X17','M5-2-u1-X16']::text[],false,'{"seq":21,"concept":"M5-2-u1-C8","difficulty":3,"kind":"mc","stem":"탄두리치킨 재료 — 닭고기 20마리(1마리 8800원, 1마리씩 판매) · 카레 가루 480 g(100 g 한 봉지 1900원) · 고춧가루 220 g(100 g 한 봉지 2150원). 가격을 반올림하여 천의 자리까지 나타내 어림셈하면 구입 비용은 약 얼마인가요?","options":[{"t":"196000원","correct":true},{"t":"199000원","mis":"M5-2-u1-X08"},{"t":"191950원","mis":"M5-2-u1-X17"},{"t":"186000원","mis":"M5-2-u1-X16"}],"explanation":["닭고기 9000 × 20 = 180000원이에요.","카레 가루 2000 × 5 = 10000원, 고춧가루 2000 × 3 = 6000원이에요.","모두 약 196000원이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_review_a#22','math',5,2,'u1','','g5_2_math_u1_review_a','unit_review','M5-2-u1-C5',3,'mc','auto','수 카드 3, 6, 1, 7을 한 번씩만 써서 가장 큰 네 자리 수를 만들었어요. 그 수를 버림하여 십의 자리까지 나타내면 얼마인가요?',ARRAY['M5-2-u1-X08','M5-2-u1-X09','M5-2-u1-X12']::text[],false,'{"seq":22,"concept":"M5-2-u1-C5","difficulty":3,"kind":"mc","stem":"수 카드 3, 6, 1, 7을 한 번씩만 써서 가장 큰 네 자리 수를 만들었어요. 그 수를 버림하여 십의 자리까지 나타내면 얼마인가요?","options":[{"t":"7630","correct":true},{"t":"7640","mis":"M5-2-u1-X08"},{"t":"7600","mis":"M5-2-u1-X09"},{"t":"763","mis":"M5-2-u1-X12"}],"explanation":["수 카드로 만든 수는 7631이에요.","버림은 십의 자리 아래 수(1)을 어떤 수든 버려요.","7631 → 7630이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_review_a#23','math',5,2,'u1','','g5_2_math_u1_review_a','unit_review','M5-2-u1-C3',4,'essay','teacher','어린이 체감 온도 단계표 — 관심 29 °C 이상 31 °C 미만 · 주의 31 °C 이상 34 °C 미만 · 경고 34 °C 이상 37 °C 미만 · 위험 37 °C 이상. 단계마다 한쪽 끝만 넣은 까닭을 쓰고, 34 °C가 어느 단계인지 설명하세요.','{}'::text[],false,'{"seq":23,"concept":"M5-2-u1-C3","difficulty":4,"kind":"essay","stem":"어린이 체감 온도 단계표 — 관심 29 °C 이상 31 °C 미만 · 주의 31 °C 이상 34 °C 미만 · 경고 34 °C 이상 37 °C 미만 · 위험 37 °C 이상. 단계마다 한쪽 끝만 넣은 까닭을 쓰고, 34 °C가 어느 단계인지 설명하세요.","answer_guide":{"answer":"예: 한쪽 끝만 넣어야 단계가 겹치지 않아 어떤 온도든 한 단계에만 들어간다. 34 °C는 주의(34 °C 미만)에서 빠지고 경고(34 °C 이상)에 들어간다.","scoring_points":["겹치지 않게 나누려는 까닭을 썼는가","34 °C가 주의에서 빠짐을 썼는가","34 °C를 경고로 판단했는가"]},"explanation":["경계를 한쪽에만 넣으면 겹치지 않아요.","34 °C는 주의 단계(미만)에서 빠져요.","경고 단계(이상)에 들어가요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_review_a#24','math',5,2,'u1','','g5_2_math_u1_review_a','unit_review','M5-2-u1-C7',4,'essay','teacher','필통값 11200원을 지폐로 낼 때는 올림을, 동전 58600원을 지폐로 바꿀 때는 버림을 써요. 둘 다 돈인데 방법이 갈린 까닭을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"M5-2-u1-C7","difficulty":4,"kind":"essay","stem":"필통값 11200원을 지폐로 낼 때는 올림을, 동전 58600원을 지폐로 바꿀 때는 버림을 써요. 둘 다 돈인데 방법이 갈린 까닭을 쓰세요.","answer_guide":{"answer":"예: 필통값은 모자라게 내면 살 수 없으니 올림, 동전은 지폐 한 장을 채우지 못한 나머지를 바꿀 수 없으니 버림이다. 수가 아니라 상황이 방법을 정한다.","scoring_points":["필통은 올림인 까닭을 썼는가","동전은 버림인 까닭을 썼는가","상황이 방법을 정한다고 썼는가"]},"explanation":["필통 — 모자라면 안 돼 올림이에요.","동전 — 남는 것을 못 바꿔 버림이에요.","상황이 방법을 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_review_a#25','math',5,2,'u1','','g5_2_math_u1_review_a','unit_review','M5-2-u1-C8',4,'essay','teacher','탄두리치킨 재료를 살 때 구입해야 하는 양은 올림으로, 구입 비용은 반올림으로 어림했어요. 한 문제 안에서 방법이 갈린 까닭을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"M5-2-u1-C8","difficulty":4,"kind":"essay","stem":"탄두리치킨 재료를 살 때 구입해야 하는 양은 올림으로, 구입 비용은 반올림으로 어림했어요. 한 문제 안에서 방법이 갈린 까닭을 쓰세요.","answer_guide":{"answer":"예: 양은 모자라면 요리를 할 수 없어 올림, 비용은 대략 얼마인지만 알면 되어 실제와 가까운 반올림으로 어림셈한다. 구하는 것에 따라 방법이 갈린다.","scoring_points":["양은 올림인 까닭을 썼는가","비용은 반올림인 까닭을 썼는가","구하는 것에 따라 갈린다고 썼는가"]},"explanation":["양 — 모자라면 안 돼 올림이에요.","비용 — 대략이면 되니 반올림이에요.","구하는 것이 방법을 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_review_b#1','math',5,2,'u1','','g5_2_math_u1_review_b','unit_review','M5-2-u1-C1',1,'sa','auto','20, 21, 19.5, 18, 25 중에서 20 이하인 수는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"M5-2-u1-C1","difficulty":1,"kind":"sa","stem":"20, 21, 19.5, 18, 25 중에서 20 이하인 수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["3","3개"],"explanation":["20 이하인 수의 뜻에 맞는지 하나씩 확인해요.","들어가는 수는 20, 19.5, 18이에요.","모두 3개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_review_b#2','math',5,2,'u1','','g5_2_math_u1_review_b','unit_review','M5-2-u1-C1',2,'mc','auto','「6세 (  ) 어린이는 버스 요금이 무료예요.」 딱 6세인 어린이도 무료라면 (  )에 알맞은 말은 어느 것인가요?',ARRAY['M5-2-u1-X02','M5-2-u1-X03']::text[],false,'{"seq":2,"concept":"M5-2-u1-C1","difficulty":2,"kind":"mc","stem":"「6세 (  ) 어린이는 버스 요금이 무료예요.」 딱 6세인 어린이도 무료라면 (  )에 알맞은 말은 어느 것인가요?","options":[{"t":"이하","correct":true},{"t":"미만","mis":"M5-2-u1-X02"},{"t":"이상","mis":"M5-2-u1-X03"},{"t":"초과","mis":"M5-2-u1-X03"}],"explanation":["어린 쪽이 무료이니 「이하」나 「미만」이에요.","딱 6세도 들어가야 해요.","경곗값을 넣는 말은 「이하」예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_review_b#3','math',5,2,'u1','','g5_2_math_u1_review_b','unit_review','M5-2-u1-C2',1,'mc','auto','반려동물 6.4 kg, 7.9 kg, 8 kg, 5.5 kg 중에서 8 kg 미만이 아닌 것은 어느 것인가요?',ARRAY['M5-2-u1-X17']::text[],false,'{"seq":3,"concept":"M5-2-u1-C2","difficulty":1,"kind":"mc","stem":"반려동물 6.4 kg, 7.9 kg, 8 kg, 5.5 kg 중에서 8 kg 미만이 아닌 것은 어느 것인가요?","options":[{"t":"8 kg","correct":true},{"t":"6.4 kg","mis":"M5-2-u1-X17"},{"t":"7.9 kg","mis":"M5-2-u1-X17"},{"t":"5.5 kg","mis":"M5-2-u1-X17"}],"explanation":["8 kg 미만은 경곗값을 포함하지 않아요.","8 kg만 범위에서 벗어나요.","그래서 아닌 것은 8 kg이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_review_b#4','math',5,2,'u1','','g5_2_math_u1_review_b','unit_review','M5-2-u1-C2',2,'ox','auto','9 초과인 수 중에서 가장 작은 자연수는 10이에요.',ARRAY['M5-2-u1-X02']::text[],false,'{"seq":4,"concept":"M5-2-u1-C2","difficulty":2,"kind":"ox","stem":"9 초과인 수 중에서 가장 작은 자연수는 10이에요.","answer":"O","reason_options":[{"t":"초과는 9보다 큰 수라 9가 빠지고 10부터라서","correct":true},{"t":"초과에는 9도 들어가서","mis":"M5-2-u1-X02"}],"mis":"M5-2-u1-X02","explanation":["9 초과는 9보다 큰 수예요.","9는 빠지니 자연수는 10부터예요.","그래서 가장 작은 자연수는 10이 맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_review_b#5','math',5,2,'u1','','g5_2_math_u1_review_b','unit_review','M5-2-u1-C2',1,'mc','auto','수직선에 8에 ○이 그려져 있고 거기서 왼쪽으로 선이 그어져 있어요. 수직선이 나타내는 수의 범위는 어느 것인가요?',ARRAY['M5-2-u1-X04','M5-2-u1-X03']::text[],false,'{"seq":5,"concept":"M5-2-u1-C2","difficulty":1,"kind":"mc","stem":"수직선에 8에 ○이 그려져 있고 거기서 왼쪽으로 선이 그어져 있어요. 수직선이 나타내는 수의 범위는 어느 것인가요?","options":[{"t":"8 미만인 수","correct":true},{"t":"8 이하인 수","mis":"M5-2-u1-X04"},{"t":"8 초과인 수","mis":"M5-2-u1-X03"},{"t":"8 이상인 수","mis":"M5-2-u1-X03"}],"explanation":["●은 그 수를 포함하고 ○은 포함하지 않아요.","8은 ○이라 포함하지 않아요.","그래서 8 미만인 수예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_review_b#6','math',5,2,'u1','','g5_2_math_u1_review_b','unit_review','M5-2-u1-C3',1,'mc','auto','수직선에 52에는 ○, 58에는 ●이 그려져 있고 두 점 사이가 선으로 이어져 있어요. 수직선이 나타내는 수의 범위는 어느 것인가요?',ARRAY['M5-2-u1-X04']::text[],false,'{"seq":6,"concept":"M5-2-u1-C3","difficulty":1,"kind":"mc","stem":"수직선에 52에는 ○, 58에는 ●이 그려져 있고 두 점 사이가 선으로 이어져 있어요. 수직선이 나타내는 수의 범위는 어느 것인가요?","options":[{"t":"52 초과 58 이하인 수","correct":true},{"t":"52 이상 58 이하인 수","mis":"M5-2-u1-X04"},{"t":"52 초과 58 미만인 수","mis":"M5-2-u1-X04"},{"t":"52 이상 58 미만인 수","mis":"M5-2-u1-X04"}],"explanation":["●은 그 수를 포함하고 ○은 포함하지 않아요.","52는 ○이라 포함하지 않아요 · 58은 ●이라 포함해요.","그래서 52 초과 58 이하인 수예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_review_b#7','math',5,2,'u1','','g5_2_math_u1_review_b','unit_review','M5-2-u1-C3',2,'sa','auto','4.9, 5, 7, 10, 10.1, 8.5 중에서 5 이상 10 이하인 수는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":7,"concept":"M5-2-u1-C3","difficulty":2,"kind":"sa","stem":"4.9, 5, 7, 10, 10.1, 8.5 중에서 5 이상 10 이하인 수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["4","4개"],"explanation":["5 이상 10 이하인 수의 뜻에 맞는지 하나씩 확인해요.","들어가는 수는 5, 7, 10, 8.5예요.","모두 4개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_review_b#8','math',5,2,'u1','','g5_2_math_u1_review_b','unit_review','M5-2-u1-C3',3,'mc','auto','우체국 소포 요금표 — 5 kg 이하 4000원 · 5 kg 초과 10 kg 이하 5000원 · 10 kg 초과 20 kg 이하 7000원 · 20 kg 초과 25 kg 이하 9000원. 무게가 20.5 kg인 소포의 요금은 얼마인가요?',ARRAY['M5-2-u1-X02','M5-2-u1-X16']::text[],false,'{"seq":8,"concept":"M5-2-u1-C3","difficulty":3,"kind":"mc","stem":"우체국 소포 요금표 — 5 kg 이하 4000원 · 5 kg 초과 10 kg 이하 5000원 · 10 kg 초과 20 kg 이하 7000원 · 20 kg 초과 25 kg 이하 9000원. 무게가 20.5 kg인 소포의 요금은 얼마인가요?","options":[{"t":"9000원","correct":true},{"t":"7000원","mis":"M5-2-u1-X02"},{"t":"5000원","mis":"M5-2-u1-X16"},{"t":"4000원","mis":"M5-2-u1-X16"}],"explanation":["20.5 kg은 20 kg보다 무거워요.","「20 kg 초과 25 kg 이하」에 들어가요.","그래서 9000원이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_review_b#9','math',5,2,'u1','','g5_2_math_u1_review_b','unit_review','M5-2-u1-C4',1,'mc','auto','2503을 올림하여 천의 자리까지 나타내면 얼마인가요?',ARRAY['M5-2-u1-X08','M5-2-u1-X09']::text[],false,'{"seq":9,"concept":"M5-2-u1-C4","difficulty":1,"kind":"mc","stem":"2503을 올림하여 천의 자리까지 나타내면 얼마인가요?","options":[{"t":"3000","correct":true},{"t":"2000","mis":"M5-2-u1-X08"},{"t":"2600","mis":"M5-2-u1-X09"},{"t":"2510","mis":"M5-2-u1-X09"}],"explanation":["올림은 천의 자리 아래 수(503)을 올려서 나타내요.","아래 숫자가 무엇이든 0이 아니면 한 칸 올리고, 아래는 0으로 채워요.","2503 → 3000이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_review_b#10','math',5,2,'u1','','g5_2_math_u1_review_b','unit_review','M5-2-u1-C4',2,'mc','auto','4.521을 올림하여 소수 둘째 자리까지 나타내면 얼마인가요?',ARRAY['M5-2-u1-X08','M5-2-u1-X09','M5-2-u1-X16']::text[],false,'{"seq":10,"concept":"M5-2-u1-C4","difficulty":2,"kind":"mc","stem":"4.521을 올림하여 소수 둘째 자리까지 나타내면 얼마인가요?","options":[{"t":"4.53","correct":true},{"t":"4.52","mis":"M5-2-u1-X08"},{"t":"4.6","mis":"M5-2-u1-X09"},{"t":"4.54","mis":"M5-2-u1-X16"}],"explanation":["올림은 소수 둘째 자리 아래 수(0.001)을 올려서 나타내요.","아래 숫자가 무엇이든 0이 아니면 한 칸 올리고, 아래는 0으로 채워요.","4.521 → 4.53이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_review_b#11','math',5,2,'u1','','g5_2_math_u1_review_b','unit_review','M5-2-u1-C5',1,'mc','auto','6017을 버림하여 백의 자리까지 나타내면 얼마인가요?',ARRAY['M5-2-u1-X08','M5-2-u1-X09','M5-2-u1-X12']::text[],false,'{"seq":11,"concept":"M5-2-u1-C5","difficulty":1,"kind":"mc","stem":"6017을 버림하여 백의 자리까지 나타내면 얼마인가요?","options":[{"t":"6000","correct":true},{"t":"6100","mis":"M5-2-u1-X08"},{"t":"6010","mis":"M5-2-u1-X09"},{"t":"60","mis":"M5-2-u1-X12"}],"explanation":["버림은 백의 자리 아래 수(17)을 어떤 수든 버려요.","버린 자리는 0으로 채우거나(자연수) 지워요(소수).","6017 → 6000이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_review_b#12','math',5,2,'u1','','g5_2_math_u1_review_b','unit_review','M5-2-u1-C5',2,'sa','auto','과자 657개를 10개씩 포장해요. 포장한 봉지는 최대 몇 봉지인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":12,"concept":"M5-2-u1-C5","difficulty":2,"kind":"sa","stem":"과자 657개를 10개씩 포장해요. 포장한 봉지는 최대 몇 봉지인가요? 숫자로 쓰세요.","answer":["65","65봉지"],"explanation":["묶음이 다 차야 하나로 셀 수 있어요.","657을 버림하여 십의 자리까지 → 650개예요.","650개는 65봉지예요. 남는 것은 버려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_review_b#13','math',5,2,'u1','','g5_2_math_u1_review_b','unit_review','M5-2-u1-C6',1,'mc','auto','4752를 반올림하여 백의 자리까지 나타내면 얼마인가요?',ARRAY['M5-2-u1-X08','M5-2-u1-X09']::text[],false,'{"seq":13,"concept":"M5-2-u1-C6","difficulty":1,"kind":"mc","stem":"4752를 반올림하여 백의 자리까지 나타내면 얼마인가요?","options":[{"t":"4800","correct":true},{"t":"4700","mis":"M5-2-u1-X08"},{"t":"4750","mis":"M5-2-u1-X09"},{"t":"5000","mis":"M5-2-u1-X09"}],"explanation":["반올림은 구하려는 자리 바로 아래 한 자리만 봐요.","백의 자리 바로 아래 숫자가 5라 올려요.","4752 → 4800이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_review_b#14','math',5,2,'u1','','g5_2_math_u1_review_b','unit_review','M5-2-u1-C6',2,'mc','auto','1.573을 반올림하여 소수 첫째 자리까지 나타내면 얼마인가요?',ARRAY['M5-2-u1-X08','M5-2-u1-X09']::text[],false,'{"seq":14,"concept":"M5-2-u1-C6","difficulty":2,"kind":"mc","stem":"1.573을 반올림하여 소수 첫째 자리까지 나타내면 얼마인가요?","options":[{"t":"1.6","correct":true},{"t":"1.5","mis":"M5-2-u1-X08"},{"t":"1.57","mis":"M5-2-u1-X09"},{"t":"2","mis":"M5-2-u1-X09"}],"explanation":["반올림은 구하려는 자리 바로 아래 한 자리만 봐요.","소수 첫째 자리 바로 아래 숫자가 0이라 버려요.","1.573 → 1.6이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_review_b#15','math',5,2,'u1','','g5_2_math_u1_review_b','unit_review','M5-2-u1-C6',3,'mc','auto','반올림하여 백의 자리까지 나타낸 수가 3500이에요. 35□2의 □에 들어갈 수 있는 수를 모두 고른 것은 어느 것인가요?',ARRAY['M5-2-u1-X08','M5-2-u1-X16','M5-2-u1-X11']::text[],false,'{"seq":15,"concept":"M5-2-u1-C6","difficulty":3,"kind":"mc","stem":"반올림하여 백의 자리까지 나타낸 수가 3500이에요. 35□2의 □에 들어갈 수 있는 수를 모두 고른 것은 어느 것인가요?","options":[{"t":"0, 1, 2, 3, 4","correct":true},{"t":"5, 6, 7, 8, 9","mis":"M5-2-u1-X08"},{"t":"0, 1, 2, 3","mis":"M5-2-u1-X16"},{"t":"1, 2, 3, 4, 5","mis":"M5-2-u1-X11"}],"explanation":["십의 자리 □를 봐요.","3500이 되려면 버려야 하니 □는 0~4예요.","5~9면 3600이 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_review_b#16','math',5,2,'u1','','g5_2_math_u1_review_b','unit_review','M5-2-u1-C4',3,'mc','auto','올림하여 십의 자리까지 나타내면 80이 되는 자연수의 범위로 알맞은 것은 어느 것인가요?',ARRAY['M5-2-u1-X07','M5-2-u1-X08','M5-2-u1-X15']::text[],false,'{"seq":16,"concept":"M5-2-u1-C4","difficulty":3,"kind":"mc","stem":"올림하여 십의 자리까지 나타내면 80이 되는 자연수의 범위로 알맞은 것은 어느 것인가요?","options":[{"t":"70 초과 80 이하","correct":true},{"t":"70 이상 80 이하","mis":"M5-2-u1-X07"},{"t":"75 이상 85 미만","mis":"M5-2-u1-X08"},{"t":"80 이상 90 미만","mis":"M5-2-u1-X15"}],"explanation":["70은 올림해도 70 — 빠져요.","71부터 80까지가 80이 돼요.","그래서 70 초과 80 이하예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_review_b#17','math',5,2,'u1','','g5_2_math_u1_review_b','unit_review','M5-2-u1-C7',1,'mc','auto','사과를 10개씩 상자에 담아 팔 때 팔 수 있는 사과 수를 정할 때 알맞은 어림 방법은 어느 것인가요?',ARRAY['M5-2-u1-X13']::text[],false,'{"seq":17,"concept":"M5-2-u1-C7","difficulty":1,"kind":"mc","stem":"사과를 10개씩 상자에 담아 팔 때 팔 수 있는 사과 수를 정할 때 알맞은 어림 방법은 어느 것인가요?","options":[{"t":"버림","correct":true},{"t":"올림","mis":"M5-2-u1-X13"},{"t":"반올림","mis":"M5-2-u1-X13"},{"t":"아무 방법이나 좋다","mis":"M5-2-u1-X13"}],"explanation":["10개를 채우지 못한 사과는 상자에 담아 팔 수 없어요.","남는 것을 버려요.","그래서 버림이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_review_b#18','math',5,2,'u1','','g5_2_math_u1_review_b','unit_review','M5-2-u1-C7',2,'mc','auto','동전 58600원을 1000원짜리 지폐로 바꾼다면 최대 얼마까지 바꿀 수 있나요?',ARRAY['M5-2-u1-X13','M5-2-u1-X09','M5-2-u1-X17']::text[],false,'{"seq":18,"concept":"M5-2-u1-C7","difficulty":2,"kind":"mc","stem":"동전 58600원을 1000원짜리 지폐로 바꾼다면 최대 얼마까지 바꿀 수 있나요?","options":[{"t":"58000원","correct":true},{"t":"59000원","mis":"M5-2-u1-X13"},{"t":"50000원","mis":"M5-2-u1-X09"},{"t":"58600원","mis":"M5-2-u1-X17"}],"explanation":["1000원이 다 차야 한 장이에요.","58600을 버림하여 천의 자리까지 나타내요.","58000원이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_review_b#19','math',5,2,'u1','','g5_2_math_u1_review_b','unit_review','M5-2-u1-C7',3,'mc','auto','어림한 방법이 다른 친구는 누구인가요? 도하 — 「학생 128명에게 줄 공책을 10권 묶음으로 130권 사요.」 리아 — 「손님 45명이 앉도록 4인용 식탁을 12개 놓아요.」 준 — 「귤 87개를 10개씩 봉지에 담아 8봉지를 팔아요.」',ARRAY['M5-2-u1-X13']::text[],false,'{"seq":19,"concept":"M5-2-u1-C7","difficulty":3,"kind":"mc","stem":"어림한 방법이 다른 친구는 누구인가요? 도하 — 「학생 128명에게 줄 공책을 10권 묶음으로 130권 사요.」 리아 — 「손님 45명이 앉도록 4인용 식탁을 12개 놓아요.」 준 — 「귤 87개를 10개씩 봉지에 담아 8봉지를 팔아요.」","options":[{"t":"준","correct":true},{"t":"도하","mis":"M5-2-u1-X13"},{"t":"리아","mis":"M5-2-u1-X13"},{"t":"모두 같다","mis":"M5-2-u1-X13"}],"explanation":["도하·리아는 모자라면 안 돼 올림이에요.","준은 못 채운 7개를 버렸어요 — 버림이에요.","그래서 다른 친구는 준이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_review_b#20','math',5,2,'u1','','g5_2_math_u1_review_b','unit_review','M5-2-u1-C8',2,'sa','auto','고수 740 g이 필요한데 100 g씩 한 봉지로 팔아요. 몇 봉지를 사야 하나요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":20,"concept":"M5-2-u1-C8","difficulty":2,"kind":"sa","stem":"고수 740 g이 필요한데 100 g씩 한 봉지로 팔아요. 몇 봉지를 사야 하나요? 숫자로 쓰세요.","answer":["8","8봉지"],"explanation":["7봉지는 700 g이라 40 g이 모자라요.","모자라면 요리를 못 하니 올림이에요.","740 g → 800 g, 8봉지예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_review_b#21','math',5,2,'u1','','g5_2_math_u1_review_b','unit_review','M5-2-u1-C8',3,'mc','auto','반미 재료 — 바게트 15개(1개 2380원, 1개씩 판매) · 고수 740 g(100 g 한 봉지 1450원) · 당근 1.2 kg(1 kg 한 봉지 3600원). 구입할 양은 올림으로 정하고, 가격은 반올림하여 천의 자리까지 나타내 어림셈하면 구입 비용은 약 얼마인가요?',ARRAY['M5-2-u1-X08','M5-2-u1-X17','M5-2-u1-X13']::text[],false,'{"seq":21,"concept":"M5-2-u1-C8","difficulty":3,"kind":"mc","stem":"반미 재료 — 바게트 15개(1개 2380원, 1개씩 판매) · 고수 740 g(100 g 한 봉지 1450원) · 당근 1.2 kg(1 kg 한 봉지 3600원). 구입할 양은 올림으로 정하고, 가격은 반올림하여 천의 자리까지 나타내 어림셈하면 구입 비용은 약 얼마인가요?","options":[{"t":"46000원","correct":true},{"t":"54000원","mis":"M5-2-u1-X08"},{"t":"54500원","mis":"M5-2-u1-X17"},{"t":"42000원","mis":"M5-2-u1-X13"}],"explanation":["고수 8봉지, 당근 2봉지예요.","어림 가격 — 2000원, 1000원, 4000원이에요.","30000 + 8000 + 8000 = 46000원이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_review_b#22','math',5,2,'u1','','g5_2_math_u1_review_b','unit_review','M5-2-u1-C5',3,'mc','auto','수 카드 5, 2, 8, 4를 한 번씩만 써서 가장 큰 네 자리 수를 만들었어요. 그 수를 버림하여 백의 자리까지 나타내면 얼마인가요?',ARRAY['M5-2-u1-X08','M5-2-u1-X09']::text[],false,'{"seq":22,"concept":"M5-2-u1-C5","difficulty":3,"kind":"mc","stem":"수 카드 5, 2, 8, 4를 한 번씩만 써서 가장 큰 네 자리 수를 만들었어요. 그 수를 버림하여 백의 자리까지 나타내면 얼마인가요?","options":[{"t":"8500","correct":true},{"t":"8600","mis":"M5-2-u1-X08"},{"t":"8540","mis":"M5-2-u1-X09"},{"t":"8000","mis":"M5-2-u1-X09"}],"explanation":["수 카드로 만든 수는 8542예요.","버림은 백의 자리 아래 수(42)를 어떤 수든 버려요.","8542 → 8500이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_review_b#23','math',5,2,'u1','','g5_2_math_u1_review_b','unit_review','M5-2-u1-C3',4,'essay','teacher','우체국 소포 요금표 — 5 kg 이하 4000원 · 5 kg 초과 10 kg 이하 5000원 · 10 kg 초과 20 kg 이하 7000원 · 20 kg 초과 25 kg 이하 9000원. 10 kg인 소포와 10.1 kg인 소포의 요금을 각각 구하고, 0.1 kg 차이로 요금이 달라지는 까닭을 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"M5-2-u1-C3","difficulty":4,"kind":"essay","stem":"우체국 소포 요금표 — 5 kg 이하 4000원 · 5 kg 초과 10 kg 이하 5000원 · 10 kg 초과 20 kg 이하 7000원 · 20 kg 초과 25 kg 이하 9000원. 10 kg인 소포와 10.1 kg인 소포의 요금을 각각 구하고, 0.1 kg 차이로 요금이 달라지는 까닭을 쓰세요.","answer_guide":{"answer":"예: 10 kg은 「5 kg 초과 10 kg 이하」라 5000원, 10.1 kg은 「10 kg 초과 20 kg 이하」라 7000원이다. 10 kg이 경곗값이라 10 kg까지는 이하 쪽에 들고, 조금이라도 넘으면 다음 범위가 되기 때문이다.","scoring_points":["10 kg 요금 5000원을 구했는가","10.1 kg 요금 7000원을 구했는가","경곗값을 넘는지로 범위가 바뀐다는 까닭을 썼는가"]},"explanation":["10 kg — 이하라 5000원이에요.","10.1 kg — 초과라 7000원이에요.","경곗값을 넘으면 다음 줄이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_review_b#24','math',5,2,'u1','','g5_2_math_u1_review_b','unit_review','M5-2-u1-C7',4,'essay','teacher','관람객 5217명을 백의 자리까지 버림해도 반올림해도 5200이에요. 결과가 같아진 까닭을 쓰고, 결과가 달라지는 수를 하나 들어 설명하세요.','{}'::text[],false,'{"seq":24,"concept":"M5-2-u1-C7","difficulty":4,"kind":"essay","stem":"관람객 5217명을 백의 자리까지 버림해도 반올림해도 5200이에요. 결과가 같아진 까닭을 쓰고, 결과가 달라지는 수를 하나 들어 설명하세요.","answer_guide":{"answer":"예: 십의 자리 숫자가 1이라 반올림에서도 버려지기 때문이다. 5267은 버림하면 5200, 반올림하면 5300으로 달라진다.","scoring_points":["십의 자리 숫자가 0~4라 반올림도 버린다고 썼는가","달라지는 수의 예를 들었는가","그 수의 두 결과를 바르게 썼는가"]},"explanation":["5217의 십의 자리 숫자는 1이에요.","반올림도 버려 버림과 같아요.","5267은 5200과 5300으로 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_review_b#25','math',5,2,'u1','','g5_2_math_u1_review_b','unit_review','M5-2-u1-C8',4,'essay','teacher','탄두리치킨 재료 — 닭고기 20마리(1마리 8800원, 1마리씩 판매) · 카레 가루 480 g(100 g 한 봉지 1900원) · 고춧가루 220 g(100 g 한 봉지 2150원). 어림셈한 비용(약 196000원)과 실제 비용(191950원)을 견주고, 어림셈의 좋은 점을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"M5-2-u1-C8","difficulty":4,"kind":"essay","stem":"탄두리치킨 재료 — 닭고기 20마리(1마리 8800원, 1마리씩 판매) · 카레 가루 480 g(100 g 한 봉지 1900원) · 고춧가루 220 g(100 g 한 봉지 2150원). 어림셈한 비용(약 196000원)과 실제 비용(191950원)을 견주고, 어림셈의 좋은 점을 쓰세요.","answer_guide":{"answer":"예: 어림셈이 실제보다 4050원 많아 꽤 가깝다. 계산이 쉬워 사러 가기 전에 준비할 돈을 빨리 가늠할 수 있다.","scoring_points":["두 값의 차나 크기를 견주었는가","어림셈이 실제와 가깝다고 썼는가","준비할 돈을 쉽게 가늠한다는 좋은 점을 썼는가"]},"explanation":["196000 − 191950 = 4050원이에요.","꽤 가까워요.","미리 쉽게 가늠할 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_review_c#1','math',5,2,'u1','','g5_2_math_u1_review_c','unit_review','M5-2-u1-C1',1,'sa','auto','59, 60, 61.5, 72, 58.9 중에서 60 이상인 수는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"M5-2-u1-C1","difficulty":1,"kind":"sa","stem":"59, 60, 61.5, 72, 58.9 중에서 60 이상인 수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["3","3개"],"explanation":["60 이상인 수의 뜻에 맞는지 하나씩 확인해요.","들어가는 수는 60, 61.5, 72예요.","모두 3개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_review_c#2','math',5,2,'u1','','g5_2_math_u1_review_c','unit_review','M5-2-u1-C1',2,'mc','auto','「점수가 90점 (  )이면 상을 받아요.」 딱 90점인 친구도 상을 받는다면 (  )에 알맞은 말은 어느 것인가요?',ARRAY['M5-2-u1-X02','M5-2-u1-X03']::text[],false,'{"seq":2,"concept":"M5-2-u1-C1","difficulty":2,"kind":"mc","stem":"「점수가 90점 (  )이면 상을 받아요.」 딱 90점인 친구도 상을 받는다면 (  )에 알맞은 말은 어느 것인가요?","options":[{"t":"이상","correct":true},{"t":"초과","mis":"M5-2-u1-X02"},{"t":"이하","mis":"M5-2-u1-X03"},{"t":"미만","mis":"M5-2-u1-X03"}],"explanation":["점수가 높은 쪽이 받으니 「이상」이나 「초과」예요.","딱 90점도 들어가야 해요.","경곗값을 넣는 말은 「이상」이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_review_c#3','math',5,2,'u1','','g5_2_math_u1_review_c','unit_review','M5-2-u1-C2',1,'mc','auto','자동차 높이 4.5 m, 4.4 m, 5 m, 4.6 m 중에서 4.4 m 초과가 아닌 것은 어느 것인가요?',ARRAY['M5-2-u1-X17']::text[],false,'{"seq":3,"concept":"M5-2-u1-C2","difficulty":1,"kind":"mc","stem":"자동차 높이 4.5 m, 4.4 m, 5 m, 4.6 m 중에서 4.4 m 초과가 아닌 것은 어느 것인가요?","options":[{"t":"4.4 m","correct":true},{"t":"4.5 m","mis":"M5-2-u1-X17"},{"t":"5 m","mis":"M5-2-u1-X17"},{"t":"4.6 m","mis":"M5-2-u1-X17"}],"explanation":["4.4 m 초과는 경곗값을 포함하지 않아요.","4.4 m만 범위에서 벗어나요.","그래서 아닌 것은 4.4 m예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_review_c#4','math',5,2,'u1','','g5_2_math_u1_review_c','unit_review','M5-2-u1-C2',2,'ox','auto','13세 미만 어린이 요금은 딱 13세인 어린이도 낼 수 있어요.',ARRAY['M5-2-u1-X02']::text[],false,'{"seq":4,"concept":"M5-2-u1-C2","difficulty":2,"kind":"ox","stem":"13세 미만 어린이 요금은 딱 13세인 어린이도 낼 수 있어요.","answer":"X","reason_options":[{"t":"13세 미만에는 13세가 들어가지 않아서","correct":true},{"t":"미만에도 경곗값이 들어가서","mis":"M5-2-u1-X02"}],"mis":"M5-2-u1-X02","explanation":["13세 미만은 13세보다 적은 나이예요.","딱 13세는 들어가지 않아요.","13세는 다음 요금을 내요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_review_c#5','math',5,2,'u1','','g5_2_math_u1_review_c','unit_review','M5-2-u1-C2',1,'mc','auto','수직선에 19에 ○이 그려져 있고 거기서 오른쪽으로 선이 그어져 있어요. 수직선이 나타내는 수의 범위는 어느 것인가요?',ARRAY['M5-2-u1-X04','M5-2-u1-X03']::text[],false,'{"seq":5,"concept":"M5-2-u1-C2","difficulty":1,"kind":"mc","stem":"수직선에 19에 ○이 그려져 있고 거기서 오른쪽으로 선이 그어져 있어요. 수직선이 나타내는 수의 범위는 어느 것인가요?","options":[{"t":"19 초과인 수","correct":true},{"t":"19 이상인 수","mis":"M5-2-u1-X04"},{"t":"19 미만인 수","mis":"M5-2-u1-X03"},{"t":"19 이하인 수","mis":"M5-2-u1-X03"}],"explanation":["●은 그 수를 포함하고 ○은 포함하지 않아요.","19는 ○이라 포함하지 않아요.","그래서 19 초과인 수예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_review_c#6','math',5,2,'u1','','g5_2_math_u1_review_c','unit_review','M5-2-u1-C3',1,'mc','auto','수직선에 12에는 ●, 24에는 ○이 그려져 있고 두 점 사이가 선으로 이어져 있어요. 수직선이 나타내는 수의 범위는 어느 것인가요?',ARRAY['M5-2-u1-X04']::text[],false,'{"seq":6,"concept":"M5-2-u1-C3","difficulty":1,"kind":"mc","stem":"수직선에 12에는 ●, 24에는 ○이 그려져 있고 두 점 사이가 선으로 이어져 있어요. 수직선이 나타내는 수의 범위는 어느 것인가요?","options":[{"t":"12 이상 24 미만인 수","correct":true},{"t":"12 초과 24 미만인 수","mis":"M5-2-u1-X04"},{"t":"12 이상 24 이하인 수","mis":"M5-2-u1-X04"},{"t":"12 초과 24 이하인 수","mis":"M5-2-u1-X04"}],"explanation":["●은 그 수를 포함하고 ○은 포함하지 않아요.","12는 ●이라 포함해요 · 24는 ○이라 포함하지 않아요.","그래서 12 이상 24 미만인 수예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_review_c#7','math',5,2,'u1','','g5_2_math_u1_review_c','unit_review','M5-2-u1-C3',2,'sa','auto','30, 31, 40, 40.5, 35, 29 중에서 30 초과 40 이하인 수는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":7,"concept":"M5-2-u1-C3","difficulty":2,"kind":"sa","stem":"30, 31, 40, 40.5, 35, 29 중에서 30 초과 40 이하인 수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["3","3개"],"explanation":["30 초과 40 이하인 수의 뜻에 맞는지 하나씩 확인해요.","들어가는 수는 31, 40, 35예요.","모두 3개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_review_c#8','math',5,2,'u1','','g5_2_math_u1_review_c','unit_review','M5-2-u1-C3',3,'mc','auto','어린이 감기약 용량표 — 4세 이상 7세 미만 한 번에 5 mL · 7세 이상 11세 미만 7.5 mL · 11세 이상 15세 미만 10 mL. 15세 미만까지만 이 약을 먹을 수 있어요. 지후는 4세, 은수는 11세예요. 두 사람이 한 번에 먹는 약은 모두 몇 mL인가요?',ARRAY['M5-2-u1-X01','M5-2-u1-X16','M5-2-u1-X03']::text[],false,'{"seq":8,"concept":"M5-2-u1-C3","difficulty":3,"kind":"mc","stem":"어린이 감기약 용량표 — 4세 이상 7세 미만 한 번에 5 mL · 7세 이상 11세 미만 7.5 mL · 11세 이상 15세 미만 10 mL. 15세 미만까지만 이 약을 먹을 수 있어요. 지후는 4세, 은수는 11세예요. 두 사람이 한 번에 먹는 약은 모두 몇 mL인가요?","options":[{"t":"15 mL","correct":true},{"t":"12.5 mL","mis":"M5-2-u1-X01"},{"t":"17.5 mL","mis":"M5-2-u1-X16"},{"t":"20 mL","mis":"M5-2-u1-X03"}],"explanation":["지후 4세는 「4세 이상 7세 미만」 — 5 mL예요.","은수 11세는 「11세 이상 15세 미만」 — 10 mL예요.","5 + 10 = 15 mL예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_review_c#9','math',5,2,'u1','','g5_2_math_u1_review_c','unit_review','M5-2-u1-C4',1,'mc','auto','1204를 올림하여 백의 자리까지 나타내면 얼마인가요?',ARRAY['M5-2-u1-X08','M5-2-u1-X09']::text[],false,'{"seq":9,"concept":"M5-2-u1-C4","difficulty":1,"kind":"mc","stem":"1204를 올림하여 백의 자리까지 나타내면 얼마인가요?","options":[{"t":"1300","correct":true},{"t":"1200","mis":"M5-2-u1-X08"},{"t":"1210","mis":"M5-2-u1-X09"},{"t":"2000","mis":"M5-2-u1-X09"}],"explanation":["올림은 백의 자리 아래 수(04)를 올려서 나타내요.","아래 숫자가 무엇이든 0이 아니면 한 칸 올리고, 아래는 0으로 채워요.","1204 → 1300이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_review_c#10','math',5,2,'u1','','g5_2_math_u1_review_c','unit_review','M5-2-u1-C4',2,'mc','auto','2.031을 올림하여 일의 자리까지 나타내면 얼마인가요?',ARRAY['M5-2-u1-X08','M5-2-u1-X09']::text[],false,'{"seq":10,"concept":"M5-2-u1-C4","difficulty":2,"kind":"mc","stem":"2.031을 올림하여 일의 자리까지 나타내면 얼마인가요?","options":[{"t":"3","correct":true},{"t":"2","mis":"M5-2-u1-X08"},{"t":"2.1","mis":"M5-2-u1-X09"},{"t":"10","mis":"M5-2-u1-X09"}],"explanation":["올림은 일의 자리 아래 수(0.031)을 올려서 나타내요.","아래 숫자가 무엇이든 0이 아니면 한 칸 올리고, 아래는 0으로 채워요.","2.031 → 3이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_review_c#11','math',5,2,'u1','','g5_2_math_u1_review_c','unit_review','M5-2-u1-C5',1,'mc','auto','4953을 버림하여 백의 자리까지 나타내면 얼마인가요?',ARRAY['M5-2-u1-X08','M5-2-u1-X09']::text[],false,'{"seq":11,"concept":"M5-2-u1-C5","difficulty":1,"kind":"mc","stem":"4953을 버림하여 백의 자리까지 나타내면 얼마인가요?","options":[{"t":"4900","correct":true},{"t":"5000","mis":"M5-2-u1-X08"},{"t":"4950","mis":"M5-2-u1-X09"},{"t":"4000","mis":"M5-2-u1-X09"}],"explanation":["버림은 백의 자리 아래 수(53)을 어떤 수든 버려요.","버린 자리는 0으로 채우거나(자연수) 지워요(소수).","4953 → 4900이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_review_c#12','math',5,2,'u1','','g5_2_math_u1_review_c','unit_review','M5-2-u1-C5',2,'sa','auto','밭에서 딴 가지 73 kg을 한 상자에 10 kg씩 담아요. 가지를 담은 상자는 최대 몇 상자인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":12,"concept":"M5-2-u1-C5","difficulty":2,"kind":"sa","stem":"밭에서 딴 가지 73 kg을 한 상자에 10 kg씩 담아요. 가지를 담은 상자는 최대 몇 상자인가요? 숫자로 쓰세요.","answer":["7","7상자"],"explanation":["묶음이 다 차야 하나로 셀 수 있어요.","73을 버림하여 십의 자리까지 → 70 kg이에요.","70 kg은 7상자예요. 남는 것은 버려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_review_c#13','math',5,2,'u1','','g5_2_math_u1_review_c','unit_review','M5-2-u1-C6',1,'mc','auto','8542를 반올림하여 천의 자리까지 나타내면 얼마인가요?',ARRAY['M5-2-u1-X08','M5-2-u1-X09']::text[],false,'{"seq":13,"concept":"M5-2-u1-C6","difficulty":1,"kind":"mc","stem":"8542를 반올림하여 천의 자리까지 나타내면 얼마인가요?","options":[{"t":"9000","correct":true},{"t":"8000","mis":"M5-2-u1-X08"},{"t":"8500","mis":"M5-2-u1-X09"},{"t":"8540","mis":"M5-2-u1-X09"}],"explanation":["반올림은 구하려는 자리 바로 아래 한 자리만 봐요.","천의 자리 바로 아래 숫자가 5라 올려요.","8542 → 9000이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_review_c#14','math',5,2,'u1','','g5_2_math_u1_review_c','unit_review','M5-2-u1-C6',2,'mc','auto','0.758을 반올림하여 소수 첫째 자리까지 나타내면 얼마인가요?',ARRAY['M5-2-u1-X08','M5-2-u1-X09']::text[],false,'{"seq":14,"concept":"M5-2-u1-C6","difficulty":2,"kind":"mc","stem":"0.758을 반올림하여 소수 첫째 자리까지 나타내면 얼마인가요?","options":[{"t":"0.8","correct":true},{"t":"0.7","mis":"M5-2-u1-X08"},{"t":"0.76","mis":"M5-2-u1-X09"},{"t":"1","mis":"M5-2-u1-X09"}],"explanation":["반올림은 구하려는 자리 바로 아래 한 자리만 봐요.","소수 첫째 자리 바로 아래 숫자가 0이라 버려요.","0.758 → 0.8이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_review_c#15','math',5,2,'u1','','g5_2_math_u1_review_c','unit_review','M5-2-u1-C6',3,'mc','auto','반올림하여 천의 자리까지 나타낸 수가 4000이에요. 3□84의 □에 들어갈 수 있는 수를 모두 고른 것은 어느 것인가요?',ARRAY['M5-2-u1-X08','M5-2-u1-X11','M5-2-u1-X16']::text[],false,'{"seq":15,"concept":"M5-2-u1-C6","difficulty":3,"kind":"mc","stem":"반올림하여 천의 자리까지 나타낸 수가 4000이에요. 3□84의 □에 들어갈 수 있는 수를 모두 고른 것은 어느 것인가요?","options":[{"t":"5, 6, 7, 8, 9","correct":true},{"t":"0, 1, 2, 3, 4","mis":"M5-2-u1-X08"},{"t":"6, 7, 8, 9","mis":"M5-2-u1-X11"},{"t":"4, 5, 6, 7, 8","mis":"M5-2-u1-X16"}],"explanation":["백의 자리 □를 봐요.","4000이 되려면 올려야 하니 □는 5~9예요.","0~4면 3000이 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_review_c#16','math',5,2,'u1','','g5_2_math_u1_review_c','unit_review','M5-2-u1-C4',3,'mc','auto','올림하여 십의 자리까지 나타내면 230이 되는 자연수 중에서 가장 큰 수는 얼마인가요?',ARRAY['M5-2-u1-X15','M5-2-u1-X08']::text[],false,'{"seq":16,"concept":"M5-2-u1-C4","difficulty":3,"kind":"mc","stem":"올림하여 십의 자리까지 나타내면 230이 되는 자연수 중에서 가장 큰 수는 얼마인가요?","options":[{"t":"230","correct":true},{"t":"229","mis":"M5-2-u1-X15"},{"t":"234","mis":"M5-2-u1-X08"},{"t":"239","mis":"M5-2-u1-X15"}],"explanation":["221부터 229까지 올림하면 230이에요.","230은 그대로 230이에요.","231부터는 240이라 가장 큰 수는 230이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_review_c#17','math',5,2,'u1','','g5_2_math_u1_review_c','unit_review','M5-2-u1-C7',1,'mc','auto','우리나라 도시별 인구를 실제와 가깝게 그래프로 나타낼 때 알맞은 어림 방법은 어느 것인가요?',ARRAY['M5-2-u1-X13']::text[],false,'{"seq":17,"concept":"M5-2-u1-C7","difficulty":1,"kind":"mc","stem":"우리나라 도시별 인구를 실제와 가깝게 그래프로 나타낼 때 알맞은 어림 방법은 어느 것인가요?","options":[{"t":"반올림","correct":true},{"t":"올림","mis":"M5-2-u1-X13"},{"t":"버림","mis":"M5-2-u1-X13"},{"t":"아무 방법이나 좋다","mis":"M5-2-u1-X13"}],"explanation":["실제와 차이가 작아야 해요.","원래 수에 가장 가까운 반올림이에요.","그래서 반올림이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_review_c#18','math',5,2,'u1','','g5_2_math_u1_review_c','unit_review','M5-2-u1-C7',2,'mc','auto','운동화 37500원을 10000원짜리 지폐로만 낸다면 최소 얼마를 내야 하나요?',ARRAY['M5-2-u1-X13','M5-2-u1-X09','M5-2-u1-X17']::text[],false,'{"seq":18,"concept":"M5-2-u1-C7","difficulty":2,"kind":"mc","stem":"운동화 37500원을 10000원짜리 지폐로만 낸다면 최소 얼마를 내야 하나요?","options":[{"t":"40000원","correct":true},{"t":"30000원","mis":"M5-2-u1-X13"},{"t":"38000원","mis":"M5-2-u1-X09"},{"t":"37500원","mis":"M5-2-u1-X17"}],"explanation":["10000원 3장은 30000원이라 모자라요.","37500을 올림하여 만의 자리까지 나타내요.","40000원이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_review_c#19','math',5,2,'u1','','g5_2_math_u1_review_c','unit_review','M5-2-u1-C7',3,'mc','auto','어림한 방법이 다른 친구는 누구인가요? 하율 — 「버스 45인승에 136명이 타려고 4대를 불러요.」 서진 — 「밀가루 3.2 kg이 필요해 1 kg짜리 4봉지를 사요.」 무진 — 「리본 357 cm로 1 m짜리 꽃을 3송이 만들어요.」',ARRAY['M5-2-u1-X13']::text[],false,'{"seq":19,"concept":"M5-2-u1-C7","difficulty":3,"kind":"mc","stem":"어림한 방법이 다른 친구는 누구인가요? 하율 — 「버스 45인승에 136명이 타려고 4대를 불러요.」 서진 — 「밀가루 3.2 kg이 필요해 1 kg짜리 4봉지를 사요.」 무진 — 「리본 357 cm로 1 m짜리 꽃을 3송이 만들어요.」","options":[{"t":"무진","correct":true},{"t":"하율","mis":"M5-2-u1-X13"},{"t":"서진","mis":"M5-2-u1-X13"},{"t":"모두 같다","mis":"M5-2-u1-X13"}],"explanation":["하율·서진은 모자라면 안 돼 올림이에요.","무진은 남은 57 cm를 버렸어요 — 버림이에요.","그래서 다른 친구는 무진이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_review_c#20','math',5,2,'u1','','g5_2_math_u1_review_c','unit_review','M5-2-u1-C8',2,'sa','auto','치즈 1350 g이 필요한데 500 g씩 한 봉지로 팔아요. 몇 봉지를 사야 하나요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":20,"concept":"M5-2-u1-C8","difficulty":2,"kind":"sa","stem":"치즈 1350 g이 필요한데 500 g씩 한 봉지로 팔아요. 몇 봉지를 사야 하나요? 숫자로 쓰세요.","answer":["3","3봉지"],"explanation":["2봉지는 1000 g이라 350 g이 모자라요.","모자라면 요리를 못 하니 올림이에요.","1350 g → 1500 g, 3봉지예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_review_c#21','math',5,2,'u1','','g5_2_math_u1_review_c','unit_review','M5-2-u1-C8',3,'mc','auto','탄두리치킨 재료 — 닭고기 20마리(1마리 8800원, 1마리씩 판매) · 카레 가루 480 g(100 g 한 봉지 1900원) · 고춧가루 220 g(100 g 한 봉지 2150원). 실제 구입 비용은 모두 얼마인가요?',ARRAY['M5-2-u1-X17','M5-2-u1-X16']::text[],false,'{"seq":21,"concept":"M5-2-u1-C8","difficulty":3,"kind":"mc","stem":"탄두리치킨 재료 — 닭고기 20마리(1마리 8800원, 1마리씩 판매) · 카레 가루 480 g(100 g 한 봉지 1900원) · 고춧가루 220 g(100 g 한 봉지 2150원). 실제 구입 비용은 모두 얼마인가요?","options":[{"t":"191950원","correct":true},{"t":"196000원","mis":"M5-2-u1-X17"},{"t":"190950원","mis":"M5-2-u1-X16"},{"t":"176000원","mis":"M5-2-u1-X16"}],"explanation":["닭고기 8800 × 20 = 176000원이에요.","카레 가루 1900 × 5 = 9500원, 고춧가루 2150 × 3 = 6450원이에요.","모두 191950원이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_review_c#22','math',5,2,'u1','','g5_2_math_u1_review_c','unit_review','M5-2-u1-C5',3,'mc','auto','수 카드 9, 0, 4, 6을 한 번씩만 써서 가장 큰 네 자리 수를 만들었어요. 그 수를 버림하여 백의 자리까지 나타내면 얼마인가요?',ARRAY['M5-2-u1-X08','M5-2-u1-X09','M5-2-u1-X12']::text[],false,'{"seq":22,"concept":"M5-2-u1-C5","difficulty":3,"kind":"mc","stem":"수 카드 9, 0, 4, 6을 한 번씩만 써서 가장 큰 네 자리 수를 만들었어요. 그 수를 버림하여 백의 자리까지 나타내면 얼마인가요?","options":[{"t":"9600","correct":true},{"t":"9700","mis":"M5-2-u1-X08"},{"t":"9000","mis":"M5-2-u1-X09"},{"t":"96","mis":"M5-2-u1-X12"}],"explanation":["수 카드로 만든 수는 9640이에요.","버림은 백의 자리 아래 수(40)을 어떤 수든 버려요.","9640 → 9600이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_review_c#23','math',5,2,'u1','','g5_2_math_u1_review_c','unit_review','M5-2-u1-C3',4,'essay','teacher','「5 이상 10 미만인 수」와 「5 초과 10 이하인 수」를 수직선에 각각 어떻게 나타내는지 쓰고, 두 범위에 함께 들어가지 않는 수를 모두 찾아 설명하세요.','{}'::text[],false,'{"seq":23,"concept":"M5-2-u1-C3","difficulty":4,"kind":"essay","stem":"「5 이상 10 미만인 수」와 「5 초과 10 이하인 수」를 수직선에 각각 어떻게 나타내는지 쓰고, 두 범위에 함께 들어가지 않는 수를 모두 찾아 설명하세요.","answer_guide":{"answer":"예: 5 이상 10 미만은 5에 ●, 10에 ○을 그리고 잇는다. 5 초과 10 이하는 5에 ○, 10에 ●을 그리고 잇는다. 5는 앞의 범위에만, 10은 뒤의 범위에만 들어가므로 함께 들어가지 않는 수는 5와 10이다.","scoring_points":["5 이상 10 미만을 ●·○으로 바르게 나타냈는가","5 초과 10 이하를 ○·●으로 바르게 나타냈는가","5와 10을 찾고 까닭을 썼는가"]},"explanation":["5 이상 10 미만 — 5 ●, 10 ○이에요.","5 초과 10 이하 — 5 ○, 10 ●이에요.","양 끝 5와 10만 한쪽에만 들어가요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_review_c#24','math',5,2,'u1','','g5_2_math_u1_review_c','unit_review','M5-2-u1-C7',4,'essay','teacher','학생 53명이 10명씩 타는 엘리베이터로 이동할 때와 젤리 53개를 10개씩 봉지에 담아 팔 때, 같은 수 53을 어떻게 어림하는지 각각 쓰고 까닭을 설명하세요.','{}'::text[],false,'{"seq":24,"concept":"M5-2-u1-C7","difficulty":4,"kind":"essay","stem":"학생 53명이 10명씩 타는 엘리베이터로 이동할 때와 젤리 53개를 10개씩 봉지에 담아 팔 때, 같은 수 53을 어떻게 어림하는지 각각 쓰고 까닭을 설명하세요.","answer_guide":{"answer":"예: 엘리베이터는 남은 3명도 타야 하니 올림하여 60명분, 6번 운행한다. 젤리는 10개를 채우지 못한 3개를 팔 수 없으니 버림하여 50개, 5봉지를 판다. 같은 수라도 하려는 일이 달라 방법이 갈린다.","scoring_points":["엘리베이터는 올림(6번)이라고 썼는가","젤리는 버림(5봉지)이라고 썼는가","하려는 일에 따라 갈린다고 썼는가"]},"explanation":["엘리베이터 — 모두 태워야 하니 올림이에요.","젤리 — 못 채운 것은 못 파니 버림이에요.","같은 수라도 상황이 방법을 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_review_c#25','math',5,2,'u1','','g5_2_math_u1_review_c','unit_review','M5-2-u1-C8',4,'essay','teacher','반미 재료 — 바게트 15개(1개 2380원, 1개씩 판매) · 고수 740 g(100 g 한 봉지 1450원) · 당근 1.2 kg(1 kg 한 봉지 3600원). 반올림으로 어림셈한 값은 46000원이고 실제 비용은 54500원이에요. 차이가 크게 난 까닭을 쓰고, 예산이 모자라지 않게 준비하려면 어떻게 어림하면 좋을지 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"M5-2-u1-C8","difficulty":4,"kind":"essay","stem":"반미 재료 — 바게트 15개(1개 2380원, 1개씩 판매) · 고수 740 g(100 g 한 봉지 1450원) · 당근 1.2 kg(1 kg 한 봉지 3600원). 반올림으로 어림셈한 값은 46000원이고 실제 비용은 54500원이에요. 차이가 크게 난 까닭을 쓰고, 예산이 모자라지 않게 준비하려면 어떻게 어림하면 좋을지 쓰세요.","answer_guide":{"answer":"예: 바게트 2380원을 2000원으로, 고수 1450원을 1000원으로 많이 내려 어림해 실제보다 작아졌다. 모자라지 않게 준비하려면 가격을 올림하여 어림셈하면 실제보다 같거나 크게 나와 안전하다.","scoring_points":["가격을 내려 어림한 탓이라고 썼는가","어떤 가격이 많이 내려갔는지 예를 들었는가","올림으로 어림셈하면 모자라지 않는다고 썼는가"]},"explanation":["반올림에서 많이 내려간 가격이 있어요.","그래서 어림셈이 실제보다 작아졌어요.","모자라지 않게 하려면 올림으로 어림셈해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_review_d#1','math',5,2,'u1','','g5_2_math_u1_review_d','unit_review','M5-2-u1-C1',1,'sa','auto','4.5, 4.6, 3, 4.49, 5 중에서 4.5 이하인 수는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"M5-2-u1-C1","difficulty":1,"kind":"sa","stem":"4.5, 4.6, 3, 4.49, 5 중에서 4.5 이하인 수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["3","3개"],"explanation":["4.5 이하인 수의 뜻에 맞는지 하나씩 확인해요.","들어가는 수는 4.5, 3, 4.49예요.","모두 3개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_review_d#2','math',5,2,'u1','','g5_2_math_u1_review_d','unit_review','M5-2-u1-C1',2,'mc','auto','「무게가 2 kg (  )인 소포는 작은 상자에 담아요.」 딱 2 kg인 소포도 담는다면 (  )에 알맞은 말은 어느 것인가요?',ARRAY['M5-2-u1-X02','M5-2-u1-X03']::text[],false,'{"seq":2,"concept":"M5-2-u1-C1","difficulty":2,"kind":"mc","stem":"「무게가 2 kg (  )인 소포는 작은 상자에 담아요.」 딱 2 kg인 소포도 담는다면 (  )에 알맞은 말은 어느 것인가요?","options":[{"t":"이하","correct":true},{"t":"미만","mis":"M5-2-u1-X02"},{"t":"이상","mis":"M5-2-u1-X03"},{"t":"초과","mis":"M5-2-u1-X03"}],"explanation":["가벼운 쪽이 담기니 「이하」나 「미만」이에요.","딱 2 kg도 들어가야 해요.","경곗값을 넣는 말은 「이하」예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_review_d#3','math',5,2,'u1','','g5_2_math_u1_review_d','unit_review','M5-2-u1-C2',1,'mc','auto','물통 1.9 L, 1.5 L, 2 L, 0.8 L 중에서 2 L 미만이 아닌 것은 어느 것인가요?',ARRAY['M5-2-u1-X17']::text[],false,'{"seq":3,"concept":"M5-2-u1-C2","difficulty":1,"kind":"mc","stem":"물통 1.9 L, 1.5 L, 2 L, 0.8 L 중에서 2 L 미만이 아닌 것은 어느 것인가요?","options":[{"t":"2 L","correct":true},{"t":"1.9 L","mis":"M5-2-u1-X17"},{"t":"1.5 L","mis":"M5-2-u1-X17"},{"t":"0.8 L","mis":"M5-2-u1-X17"}],"explanation":["2 L 미만은 경곗값을 포함하지 않아요.","2 L만 범위에서 벗어나요.","그래서 아닌 것은 2 L예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_review_d#4','math',5,2,'u1','','g5_2_math_u1_review_d','unit_review','M5-2-u1-C2',2,'ox','auto','40 초과인 수와 40 이상인 수는 40만 달라요.',ARRAY['M5-2-u1-X02']::text[],false,'{"seq":4,"concept":"M5-2-u1-C2","difficulty":2,"kind":"ox","stem":"40 초과인 수와 40 이상인 수는 40만 달라요.","answer":"O","reason_options":[{"t":"40 이상에는 40이 들어가고 40 초과에는 빠져서","correct":true},{"t":"두 말은 완전히 같은 뜻이어서","mis":"M5-2-u1-X02"}],"mis":"M5-2-u1-X02","explanation":["40 이상은 40과 같거나 큰 수예요.","40 초과는 40보다 큰 수예요.","40이 들어가는지만 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_review_d#5','math',5,2,'u1','','g5_2_math_u1_review_d','unit_review','M5-2-u1-C2',1,'mc','auto','수직선에 50에 ○이 그려져 있고 거기서 왼쪽으로 선이 그어져 있어요. 수직선이 나타내는 수의 범위는 어느 것인가요?',ARRAY['M5-2-u1-X04','M5-2-u1-X03']::text[],false,'{"seq":5,"concept":"M5-2-u1-C2","difficulty":1,"kind":"mc","stem":"수직선에 50에 ○이 그려져 있고 거기서 왼쪽으로 선이 그어져 있어요. 수직선이 나타내는 수의 범위는 어느 것인가요?","options":[{"t":"50 미만인 수","correct":true},{"t":"50 이하인 수","mis":"M5-2-u1-X04"},{"t":"50 초과인 수","mis":"M5-2-u1-X03"},{"t":"50 이상인 수","mis":"M5-2-u1-X03"}],"explanation":["●은 그 수를 포함하고 ○은 포함하지 않아요.","50은 ○이라 포함하지 않아요.","그래서 50 미만인 수예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_review_d#6','math',5,2,'u1','','g5_2_math_u1_review_d','unit_review','M5-2-u1-C3',1,'mc','auto','수직선에 5에는 ○, 10에는 ○이 그려져 있고 두 점 사이가 선으로 이어져 있어요. 수직선이 나타내는 수의 범위는 어느 것인가요?',ARRAY['M5-2-u1-X04']::text[],false,'{"seq":6,"concept":"M5-2-u1-C3","difficulty":1,"kind":"mc","stem":"수직선에 5에는 ○, 10에는 ○이 그려져 있고 두 점 사이가 선으로 이어져 있어요. 수직선이 나타내는 수의 범위는 어느 것인가요?","options":[{"t":"5 초과 10 미만인 수","correct":true},{"t":"5 이상 10 미만인 수","mis":"M5-2-u1-X04"},{"t":"5 초과 10 이하인 수","mis":"M5-2-u1-X04"},{"t":"5 이상 10 이하인 수","mis":"M5-2-u1-X04"}],"explanation":["●은 그 수를 포함하고 ○은 포함하지 않아요.","5는 ○이라 포함하지 않아요 · 10은 ○이라 포함하지 않아요.","그래서 5 초과 10 미만인 수예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_review_d#7','math',5,2,'u1','','g5_2_math_u1_review_d','unit_review','M5-2-u1-C3',2,'sa','auto','1.5, 1.49, 2, 3, 2.99, 3.1 중에서 1.5 이상 3 미만인 수는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":7,"concept":"M5-2-u1-C3","difficulty":2,"kind":"sa","stem":"1.5, 1.49, 2, 3, 2.99, 3.1 중에서 1.5 이상 3 미만인 수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["3","3개"],"explanation":["1.5 이상 3 미만인 수의 뜻에 맞는지 하나씩 확인해요.","들어가는 수는 1.5, 2, 2.99예요.","모두 3개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_review_d#8','math',5,2,'u1','','g5_2_math_u1_review_d','unit_review','M5-2-u1-C3',3,'mc','auto','박물관 입장료는 13세 미만 1000원, 13세 이상 19세 미만 1500원, 19세 이상 2000원이에요. 은우(11세)와 형(19세)의 입장료는 모두 얼마인가요?',ARRAY['M5-2-u1-X02','M5-2-u1-X03','M5-2-u1-X16']::text[],false,'{"seq":8,"concept":"M5-2-u1-C3","difficulty":3,"kind":"mc","stem":"박물관 입장료는 13세 미만 1000원, 13세 이상 19세 미만 1500원, 19세 이상 2000원이에요. 은우(11세)와 형(19세)의 입장료는 모두 얼마인가요?","options":[{"t":"3000원","correct":true},{"t":"2500원","mis":"M5-2-u1-X02"},{"t":"3500원","mis":"M5-2-u1-X03"},{"t":"2000원","mis":"M5-2-u1-X16"}],"explanation":["은우 11세 — 1000원이에요.","형 19세는 「19세 이상」 — 2000원이에요.","1000 + 2000 = 3000원이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_review_d#9','math',5,2,'u1','','g5_2_math_u1_review_d','unit_review','M5-2-u1-C4',1,'mc','auto','5217을 올림하여 백의 자리까지 나타내면 얼마인가요?',ARRAY['M5-2-u1-X08','M5-2-u1-X09']::text[],false,'{"seq":9,"concept":"M5-2-u1-C4","difficulty":1,"kind":"mc","stem":"5217을 올림하여 백의 자리까지 나타내면 얼마인가요?","options":[{"t":"5300","correct":true},{"t":"5200","mis":"M5-2-u1-X08"},{"t":"5220","mis":"M5-2-u1-X09"},{"t":"6000","mis":"M5-2-u1-X09"}],"explanation":["올림은 백의 자리 아래 수(17)을 올려서 나타내요.","아래 숫자가 무엇이든 0이 아니면 한 칸 올리고, 아래는 0으로 채워요.","5217 → 5300이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_review_d#10','math',5,2,'u1','','g5_2_math_u1_review_d','unit_review','M5-2-u1-C4',2,'mc','auto','7.805를 올림하여 소수 둘째 자리까지 나타내면 얼마인가요?',ARRAY['M5-2-u1-X08','M5-2-u1-X09']::text[],false,'{"seq":10,"concept":"M5-2-u1-C4","difficulty":2,"kind":"mc","stem":"7.805를 올림하여 소수 둘째 자리까지 나타내면 얼마인가요?","options":[{"t":"7.81","correct":true},{"t":"7.80","mis":"M5-2-u1-X08"},{"t":"7.85","mis":"M5-2-u1-X09"},{"t":"7.9","mis":"M5-2-u1-X09"}],"explanation":["올림은 소수 둘째 자리 아래 수(0.005)를 올려서 나타내요.","아래 숫자가 무엇이든 0이 아니면 한 칸 올리고, 아래는 0으로 채워요.","7.805 → 7.81이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_review_d#11','math',5,2,'u1','','g5_2_math_u1_review_d','unit_review','M5-2-u1-C5',1,'mc','auto','8359를 버림하여 천의 자리까지 나타내면 얼마인가요?',ARRAY['M5-2-u1-X08','M5-2-u1-X09']::text[],false,'{"seq":11,"concept":"M5-2-u1-C5","difficulty":1,"kind":"mc","stem":"8359를 버림하여 천의 자리까지 나타내면 얼마인가요?","options":[{"t":"8000","correct":true},{"t":"9000","mis":"M5-2-u1-X08"},{"t":"8300","mis":"M5-2-u1-X09"},{"t":"8350","mis":"M5-2-u1-X09"}],"explanation":["버림은 천의 자리 아래 수(359)를 어떤 수든 버려요.","버린 자리는 0으로 채우거나(자연수) 지워요(소수).","8359 → 8000이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_review_d#12','math',5,2,'u1','','g5_2_math_u1_review_d','unit_review','M5-2-u1-C5',2,'sa','auto','구슬 836개를 한 봉지에 10개씩 담아요. 구슬을 담은 봉지는 최대 몇 봉지인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":12,"concept":"M5-2-u1-C5","difficulty":2,"kind":"sa","stem":"구슬 836개를 한 봉지에 10개씩 담아요. 구슬을 담은 봉지는 최대 몇 봉지인가요? 숫자로 쓰세요.","answer":["83","83봉지"],"explanation":["묶음이 다 차야 하나로 셀 수 있어요.","836을 버림하여 십의 자리까지 → 830개예요.","830개는 83봉지예요. 남는 것은 버려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_review_d#13','math',5,2,'u1','','g5_2_math_u1_review_d','unit_review','M5-2-u1-C6',1,'mc','auto','2449를 반올림하여 백의 자리까지 나타내면 얼마인가요?',ARRAY['M5-2-u1-X10','M5-2-u1-X09']::text[],false,'{"seq":13,"concept":"M5-2-u1-C6","difficulty":1,"kind":"mc","stem":"2449를 반올림하여 백의 자리까지 나타내면 얼마인가요?","options":[{"t":"2400","correct":true},{"t":"2500","mis":"M5-2-u1-X10"},{"t":"2450","mis":"M5-2-u1-X09"},{"t":"2000","mis":"M5-2-u1-X09"}],"explanation":["반올림은 구하려는 자리 바로 아래 한 자리만 봐요.","백의 자리 바로 아래 숫자가 4라 버려요.","2449 → 2400이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_review_d#14','math',5,2,'u1','','g5_2_math_u1_review_d','unit_review','M5-2-u1-C6',2,'mc','auto','5.602를 반올림하여 소수 첫째 자리까지 나타내면 얼마인가요?',ARRAY['M5-2-u1-X08','M5-2-u1-X09','M5-2-u1-X16']::text[],false,'{"seq":14,"concept":"M5-2-u1-C6","difficulty":2,"kind":"mc","stem":"5.602를 반올림하여 소수 첫째 자리까지 나타내면 얼마인가요?","options":[{"t":"5.6","correct":true},{"t":"5.7","mis":"M5-2-u1-X08"},{"t":"6","mis":"M5-2-u1-X09"},{"t":"5.8","mis":"M5-2-u1-X16"}],"explanation":["반올림은 구하려는 자리 바로 아래 한 자리만 봐요.","소수 첫째 자리 바로 아래 숫자가 0이라 버려요.","5.602 → 5.6이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_review_d#15','math',5,2,'u1','','g5_2_math_u1_review_d','unit_review','M5-2-u1-C6',3,'mc','auto','반올림하여 십의 자리까지 나타낸 수가 650이에요. 65□의 □에 들어갈 수 있는 수를 모두 고른 것은 어느 것인가요?',ARRAY['M5-2-u1-X08','M5-2-u1-X16','M5-2-u1-X11']::text[],false,'{"seq":15,"concept":"M5-2-u1-C6","difficulty":3,"kind":"mc","stem":"반올림하여 십의 자리까지 나타낸 수가 650이에요. 65□의 □에 들어갈 수 있는 수를 모두 고른 것은 어느 것인가요?","options":[{"t":"0, 1, 2, 3, 4","correct":true},{"t":"5, 6, 7, 8, 9","mis":"M5-2-u1-X08"},{"t":"1, 2, 3, 4","mis":"M5-2-u1-X16"},{"t":"0, 1, 2, 3, 4, 5","mis":"M5-2-u1-X11"}],"explanation":["일의 자리 □를 봐요.","650이 되려면 버려야 하니 □는 0~4예요.","5~9면 660이 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_review_d#16','math',5,2,'u1','','g5_2_math_u1_review_d','unit_review','M5-2-u1-C4',3,'mc','auto','올림하여 백의 자리까지 나타내면 500이 되는 자연수 중에서 가장 작은 수는 얼마인가요?',ARRAY['M5-2-u1-X07','M5-2-u1-X08','M5-2-u1-X17']::text[],false,'{"seq":16,"concept":"M5-2-u1-C4","difficulty":3,"kind":"mc","stem":"올림하여 백의 자리까지 나타내면 500이 되는 자연수 중에서 가장 작은 수는 얼마인가요?","options":[{"t":"401","correct":true},{"t":"400","mis":"M5-2-u1-X07"},{"t":"450","mis":"M5-2-u1-X08"},{"t":"499","mis":"M5-2-u1-X17"}],"explanation":["400은 올림해도 400 — 빠져요.","401은 아래 01을 올려 500이 돼요.","그래서 가장 작은 수는 401이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_review_d#17','math',5,2,'u1','','g5_2_math_u1_review_d','unit_review','M5-2-u1-C7',1,'mc','auto','필통값 11200원을 지폐로만 낼 돈을 정할 때 알맞은 어림 방법은 어느 것인가요?',ARRAY['M5-2-u1-X13']::text[],false,'{"seq":17,"concept":"M5-2-u1-C7","difficulty":1,"kind":"mc","stem":"필통값 11200원을 지폐로만 낼 돈을 정할 때 알맞은 어림 방법은 어느 것인가요?","options":[{"t":"올림","correct":true},{"t":"버림","mis":"M5-2-u1-X13"},{"t":"반올림","mis":"M5-2-u1-X13"},{"t":"아무 방법이나 좋다","mis":"M5-2-u1-X13"}],"explanation":["모자라게 내면 살 수 없어요.","모자라지 않게 크게 어림해요.","그래서 올림이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_review_d#18','math',5,2,'u1','','g5_2_math_u1_review_d','unit_review','M5-2-u1-C7',2,'mc','auto','동전 26300원을 10000원짜리 지폐로만 바꾼다면 최대 얼마까지 바꿀 수 있나요?',ARRAY['M5-2-u1-X13','M5-2-u1-X09','M5-2-u1-X17']::text[],false,'{"seq":18,"concept":"M5-2-u1-C7","difficulty":2,"kind":"mc","stem":"동전 26300원을 10000원짜리 지폐로만 바꾼다면 최대 얼마까지 바꿀 수 있나요?","options":[{"t":"20000원","correct":true},{"t":"30000원","mis":"M5-2-u1-X13"},{"t":"26000원","mis":"M5-2-u1-X09"},{"t":"26300원","mis":"M5-2-u1-X17"}],"explanation":["10000원이 다 차야 한 장이에요.","26300을 버림하여 만의 자리까지 나타내요.","20000원이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_review_d#19','math',5,2,'u1','','g5_2_math_u1_review_d','unit_review','M5-2-u1-C7',3,'mc','auto','어림한 방법이 다른 친구는 누구인가요? 가온 — 「키 142.6 cm를 실제와 가깝게 143 cm로 적어요.」 나래 — 「관람객 5813명을 약 5800명이라고 말해요.」 다솔 — 「동전 58600원을 1000원짜리로 58000원까지 바꿔요.」',ARRAY['M5-2-u1-X13']::text[],false,'{"seq":19,"concept":"M5-2-u1-C7","difficulty":3,"kind":"mc","stem":"어림한 방법이 다른 친구는 누구인가요? 가온 — 「키 142.6 cm를 실제와 가깝게 143 cm로 적어요.」 나래 — 「관람객 5813명을 약 5800명이라고 말해요.」 다솔 — 「동전 58600원을 1000원짜리로 58000원까지 바꿔요.」","options":[{"t":"다솔","correct":true},{"t":"가온","mis":"M5-2-u1-X13"},{"t":"나래","mis":"M5-2-u1-X13"},{"t":"모두 같다","mis":"M5-2-u1-X13"}],"explanation":["가온·나래는 실제와 가깝게 — 반올림이에요.","다솔은 남는 600원을 버렸어요 — 버림이에요.","그래서 다른 친구는 다솔이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_review_d#20','math',5,2,'u1','','g5_2_math_u1_review_d','unit_review','M5-2-u1-C8',2,'sa','auto','고춧가루 220 g이 필요한데 100 g씩 한 봉지로 팔아요. 몇 봉지를 사야 하나요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":20,"concept":"M5-2-u1-C8","difficulty":2,"kind":"sa","stem":"고춧가루 220 g이 필요한데 100 g씩 한 봉지로 팔아요. 몇 봉지를 사야 하나요? 숫자로 쓰세요.","answer":["3","3봉지"],"explanation":["2봉지는 200 g이라 20 g이 모자라요.","모자라면 요리를 못 하니 올림이에요.","220 g → 300 g, 3봉지예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_review_d#21','math',5,2,'u1','','g5_2_math_u1_review_d','unit_review','M5-2-u1-C8',3,'mc','auto','피자 재료 — 밀가루 2300 g(1000 g 한 봉지 2800원) · 치즈 1350 g(500 g 한 봉지 6400원). 구입할 양은 올림으로 정하고 가격은 반올림하여 천의 자리까지 나타내 어림셈하면 구입 비용은 약 얼마인가요?',ARRAY['M5-2-u1-X13','M5-2-u1-X17','M5-2-u1-X08']::text[],false,'{"seq":21,"concept":"M5-2-u1-C8","difficulty":3,"kind":"mc","stem":"피자 재료 — 밀가루 2300 g(1000 g 한 봉지 2800원) · 치즈 1350 g(500 g 한 봉지 6400원). 구입할 양은 올림으로 정하고 가격은 반올림하여 천의 자리까지 나타내 어림셈하면 구입 비용은 약 얼마인가요?","options":[{"t":"27000원","correct":true},{"t":"24000원","mis":"M5-2-u1-X13"},{"t":"27600원","mis":"M5-2-u1-X17"},{"t":"30000원","mis":"M5-2-u1-X08"}],"explanation":["밀가루 2300 g → 3봉지, 치즈 1350 g → 3봉지예요.","어림 가격 — 밀가루 3000원, 치즈 6000원이에요.","3000 × 3 + 6000 × 3 = 9000 + 18000 = 27000원이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_review_d#22','math',5,2,'u1','','g5_2_math_u1_review_d','unit_review','M5-2-u1-C5',3,'mc','auto','수 카드 2, 7, 5, 3을 한 번씩만 써서 가장 작은 네 자리 수를 만들었어요. 그 수를 버림하여 십의 자리까지 나타내면 얼마인가요?',ARRAY['M5-2-u1-X08','M5-2-u1-X09','M5-2-u1-X12']::text[],false,'{"seq":22,"concept":"M5-2-u1-C5","difficulty":3,"kind":"mc","stem":"수 카드 2, 7, 5, 3을 한 번씩만 써서 가장 작은 네 자리 수를 만들었어요. 그 수를 버림하여 십의 자리까지 나타내면 얼마인가요?","options":[{"t":"2350","correct":true},{"t":"2360","mis":"M5-2-u1-X08"},{"t":"2300","mis":"M5-2-u1-X09"},{"t":"235","mis":"M5-2-u1-X12"}],"explanation":["수 카드로 만든 수는 2357이에요.","버림은 십의 자리 아래 수(7)을 어떤 수든 버려요.","2357 → 2350이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_review_d#23','math',5,2,'u1','','g5_2_math_u1_review_d','unit_review','M5-2-u1-C3',4,'essay','teacher','어린이 감기약 용량표 — 4세 이상 7세 미만 한 번에 5 mL · 7세 이상 11세 미만 7.5 mL · 11세 이상 15세 미만 10 mL. 7세 어린이는 몇 mL를 먹어야 하는지 쓰고, 표에서 7세가 두 줄에 모두 들어가지 않는 까닭을 설명하세요.','{}'::text[],false,'{"seq":23,"concept":"M5-2-u1-C3","difficulty":4,"kind":"essay","stem":"어린이 감기약 용량표 — 4세 이상 7세 미만 한 번에 5 mL · 7세 이상 11세 미만 7.5 mL · 11세 이상 15세 미만 10 mL. 7세 어린이는 몇 mL를 먹어야 하는지 쓰고, 표에서 7세가 두 줄에 모두 들어가지 않는 까닭을 설명하세요.","answer_guide":{"answer":"예: 7.5 mL. 7세는 「4세 이상 7세 미만」에서는 미만이라 빠지고 「7세 이상 11세 미만」에는 이상이라 들어간다. 경곗값을 한쪽에만 넣어 두 줄이 겹치지 않는다.","scoring_points":["7.5 mL를 구했는가","7세가 미만 줄에서 빠지고 이상 줄에 듦을 썼는가","경곗값을 한쪽에만 넣었다는 까닭을 썼는가"]},"explanation":["7세는 「7세 이상」 줄에 들어가요.","「7세 미만」 줄에서는 빠져요.","그래서 7.5 mL이고, 두 줄은 겹치지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_review_d#24','math',5,2,'u1','','g5_2_math_u1_review_d','unit_review','M5-2-u1-C7',4,'essay','teacher','부산광역시 인구 3259219명을 그래프로 나타낼 때 올림·버림·반올림 중 어느 방법이 알맞은지 쓰고, 만의 자리까지 나타낸 값과 함께 까닭을 설명하세요.','{}'::text[],false,'{"seq":24,"concept":"M5-2-u1-C7","difficulty":4,"kind":"essay","stem":"부산광역시 인구 3259219명을 그래프로 나타낼 때 올림·버림·반올림 중 어느 방법이 알맞은지 쓰고, 만의 자리까지 나타낸 값과 함께 까닭을 설명하세요.","answer_guide":{"answer":"예: 반올림이 알맞다. 반올림하여 만의 자리까지 나타내면 3260000명으로, 올림(3260000)이나 버림(3250000)보다 실제와 차이가 작게 어림하는 방법이기 때문이다. 그래프는 실제와 가깝게 나타내야 한다.","scoring_points":["반올림을 골랐는가","3260000명을 구했는가","실제와 차이가 작아야 한다는 까닭을 썼는가"]},"explanation":["그래프는 실제와 가까워야 해요.","반올림하여 만의 자리까지 → 3260000명이에요.","그래서 반올림이 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u1_review_d#25','math',5,2,'u1','','g5_2_math_u1_review_d','unit_review','M5-2-u1-C8',4,'essay','teacher','피자를 만들려면 토마토소스 2 L와 치즈 1350 g이 필요해요. 토마토소스는 1 L씩, 치즈는 500 g씩 팔 때 각각 몇 봉지를 사야 하는지 구하고, 토마토소스는 올림해도 그대로인 까닭을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"M5-2-u1-C8","difficulty":4,"kind":"essay","stem":"피자를 만들려면 토마토소스 2 L와 치즈 1350 g이 필요해요. 토마토소스는 1 L씩, 치즈는 500 g씩 팔 때 각각 몇 봉지를 사야 하는지 구하고, 토마토소스는 올림해도 그대로인 까닭을 쓰세요.","answer_guide":{"answer":"예: 토마토소스 2봉지, 치즈 3봉지. 치즈는 2봉지 1000 g이면 모자라 3봉지를 산다. 토마토소스 2 L는 1 L씩 딱 나누어져 올릴 것이 없어 그대로 2봉지다.","scoring_points":["토마토소스 2봉지를 구했는가","치즈 3봉지를 구했는가","딱 나누어져 올릴 것이 없다는 까닭을 썼는가"]},"explanation":["치즈 1350 g → 3봉지 1500 g이에요.","토마토소스 2 L → 2봉지예요.","아래 수가 0이면 올리지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
